    platform::write_u32(this, U8_TABLE_VTABLE as u32);
    platform::write_u32(this + 0x24, 0);
    platform::write_u32(this + U8_TABLE_LIST, (this + U8_TABLE_LIST) as u32);
    platform::write_u32(this + 0x2C, (this + U8_TABLE_LIST) as u32);
    this
