/// Builds the EGG root heaps for MEM1, MEM2, the debug region and the system.
///
/// The routine reads the four arena bounds, aligns them, records them in the
/// root-heap descriptor, installs them back through the arena setters, then
/// creates one heap per range through [`fn_802b9360`] and one system heap
/// through [`fn_802b9430`]. The last 64 MiB of MEM2 becomes the debug heap when
/// MEM2 is large enough.
///
/// # Original
/// - Ghidra: `FUN_802ba870` at `0x802BA870` (372 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802ba870_FUN_802ba870.c`
/// - observed: `iVar1 = FUN_802dcd70();` (register-save stub, so `iVar1` is the
///   incoming `r3`), four `FUN_801abe..` getters, seven stores into `+0x04`,
///   `+0x08`, `+0x0C`, `+0x10`, `+0x14`, `+0x2C`, `+0x30`, four arena setters,
///   `FUN_802b8b40()`, the MEM2 split at `0x4000000`, three `FUN_802b9360`
///   calls tagged with `s_EGGRootMEM1/MEM2/Debug`, one `FUN_802b9430` tagged
///   `s_EGGSystem`, and `FUN_802b9170(system)`.
/// - `// inferred:` the getter/setter pairs are arena bounds; `+0x34` holds the
///   parent heap handed to the system-heap factory.
///
/// # Arguments
/// - `root`: EGG root-heap descriptor (0x38 bytes).
///
/// # Returns
/// `()`.
///
/// # Side effects
/// Programs the arena registers, initialises the heap list, creates up to four
/// heaps, stamps their `+0x34` names and makes the system heap current.
///
/// # Safety
/// `root` must be a writable descriptor; the arena calls must be made once,
/// during startup, before any archive allocation.
///
/// # Confidence
/// medium - every store and call is literal; the meaning of the arena
/// getters/setters and of `+0x34` is inferred from their pairing.
pub unsafe fn fn_802ba870(root: usize) {
    let mem1_lo = call0_u32(ARENA_GET_1);
    let mem1_hi = call0_u32(ARENA_GET_2);
    let mem2_lo = call0_u32(ARENA_GET_3);
    let mem2_hi = call0_u32(ARENA_GET_4);

    let mem1_lo = mem1_lo.wrapping_add(0x1F) & 0xFFFF_FFE0;
    let mem1_hi = mem1_hi & 0xFFFF_FFE0;
    let mem2_hi = mem2_hi & 0xFFFF_FFE0;

    platform::write_u32(root + 0x2C, 0x8000_0000);
    platform::write_u32(root + 0x30, mem1_lo);
    platform::write_u32(root + 0x04, mem1_lo);
    platform::write_u32(root + 0x08, mem1_hi);
    platform::write_u32(root + 0x0C, mem2_lo.wrapping_add(0x1F) & 0xFFFF_FFE0);
    platform::write_u32(root + 0x10, mem2_hi);
    platform::write_u32(root + 0x14, platform::read_u32(OS_PHYSICAL_MEM1_SIZE));

    // observed: both setters of each pair receive the same bound.
    platform::call1(ARENA_SET_2A, mem1_hi);
    platform::call1(ARENA_SET_2B, mem1_hi);
    platform::call1(ARENA_SET_4A, mem2_hi);
    platform::call1(ARENA_SET_4B, mem2_hi);

    fn_802b8b40();

    let mem2_base = platform::read_u32(root + 0x0C);
    let mut mem2_size = platform::read_u32(root + 0x10).wrapping_sub(mem2_base);
    let debug_size;
    if mem2_size < 0x0400_0000 {
        debug_size = 0u32;
    } else {
        debug_size = 0x0400_0000u32;
        mem2_size = mem2_size.wrapping_add(0xFC00_0000) & 0xFFFF_FFE0;
    }

    let mem1_base = platform::read_u32(root + 0x04);
    let mem1_size = platform::read_u32(root + 0x08).wrapping_sub(mem1_base);
    let mem1_heap = fn_802b9360(mem1_base as usize, mem1_size, 0);
    platform::write_u32(root + 0x18, mem1_heap);
    platform::write_u32(mem1_heap as usize + 0x34, STR_EGGROOT_MEM1 as u32);

    let mem2_heap = fn_802b9360(mem2_base as usize, mem2_size, 0);
    platform::write_u32(root + 0x1C, mem2_heap);
    platform::write_u32(mem2_heap as usize + 0x34, STR_EGGROOT_MEM2 as u32);

    if debug_size == 0 {
        platform::write_u32(root + 0x20, 0);
    } else {
        let debug_base = mem2_base.wrapping_add(mem2_size);
        let debug_heap = fn_802b9360(debug_base as usize, debug_size, 0);
        platform::write_u32(root + 0x20, debug_heap);
        platform::write_u32(debug_heap as usize + 0x34, STR_EGGROOT_DEBUG as u32);
    }

    let parent = platform::read_u32(root + 0x34);
    let system_heap = fn_802b9430(parent, mem1_heap as usize, 0);
    platform::write_u32(root + 0x24, system_heap);
    platform::write_u32(system_heap as usize + 0x34, STR_EGGROOT_SYSTEM as u32);
    arc_heap_exchange_current(system_heap as usize);
}

