const FN_802290C0: usize = 0x8022_90C0;

/// `0x8034FF88` - vtable installed by the 0x1C-byte list-header pair.
const VT_802BDD00: usize = 0x8034_FF88;
/// `0x8034FF94` - vtable installed by each 0x28-byte queue node.
const VT_802BDB40: usize = 0x8034_FF94;

/// `r2 - 0x3FC0` -> `0x8042F0C0`: zero/default word used for section entries.
const SDA2_SECTION_DEFAULT: usize = SDA2_BASE - 0x3FC0;
/// `r2 - 0x3F10` -> `0x8042F170`: 0.0f constant used by the queue nodes.
const SDA2_FLOAT_ZERO: usize = SDA2_BASE - 0x3F10;
/// `r2 - 0x3F08` -> `0x8042F178`: 1.0f constant used by the queue stepper.
const SDA2_FLOAT_ONE: usize = SDA2_BASE - 0x3F08;
/// `r2 - 0x3F04` -> `0x8042F17C`: inert step value returned by a disabled node.
const SDA2_QUEUE_INERT: usize = SDA2_BASE - 0x3F04;
/// `r2 - 0x3EF8` -> `0x8042F188`: default half-extent of the quad initialiser.
const SDA2_QUAD_EXTENT: usize = SDA2_BASE - 0x3EF8;
/// `r13 - 0x4870` -> `0x8042E810`: the current archive heap.
const SDA_CURRENT_HEAP: usize = SDA_BASE - 0x4870;

/// `r2 - 0x3458` -> `0x8042FC28`: four default halfwords of the RLYT record.
const SDA2_RLYT_DEFAULTS: usize = SDA2_BASE - 0x3458;

/// Resets an RLYT record header to its defaults and clears both counters.
///
/// Four halfwords are copied from the `r2` small-data defaults, the eight
/// colour/extent halfwords at `+0x18..+0x26` become `0xFF`, both packed
/// counters keep only their low five bits and the section base is cleared.
///
/// # Original
/// - Ghidra: `FUN_802b2b50` at `0x802B2B50` (112 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802b2b50_FUN_802b2b50.c`
/// - observed: `*(undefined2 *)(param_1 + 0x10) = *(undefined2 *)(r2 - 0x3458);`
///   ... four default halfwords, eight `0xFF` halfwords, `0x38 &= 0x1f`,
///   `0x3c &= 0x1f`, `+0x59 = 0`, `+0x40 = 0`.
///
/// # Arguments
/// - `this`: RLYT record whose header is reset (at least 0x5A bytes).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x10..+0x26`, masks `+0x38` and `+0x3C`, clears `+0x59` and
/// `+0x40`.
///
/// # Safety
/// `this` must be writable for the full record.
///
/// # Confidence
/// high - every field and default halfword is literal; only the meaning of the
/// defaults is `// unknown:`.
pub unsafe fn fn_802b2b50(this: usize) {
    platform::write_u16(this + 0x10, platform::read_u16(SDA2_RLYT_DEFAULTS));
    platform::write_u16(this + 0x12, platform::read_u16(SDA2_RLYT_DEFAULTS + 2));
    platform::write_u16(this + 0x14, platform::read_u16(SDA2_RLYT_DEFAULTS + 4));
    platform::write_u16(this + 0x16, platform::read_u16(SDA2_RLYT_DEFAULTS + 6));
    for slot in 0..8usize {
        platform::write_u16(this + 0x18 + slot * 2, 0xFF);
    }
    platform::write_u32(this + 0x38, platform::read_u32(this + 0x38) & 0x1F);
    platform::write_u32(this + 0x3C, platform::read_u32(this + 0x3C) & 0x1F);
    platform::write_u8(this + 0x59, 0);
    platform::write_u32(this + 0x40, 0);
}

/// Grows the 0x1C-byte section array to `count` entries.
///
/// New entries start zeroed except for the two default words copied from
/// `SDA2_SECTION_DEFAULT` and the flags `0x180000` in the low 19-bit field.
///
/// # Original
/// - Ghidra: `FUN_802b3620` at `0x802B3620` (144 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802b3620_FUN_802b3620.c`
/// - observed: `uVar2 = *(uint *)(param_1 + 0x3c) >> 0x1c; ... p[6] = p[6] &
///   0x81fff | 0x180000; *(uint *)(param_1 + 0x3c) = param_2 << 0x1c | ...
///   & 0xfffffff;`
///
/// # Arguments
/// - `this`: object holding the packed count at `+0x3C` and base at `+0x40`.
/// - `count`: new number of 0x1C-byte entries.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Initialises entries `old..count` and rewrites the count field of `+0x3C`.
///
/// # Safety
/// `this + 0x40` must point to room for `count` entries of 0x1C bytes.
///
/// # Confidence
/// high - the bitfield, row stride and all seven field stores are literal.
pub unsafe fn fn_802b3620(this: usize, count: u32) {
    let key = platform::read_u32(this + 0x3C);
    let old = key >> 28;
    if count != 0 {
        let default_word = platform::read_u32(SDA2_SECTION_DEFAULT);
        let mut entry = platform::read_u32(this + 0x40) as usize + old as usize * 0x1C;
        if old < count {
            let mut remaining = count.wrapping_sub(old) as i32;
            loop {
                platform::write_u32(entry, 0);
                platform::write_u16(entry + 0x08, 0);
                platform::write_u16(entry + 0x0A, 0);
                platform::write_u32(entry + 0x0C, default_word);
                platform::write_u32(entry + 0x10, default_word);
                platform::write_u16(entry + 0x14, 0);
                platform::write_u32(entry + 0x04, 0);
                platform::write_u32(
                    entry + 0x18,
                    (platform::read_u32(entry + 0x18) & 0x81FFF) | 0x180000,
                );
                platform::write_u16(entry + 0x16, 0);
                entry += 0x1C;
                remaining -= 1;
                if remaining == 0 {
                    break;
                }
            }
        }
    }
    platform::write_u32(this + 0x3C, (count << 28) | (key & 0x0FFF_FFFF));
}

/// Grows the 4-byte sub-array to `count` entries.
///
/// Each new entry is `{1, 4, 0x3C, 0}`; the target address is built from the
/// packed `+0x38`/`+0x3C` bitfields exactly as printed.
///
/// # Original
/// - Ghidra: `FUN_802b36b0` at `0x802B36B0` (136 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802b36b0_FUN_802b36b0.c`
/// - observed: `(*(uint *)(param_1 + 0x3c) >> 0x12 & 0x3c) +
///   (*(uint *)(param_1 + 0x38) >> 0x1c) * 0x1c + base` ... three byte stores
///   `1, 4, 0x3c`, then `+0x3c = (param_2 & 0xf) << 0x14 | ... & 0xff0fffff`.
///
/// # Arguments
/// - `this`: section owner.
/// - `count`: new number of 4-byte entries.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes entries `old..count` and the `bits 20..23` count field.
///
/// # Safety
/// The computed base must have room for `count` 4-byte entries.
///
/// # Confidence
/// high - the address arithmetic and the four stores are literal.
pub unsafe fn fn_802b36b0(this: usize, count: u32) {
    let key = platform::read_u32(this + 0x3C);
    let summary = platform::read_u32(this + 0x38);
    let old = (key >> 20) & 0xF;
    if count != 0 {
        let mut entry = ((key >> 18) & 0x3C) as usize
            + (summary >> 28) as usize * 0x1C
            + platform::read_u32(this + 0x40) as usize
            + ((summary >> 24) & 0xF) as usize * 0x14;
        if old < count {
            let mut remaining = count.wrapping_sub(old) as i32;
            loop {
                platform::write_u8(entry + 3, 0);
                platform::write_u8(entry, 1);
                platform::write_u8(entry + 1, 4);
                platform::write_u8(entry + 2, 0x3C);
                entry += 4;
                remaining -= 1;
                if remaining == 0 {
                    break;
                }
            }
        }
    }
    platform::write_u32(this + 0x3C, ((count & 0xF) << 20) | (key & 0xFF0F_FFFF));
}

/// Grows the 0x10-byte sub-array to `count` entries with `0xFF` defaults.
///
/// # Original
/// - Ghidra: `FUN_802b3740` at `0x802B3740` (292 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802b3740_FUN_802b3740.c`
/// - observed: the eleven constants `0xff, 4, 0xff, 0, 0xff, 0xaf, 0x77,
///   0x57, 0, 0x61, 0, 0x81, 0, 0, 0, 0` written per 0x10-byte entry; then
///   `+0x3c = (param_2 & 0x1f) << 9 | ... & 0xffffc1ff`.
///
/// # Arguments
/// - `this`: section owner.
/// - `count`: new number of 0x10-byte entries.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes entries `old..count` and the `bits 9..13` count field.
///
/// # Safety
/// The computed base must have room for `count` entries of 0x10 bytes.
///
/// # Confidence
/// high - every constant and term of the address expression is literal.
pub unsafe fn fn_802b3740(this: usize, count: u32) {
    let key = platform::read_u32(this + 0x3C);
    let summary = platform::read_u32(this + 0x38);
    let old = (key >> 9) & 0x1F;
    if count != 0 {
        let mut entry = ((key >> 5) & 0x1F0) as usize
            + ((summary >> 3) & 4) as usize
            + ((summary >> 13) & 0x1C) as usize
            + platform::read_u32(this + 0x40) as usize
            + (((summary >> 18) & 3) + ((summary >> 24) & 0xF)) as usize * 0x14
            + (summary >> 28) as usize * 0x1C
            + ((summary >> 4) & 4) as usize
            + ((summary >> 12) & 4) as usize
            + ((summary >> 5) & 4) as usize
            + ((summary >> 18) & 0x3C) as usize
            + ((summary >> 6) & 4) as usize;
        if old < count {
            let mut remaining = count.wrapping_sub(old) as i32;
            loop {
                platform::write_u8(entry, 0xFF);
                platform::write_u8(entry + 1, 4);
                platform::write_u8(entry + 2, 0xFF);
                platform::write_u8(entry + 3, 0);
                platform::write_u8(entry + 4, 0xFF);
                platform::write_u8(entry + 5, 0xAF);
                platform::write_u8(entry + 8, 0x77);
                platform::write_u8(entry + 9, 0x57);
                platform::write_u8(entry + 6, 0);
                platform::write_u8(entry + 7, 0x61);
                platform::write_u8(entry + 10, 0);
                platform::write_u8(entry + 11, 0x81);
                platform::write_u8(entry + 12, 0);
                platform::write_u8(entry + 13, 0);
                platform::write_u8(entry + 14, 0);
                platform::write_u8(entry + 15, 0);
                entry += 0x10;
                remaining -= 1;
                if remaining == 0 {
                    break;
                }
            }
        }
    }
    platform::write_u32(this + 0x3C, ((count & 0x1F) << 9) | (key & 0xFFFF_C1FF));
}

/// Grows the zeroed 4-byte sub-array to `count` entries.
///
/// # Original
/// - Ghidra: `FUN_802b3870` at `0x802B3870` (196 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802b3870_FUN_802b3870.c`
/// - observed: four zero byte stores per 4-byte entry; then
///   `+0x3c = (param_2 & 7) << 0xf | ... & 0xfffc7fff`.
///
/// # Arguments
/// - `this`: section owner.
/// - `count`: new number of 4-byte entries.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Zeroes entries `old..count` and writes the `bits 15..17` count field.
///
/// # Safety
/// The computed base must have room for `count` 4-byte entries.
///
/// # Confidence
/// high - the address terms and the four stores are literal.
pub unsafe fn fn_802b3870(this: usize, count: u32) {
    let key = platform::read_u32(this + 0x3C);
    let summary = platform::read_u32(this + 0x38);
    let old = (key >> 15) & 7;
    if count != 0 {
        let mut entry = ((key >> 13) & 0x1C) as usize
            + ((summary >> 3) & 4) as usize
            + ((summary >> 12) & 4) as usize
            + ((summary >> 18) & 0x3C) as usize
            + ((summary >> 4) & 4) as usize
            + ((summary >> 5) & 4) as usize
            + ((summary >> 6) & 4) as usize
            + platform::read_u32(this + 0x40) as usize
            + ((summary >> 24) & 0xF) as usize * 0x14
            + (summary >> 28) as usize * 0x1C;
        if old < count {
            let mut remaining = count.wrapping_sub(old) as i32;
            loop {
                platform::write_u32(entry, 0);
                entry += 4;
                remaining -= 1;
                if remaining == 0 {
                    break;
                }
            }
        }
    }
    platform::write_u32(this + 0x3C, ((count & 7) << 15) | (key & 0xFFFC_7FFF));
}

/// Stores one packed colour/extent field selected by a staged index.
///
/// Three index ranges are handled: `0x10..0x1F` addresses the 4-byte rows at
/// `+0x28`, `4..0x0F` the halfword rows at `+0x10`, and `0..3` the colour bytes
/// of the `+0x40` entry when bit 7 of `+0x3C` is set.
///
/// # Original
/// - Ghidra: `FUN_802b3940` at `0x802B3940` (440 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802b3940_FUN_802b3940.c`
/// - observed: the `(param_2 - 0x10) < 0x10`, `(param_2 - 4) <= 0xb` and
///   `3 < param_2` guards; the clamp `param_3 & ~((int)param_3 >> 0x1f)`
///   followed by `if ((short)param_3 < 0x100)`, and the four byte stores at
///   `+0x28..+0x2B`.
///
/// # Arguments
/// - `this`: section owner.
/// - `index`: packed field index.
/// - `value`: byte value (byte ranges) or halfword value (halfword range).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes exactly one byte or halfword in the selected row.
///
/// # Safety
/// The selected row must be writable.
///
/// # Confidence
/// high - every guard, clamp and store is literal; the semantic names of the
/// three index ranges are `// inferred:` from their strides.
pub unsafe fn fn_802b3940(this: usize, index: u32, value: u32) {
    let clamp_byte = |raw: u32| -> u8 {
        let positive = raw & !((raw as i32 >> 31) as u32);
        if (positive as u16 as i16) < 0x100 {
            positive as u8
        } else {
            0xFF
        }
    };

    let shifted = index.wrapping_sub(0x10);
    if shifted < 0x10 {
        let row = (shifted >> 2) as usize;
        let column = (shifted & 3) as usize;
        platform::write_u8(this + row * 4 + 0x28 + column, clamp_byte(value));
        return;
    }

    let halfword_slot = index.wrapping_sub(4);
    if halfword_slot < 0xC {
        let row = (halfword_slot >> 2) as usize;
        let column = (halfword_slot & 3) as usize;
        platform::write_u16(this + row * 8 + 0x10 + column * 2, value as u16);
        return;
    }

    if index > 3 {
        return;
    }
    let key = platform::read_u32(this + 0x3C);
    if (key >> 7) & 1 == 0 {
        return;
    }
    let summary = platform::read_u32(this + 0x38);
    let entry = ((summary >> 24) & 0xF) as usize * 0x14
        + (summary >> 28) as usize * 0x1C
        + platform::read_u32(this + 0x40) as usize
        + ((summary >> 6) & 4) as usize
        + ((summary >> 18) & 0x3C) as usize;
    platform::write_u8(entry + (index & 3) as usize, clamp_byte(value));
}

/// Releases every entry of one registered list, optionally filtered by key.
///
/// Walks the sentinel ring at `this + 4`; an entry is unlinked through
/// `0x802290C0` when `filter` is zero or equals the entry key at `+0x08`, and
/// its tail (`+0x08`, `+0x0C`, `+0x0E`) is cleared.
///
/// # Original
/// - Ghidra: `FUN_802b6320` at `0x802B6320` (132 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802b6320_FUN_802b6320.c`
/// - observed: `puVar2 = *(undefined4 **)(iVar1 + 4); ... if (((int)uVar4 == 0)
///   || (puVar3[2] == (int)uVar4)) { local_28[0] = puVar3; FUN_802290c0(...);
///   puVar3[2] = 0; *(undefined2 *)(puVar3 + 3) = 0;
///   *(undefined1 *)((int)puVar3 + 0xe) = 0; }`
/// - `// inferred:` `0x802DCD70` is the register-save prologue; its high word
///   is the incoming `r3` (`this`) and its low word the incoming `r4`
///   (`filter`).
///
/// # Arguments
/// - `this`: owner whose `+0x04` word is the ring sentinel.
/// - `filter`: zero for every entry, otherwise the key to match.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Unlinks and clears every selected entry.
///
/// # Safety
/// The ring and the unlink helper must be valid.
///
/// # Confidence
/// medium - the walk, filter and three clears are literal; the two arguments
/// are recovered from the save prologue.
pub unsafe fn fn_802b6320(this: usize, filter: u32) {
    let sentinel = this + 4;
    let mut node = platform::read_u32(sentinel) as usize;
    while node != sentinel {
        let next = platform::read_u32(node) as usize;
        let key = platform::read_u32(node + 0x08);
        if filter == 0 || key == filter {
            let mut slot = node as u32;
            platform::call2(FN_802290C0, this as u32, &mut slot as *mut u32 as u32);
            platform::write_u32(node + 0x08, 0);
            platform::write_u16(node + 0x0C, 0);
            platform::write_u8(node + 0x0E, 0);
        }
        node = next;
    }
}

/// Tests whether a scaled-colour handle still carries usable data.
///
/// Returns 1 for any mode except `0xFF`; for mode `0xFF` it returns 0 only when
/// the handle is null or all four of its words are `-1`.
///
/// # Original
/// - Ghidra: `FUN_802b6ae0` at `0x802B6AE0` (104 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802b6ae0_FUN_802b6ae0.c`
/// - observed: `if (param_2 != 0xff) return 1; if (param_1 != 0 && (((*p != -1
///   || p[1] != -1) || p[2] != -1) || p[3] != -1)) return 1; return 0;`
///
/// # Arguments
/// - `handle`: four-word colour handle, may be null.
/// - `mode`: scale mode; `0xFF` means "full strength".
///
/// # Returns
/// `1` when the handle is usable, `0` when it is null or fully `-1`.
///
/// # Side effects
/// None.
///
/// # Safety
/// A non-null `handle` must be readable for 16 bytes.
///
/// # Confidence
/// high - the two guards and the four comparisons are literal.
pub unsafe fn fn_802b6ae0(handle: usize, mode: u32) -> u32 {
    if mode != 0xFF {
        return 1;
    }
    if handle != 0 {
        let unused = platform::read_u32(handle) == 0xFFFF_FFFF
            && platform::read_u32(handle + 4) == 0xFFFF_FFFF
            && platform::read_u32(handle + 8) == 0xFFFF_FFFF
            && platform::read_u32(handle + 0x0C) == 0xFFFF_FFFF;
        if !unused {
            return 1;
        }
    }
    0
}

/// Copies four bytes and scales the fourth by `mode / 0xFF`.
///
/// # Original
/// - Ghidra: `FUN_802b6b50` at `0x802B6B50` (60 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802b6b50_FUN_802b6b50.c`
/// - observed: `*param_1 = *param_2; if (param_3 == 0xff) return;
///   param_3 = (uint)*(byte *)((int)param_2 + 3) * param_3;
///   iVar1 = param_3 / 0xff + (param_3 >> 0x1f);
///   *(char *)((int)param_1 + 3) = (char)iVar1 - (char)(iVar1 >> 0x1f);`
///
/// # Arguments
/// - `dst`: four-byte destination.
/// - `src`: four-byte source.
/// - `mode`: scale byte; `0xFF` copies unchanged.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes four bytes at `dst`.
///
/// # Safety
/// `dst` must be writable and `src` readable for four bytes.
///
/// # Confidence
/// high - the copy, the scaler and the sign fixup are literal.
pub unsafe fn fn_802b6b50(dst: usize, src: usize, mode: u32) {
    platform::write_u32(dst, platform::read_u32(src));
    if mode == 0xFF {
        return;
    }
    let scaled = (platform::read_u8(src + 3) as i32).wrapping_mul(mode as i32);
    let quotient = scaled / 0xFF + (scaled >> 31);
    let corrected = quotient.wrapping_sub(quotient >> 31) as u8;
    platform::write_u8(dst + 3, corrected);
}

/// Scales a 16-byte colour block by `scale / 0xFF` and forwards it.
///
/// # Original
/// - Ghidra: `FUN_802b71e0` at `0x802B71E0` (304 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802b71e0_FUN_802b71e0.c`
/// - observed: four source words are read from the incoming `r7`, each byte is
///   multiplied by the incoming `r8` and divided by `0xff` when `r8 != 0xff`,
///   the 16 scaled bytes are written to a stack block, then `FUN_802b6c80()`
///   runs.
/// - `// inferred:` the trailing call receives the stack block; Ghidra prints
///   it without arguments.
///
/// # Arguments
/// - `source`: 16-byte source colour block (`r7`); may be null.
/// - `scale`: scale byte applied to every component (`r8`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes a 16-byte stack block and calls `0x802B6C80`.
///
/// # Safety
/// A non-null `source` must be readable for 16 bytes and the callee callable.
///
/// # Confidence
/// medium - the scaling loop is literal; the callee's argument is inferred.
pub unsafe fn fn_802b71e0(source: usize, scale: u8) {
    let mut scaled = [0u8; 16];
    if source != 0 {
        for (slot, byte) in scaled.iter_mut().enumerate() {
            let raw = platform::read_u8(source + slot);
            *byte = if scale == 0xFF {
                raw
            } else {
                ((raw as u32 * scale as u32) / 0xFF) as u8
            };
        }
    }
    platform::call1(FN_802B6C80, scaled.as_ptr() as u32);
}

/// Initialises one 0x28-byte ordered-queue node.
///
/// # Original
/// - Ghidra: `FUN_802bdb40` at `0x802BDB40` (36 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802bdb40_FUN_802bdb40.c`
/// - observed: `+0x04`, `+0x08`, `+0x0C` zero; `+0x10` and `+0x14` set to the
///   `r2 - 0x3f10` float; byte `+0x18` cleared.
///
/// # Arguments
/// - `this`: node to initialise.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes six words and one byte.
///
/// # Safety
/// `this` must be writable for 0x28 bytes.
///
/// # Confidence
/// high - every store is literal.
pub unsafe fn fn_802bdb40(this: usize) {
    let zero = platform::read_u32(SDA2_FLOAT_ZERO);
    platform::write_u32(this + 0x04, 0);
    platform::write_u32(this + 0x08, 0);
    platform::write_u32(this + 0x0C, 0);
    platform::write_u32(this + 0x14, zero);
    platform::write_u32(this + 0x10, zero);
    platform::write_u8(this + 0x18, 0);
}

/// Arms a node with a string range and a repeat/direction count.
///
/// # Original
/// - Ghidra: `FUN_802bdb70` at `0x802BDB70` (84 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802bdb70_FUN_802bdb70.c`
/// - observed: `+0x04 = +0x08 = param_2; flags = flags & 0xcf;` then flag
///   `0x10` for a negative count or `0x30` for a positive one; `+0x0C = count`;
///   finally `flags = flags & 0xfd | 9`.
///
/// # Arguments
/// - `this`: node.
/// - `first`: string cursor start/end.
/// - `count`: repeat count; its sign selects the direction bits.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x04`, `+0x08`, `+0x0C` and the flag byte `+0x18`.
///
/// # Safety
/// `this` must be writable for 0x28 bytes.
///
/// # Confidence
/// high - every store and mask is literal.
pub unsafe fn fn_802bdb70(this: usize, first: usize, count: i32) {
    platform::write_u32(this + 0x04, first as u32);
    platform::write_u32(this + 0x08, first as u32);
    let mut flags = platform::read_u8(this + 0x18) & 0xCF;
    if count < 0 {
        flags |= 0x10;
    } else if count > 0 {
        flags |= 0x30;
    }
    platform::write_u32(this + 0x0C, count as u32);
    platform::write_u8(this + 0x18, (flags & 0xFD) | 9);
}

/// Arms a node with a float step and a repeat/direction count.
///
/// # Original
/// - Ghidra: `FUN_802bdbd0` at `0x802BDBD0` (60 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802bdbd0_FUN_802bdbd0.c`
/// - observed: `+0x10 = (float)param_1; +0x0C = param_3;
///   flags = flags & 0xfa; +0x14 = r2 - 0x3f10; flags = flags | 10;` and for a
///   negative count `flags = flags | 0xe`.
///
/// # Arguments
/// - `step`: float step stored at `+0x10`.
/// - `this`: node.
/// - `count`: repeat count.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x10`, `+0x0C`, `+0x14` and the flag byte `+0x18`.
///
/// # Safety
/// `this` must be writable for 0x28 bytes.
///
/// # Confidence
/// high - all four stores and the two masks are literal.
pub unsafe fn fn_802bdbd0(step: f32, this: usize, count: i32) {
    platform::write_f32(this + 0x10, step);
    platform::write_u32(this + 0x0C, count as u32);
    let flags = platform::read_u8(this + 0x18) & 0xFA;
    platform::write_u32(this + 0x14, platform::read_u32(SDA2_FLOAT_ZERO));
    platform::write_u8(this + 0x18, flags | 0x0A);
    if count < 0 {
        platform::write_u8(this + 0x18, flags | 0x0E);
    }
}

/// Advances a node by one step and returns its current output value.
///
/// Two modes are implemented: a string mode that walks the cursor at `+0x08`
/// and treats `'*'` as a full step, and a numeric mode that accumulates
/// `+0x10` into `+0x14` and emits 1.0 on overflow. Bit 3 of `+0x18` is the
/// enable flag; bits 2 and 5 control repeat handling.
///
/// # Original
/// - Ghidra: `FUN_802bdc10` at `0x802BDC10` (236 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802bdc10_FUN_802bdc10.c`
/// - observed: the `bVar1 & 8`, `bVar1 & 1`, `bVar1 & 0x10`, `bVar1 & 0x20`,
///   `bVar1 & 4` guards, the cursor increment at `+0x08`, the `'*'` compare,
///   the accumulator add at `+0x14` and the `r2 - 0x3f08` / `r2 - 0x3f04`
///   constants.
/// - `// unknown:` the two constants' exact values are read at runtime.
///
/// # Arguments
/// - `this`: node.
///
/// # Returns
/// The node's current step value as a double (the original returns `f1`).
///
/// # Side effects
/// Advances `+0x08` or `+0x14`, decrements `+0x0C` and updates `+0x18`.
///
/// # Safety
/// `this` must be writable and its string cursor valid while bit 0 is set.
///
/// # Confidence
/// high - the control flow and every store are literal; only the constant
/// meanings are unknown.
pub unsafe fn fn_802bdc10(this: usize) -> f64 {
    let flags = platform::read_u8(this + 0x18);
    let zero = platform::read_f32(SDA2_FLOAT_ZERO);
    let mut value = f64::from(zero);
    if (flags & 8) == 0 {
        return f64::from(platform::read_f32(SDA2_QUEUE_INERT));
    }
    if (flags & 1) != 0 {
        let cursor = platform::read_u32(this + 0x08).wrapping_add(1);
        platform::write_u32(this + 0x08, cursor);
        let symbol = platform::read_u8(cursor as usize);
        if symbol == 0 {
            if (flags & 0x10) == 0 {
                platform::write_u8(this + 0x18, platform::read_u8(this + 0x18) & 0xF7);
            } else {
                platform::write_u32(this + 0x08, platform::read_u32(this + 0x04));
            }
        } else if symbol == b'*' {
            value = f64::from(platform::read_f32(SDA2_FLOAT_ONE));
        }
        if (platform::read_u8(this + 0x18) & 0x20) == 0 {
            return value;
        }
    } else {
        let one = platform::read_f32(SDA2_FLOAT_ONE);
        let accumulated = platform::read_f32(this + 0x14) + platform::read_f32(this + 0x10);
        platform::write_f32(this + 0x14, accumulated);
        if f64::from(one) <= f64::from(accumulated) {
            platform::write_u32(this + 0x14, platform::read_u32(SDA2_FLOAT_ZERO));
            value = f64::from(one);
        }
        if (platform::read_u8(this + 0x18) & 4) != 0 {
            return value;
        }
    }
    let remaining = platform::read_u32(this + 0x0C).wrapping_sub(1);
    platform::write_u32(this + 0x0C, remaining);
    if (remaining as i32) > 0 {
        return value;
    }
    platform::write_u8(this + 0x18, platform::read_u8(this + 0x18) & 0xF7);
    value
}

/// Constructs the 0x1C-byte list-header pair and its owning vtable.
///
/// # Original
/// - Ghidra: `FUN_802bdd00` at `0x802BDD00` (88 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802bdd00_FUN_802bdd00.c`
/// - observed: `*param_1 = &DAT_8034ff88; param_1[7] = 0;
///   FUN_80228dd0(param_1 + 1,0x1c); FUN_80228dd0(param_1 + 4,0x1c);`
///
/// # Arguments
/// - `this`: object returned unchanged.
///
/// # Returns
/// `this`.
///
/// # Side effects
/// Writes the vtable, clears `+0x1C` and initialises two list headers.
///
/// # Safety
/// `this` must be writable for 0x20 bytes.
///
/// # Confidence
/// high - the vtable word and both list calls are literal.
pub unsafe fn fn_802bdd00(this: usize) -> usize {
    platform::write_u32(this, VT_802BDD00 as u32);
    platform::write_u32(this + 0x1C, 0);
    platform::call2(FN_80228DD0, (this + 0x04) as u32, 0x1C);
    platform::call2(FN_80228DD0, (this + 0x10) as u32, 0x1C);
    this
}

/// Fills the free list with `count` fresh 0x28-byte queue nodes.
///
/// # Original
/// - Ghidra: `FUN_802bdd60` at `0x802BDD60` (140 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802bdd60_FUN_802bdd60.c`
/// - observed: `for (uVar3 = 0; (uVar3 & 0xff) < (uint)uVar4; uVar3 = uVar3 + 1)`
///   allocating 0x28 bytes, writing `&DAT_8034ff94`, clearing `+0x18`, calling
///   `FUN_802bdb40()` and appending to `iVar1 + 0x10`; finally `+0x1C = param_3`
///   and `FUN_802dcdb8()`.
/// - `// inferred:` `0x802DCD6C` is the register-save prologue; its high word
///   is the incoming `r3` (`this`) and its low word the node count.
///
/// # Arguments
/// - `this`: list owner returned by [`fn_802bdd00`].
/// - `count`: number of nodes to allocate (low byte).
/// - `owner`: pointer stored at `+0x1C`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Allocates and appends `count` nodes, then stores `owner`.
///
/// # Safety
/// `this` must hold the initialised headers and the allocator must be live.
///
/// # Confidence
/// medium - the loop and stores are literal; the count and `this` come from the
/// save prologue.
pub unsafe fn fn_802bdd60(this: usize, count: u32, owner: u32) {
    for _ in 0..(count & 0xFF) {
        let node = fn_802b9210(0x28);
        if node != 0 {
            platform::write_u32(node as usize, VT_802BDB40 as u32);
            platform::write_u8(node as usize + 0x18, 0);
            platform::call1(FN_802BDB40, node);
        }
        platform::call2(FN_80228DF0, (this + 0x10) as u32, node);
    }
    platform::write_u32(this + 0x1C, owner);
}

/// Drains the active list back into the free list and disables the owner.
///
/// # Original
/// - Ghidra: `FUN_802bddf0` at `0x802BDDF0` (112 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802bddf0_FUN_802bddf0.c`
/// - observed: `FUN_802bc910(*(undefined4 *)(param_1 + 0x1c)); while
///   (*(short *)(param_1 + 0xc) != 0) { uVar1 = FUN_80228ff0(param_1 + 4,0);
///   FUN_80228f80(param_1 + 4,uVar1); FUN_80228df0(param_1 + 0x10,uVar1); }`
///
/// # Arguments
/// - `this`: list owner.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Calls [`fn_802bc910`] on the owner and moves every active node to the free
/// list.
///
/// # Safety
/// The `+0x1C` owner must be a valid handle object.
///
/// # Confidence
/// high - the helper sequence and the count at `+0x0C` are literal.
pub unsafe fn fn_802bddf0(this: usize) {
    fn_802bc910(platform::read_u32(this + 0x1C) as usize);
    while platform::read_u16(this + 0x0C) != 0 {
        let node = platform::call2(FN_80228FF0, (this + 0x04) as u32, 0);
        platform::call2(FN_80228F80, (this + 0x04) as u32, node);
        platform::call2(FN_80228DF0, (this + 0x10) as u32, node);
    }
}

