/// Tests whether the cheapest node's cost is at or above the caller's limit.
///
/// # Original
/// - Ghidra: `FUN_80269e10` at `0x80269E10` (196 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80269e10_FUN_80269e10.c`
/// - observed: `if (param_1[3] == 0) return 0; if (param_1[3] <= *param_1) {
///   uVar4 = 0x80; piVar3 = 0; for (piVar1 = (int *)param_1[1];
///   piVar1 != param_1 + 1; piVar1 = (int *)*piVar1) { uVar2 =
///   *(byte *)(piVar1 + -0x1c) + piVar1[-0x2e]; uVar2 = (int)uVar2 < 0x80 ?
///   uVar2 & ~((int)uVar2 >> 0x1f) : 0x7f; if ((int)uVar2 < (int)uVar4) {
///   piVar3 = piVar1 + -0x42; uVar4 = uVar2; } } if (piVar3 == 0) return 0;
///   uVar4 = (byte *)(piVar3 + 0x26) + piVar3[0x14]; ... if (param_2 <
///   (int)uVar4) return 0; } return 1;`
/// - `// inferred:` each node costs its `-0x70` byte plus its `-0xB8` word,
///   clamped to `0..0x7F`; the winner's own `+0x98` byte plus `+0x50` word is
///   the final cost. The `0x80` start is "no candidate yet".
///
/// # Arguments
/// - `this`: list head: count at `+0x00`, links at `+0x04`, active descriptor
///   at `+0x0C`.
/// - `limit`: caller's cost threshold.
///
/// # Returns
/// `1` when the list should be drained, `0` when the best node is too cheap or
/// the list is empty.
///
/// # Side effects
/// None.
///
/// # Safety
/// Every list node and the `+0x0C` descriptor must be readable at the negative
/// offsets the export proves.
///
/// # Confidence
/// medium - the loop, the clamps and both cost sums are literal; the node roles
/// and the meaning of the `0x80` start are inferred.
pub unsafe fn fn_80269e10(this: usize, limit: i32) -> u32 {
    if platform::read_u32(this + 0x0C) == 0 {
        return 0;
    }
    if platform::read_u32(this + 0x0C) > platform::read_u32(this) {
        return 1;
    }
    let head = this + 0x04;
    let mut node = platform::read_u32(this + 0x04) as usize;
    let mut best = 0usize;
    let mut best_cost = 0x80u32;
    while node != head {
        let raw = platform::read_u8(node - 0x70) as u32
            + platform::read_u32(node - 0xB8);
        let cost = if (raw as i32) < 0x80 {
            raw & !(((raw as i32) >> 31) as u32)
        } else {
            0x7F
        };
        if (cost as i32) < (best_cost as i32) {
            best = node - 0x108;
            best_cost = cost;
        }
        node = platform::read_u32(node) as usize;
    }
    if best == 0 {
        return 0;
    }
    let raw = platform::read_u8(best + 0x98) as u32 + platform::read_u32(best + 0x50);
    let cost = if (raw as i32) < 0x80 {
        raw & !(((raw as i32) >> 31) as u32)
    } else {
        0x7F
    };
    if limit < cost as i32 {
        return 0;
    }
    1
}

/// Drains every node of the two lists and releases the active descriptor.
///
/// # Original
/// - Ghidra: `FUN_8026a1b0` at `0x8026A1B0` (240 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8026a1b0_FUN_8026a1b0.c`
/// - observed: `if (*param_1 != 0) { if (param_1[1] != 0) { while
///   (param_1[1] != 0) { iVar1 = param_1[3]; if (iVar1 != 0) { iVar2 =
///   iVar1 + 0xc; while (iVar2 != *(int *)(iVar1 + 0xc)) { iVar2 = *(int *)
///   (iVar2 + 4); if ((iVar2 != 0) && (*(code **)(iVar2 + 0x10) != 0))
///   (**(code **)(iVar2 + 0x10))(*(undefined4 *)(iVar2 + 8),
///   *(undefined4 *)(iVar2 + 0xc), *(undefined4 *)(iVar2 + 0x14)); }
///   if (iVar1 + 8 != 0) FUN_80229030(iVar1 + 8,0); }
///   FUN_80229190(param_1 + 1,iVar1); } } FUN_801d4d60(*param_1,3);
///   FUN_801d4c10(*param_1); *param_1 = 0; }`
/// - `// inferred:` the `+0x0C` descriptor owns a `+0x0C` link ring; each ring
///   node calls its `+0x10` slot with the three words at `+0x08`, `+0x0C` and
///   `+0x14`.
///
/// # Arguments
/// - `this`: list owner: handle at `+0x00`, list at `+0x04`, descriptor at
///   `+0x0C`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Calls every ring node's slot, releases the ring, drains the list, closes the
/// handle with mode 3 and clears `+0x00`.
///
/// # Safety
/// All list links and ring nodes must be valid; the handle must be closeable.
///
/// # Confidence
/// medium - every offset, guard and call is literal; the ring/slot roles are
/// inferred from the call arguments.
pub unsafe fn fn_8026a1b0(this: usize) {
    if platform::read_u32(this) == 0 {
        return;
    }
    while platform::read_u32(this + 0x04) != 0 {
        let descriptor = platform::read_u32(this + 0x0C) as usize;
        if descriptor != 0 {
            let mut cursor = descriptor + 0x0C;
            while cursor != platform::read_u32(descriptor + 0x0C) as usize {
                cursor = platform::read_u32(cursor + 0x04) as usize;
                if cursor != 0 {
                    let slot = platform::read_u32(cursor + 0x10) as usize;
                    if slot != 0 {
                        platform::call3(
                            slot,
                            platform::read_u32(cursor + 0x08),
                            platform::read_u32(cursor + 0x0C),
                            platform::read_u32(cursor + 0x14),
                        );
                    }
                }
            }
            // observed: `iVar1 + 8 != 0` is always true here; the call is kept.
            platform::call2(FN_80229030, (descriptor + 0x08) as u32, 0);
        }
        platform::call2(FN_80229190, (this + 0x04) as u32, descriptor as u32);
    }
    let handle = platform::read_u32(this);
    platform::call2(FN_801D4D60, handle, 3);
    platform::call1(FN_801D4C10, handle);
    platform::write_u32(this, 0);
}

