    platform::call2(FN_801AC470, G_80260950_STATE as u32, 0x100);
    platform::write_u32(this + 0x04, G_80260950_STATE as u32);
    let mask = call0_u32(IRQ_DISABLE);
    platform::call2(FN_801A0DF0, (this + 0xD8) as u32, (this + 0xE4) as u32);
    platform::call2(FN_801A0E10, (this + 0xDC) as u32, (this + 0xE8) as u32);
    platform::call2(FN_801A0E30, (this + 0xE0) as u32, (this + 0xEC) as u32);
    platform::call2(FN_801A0CA0, 0, 0);
    platform::call2(FN_801A0D10, 0, 0);
    platform::call2(FN_801A0D80, 0, 0);
