    platform::write_u32(G_80260950_CONTROL + 0x08, (SDA_BASE - 0x49A4) as u32);
    platform::write_u32(G_80260950_CONTROL + 0x0C, (SDA_BASE - 0x49A0) as u32);
    platform::write_u32(G_80260950_CONTROL + 0x10, (SDA_BASE - 0x499C) as u32);
    platform::write_u32(G_80260950_CONTROL + 0x14, (SDA_BASE - 0x4998) as u32);
    platform::write_u32(G_80260950_CONTROL + 0x04, (SDA_BASE - 0x49A8) as u32);
