/// Releases one member list and clears its voice channel.
///
/// # Original
/// - Ghidra: `FUN_80261640` at `0x80261640` (244 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80261640_FUN_80261640.c`
/// - observed: `mask = disable; base = this + slot*0xc;
///   if (base[0xb4] == 0) restore; else { for (node = base[0xb8];
///   node != &base[0xb8]; node = *node) (**(node[-1] + 0x10))(node - 1);
///   FUN_80229110(&base[0xb4]); if (slot == 0) reset_ch0(); +0xf4 = 0;
///   else if (slot == 1) reset_ch1(); +0xf8 = 0; else if (slot == 2)
///   reset_ch2(); +0xfc = 0; restore; }`
/// - `// inferred:` the save thunk's pair is `(manager, slot)`; the nodes are
///   intrusive, with the vtable four bytes before the link word.
///
/// # Arguments
/// - `this`: manager base.
/// - `slot`: member-list index 0..2; selects the `+0xB4` list and the
///   `+0xF4`/`+0xF8`/`+0xFC` channel word.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Walks each list node, calls its `+0x10` slot, releases the list head, clears
/// the slot's channel word and restores interrupts.
///
/// # Safety
/// `this + slot * 0xC` must be a live manager slot; each node must carry a
/// valid vtable at `node - 4`.
///
/// # Confidence
/// medium - the walk, the slot arithmetic and the three channel resets are
/// literal; the save pair order is inferred.
pub unsafe fn fn_80261640(this: usize, slot: u32) {
    let mask = call0_u32(IRQ_DISABLE);
    let base = this + (slot as usize) * 0xC;
    if platform::read_u32(base + 0xB4) == 0 {
        platform::call1(IRQ_RESTORE, mask);
        return;
    }
    let head = base + 0xB8;
    let mut node = platform::read_u32(head) as usize;
    while node != head {
        let next = platform::read_u32(node) as usize;
        let object = node - 4;
        let vtable = platform::read_u32(object) as usize;
        let destroy = platform::read_u32(vtable + 0x10) as usize;
        platform::call1(destroy, object as u32);
        node = next;
    }
    platform::call1(FN_80229110, (base + 0xB4) as u32);
    if slot == 0 {
        platform::call2(FN_801A0CA0, 0, 0);
        platform::write_u32(this + 0xF4, 0);
    } else if slot == 1 {
        platform::call2(FN_801A0D10, 0, 0);
        platform::write_u32(this + 0xF8, 0);
    } else if slot == 2 {
        platform::call2(FN_801A0D80, 0, 0);
        platform::write_u32(this + 0xFC, 0);
    }
    platform::call1(IRQ_RESTORE, mask);
}

/// Tests whether the member's cursor lies inside the current mode's window.
///
/// # Original
/// - Ghidra: `FUN_80261e70` at `0x80261E70` (320 bytes)
/// - Extent: `stwu` prologue at `0x80261E70` to the final `blr` at
///   `0x80261FAC`, 320 bytes - matches `functions.tsv`.
/// - Evidence: `work/ghidra/main-gb/export/80261e70_FUN_80261e70.c`
/// - observed: `mask = disable; if (+0x10 == 0) { restore; return 0; }
///   pos = child ? child[0xa2] << 16 | child[0xa4] : 0; manager(); raw =
///   FUN_80260ec0(); mode = +0x14; unit = raw ? raw + 0x80000000 : raw;
///   width = mode==3 ? unit*2+2 : mode==2 ? unit : mode==1 ? unit>>1 : 0;
///   edge = mode==3 ? width+0x200 : mode==2 ? width+0x100 : mode==1 ?
///   width+0x80 : return 0; restore; return pos < width || edge <= pos ? 0 : 1;`
///
/// # Arguments
/// - `this`: member record; `+0x00` is the child handle, `+0x10` the ready
///   word and `+0x14` the mode.
///
/// # Returns
/// 1 when `width <= pos < edge`, otherwise 0.
///
/// # Side effects
/// Masks and restores interrupts and reads the manager count word.
///
/// # Safety
/// `this` must be readable through `+0x14`; a non-null child must be readable
/// at `+0xA2`.
///
/// # Confidence
/// medium - the ladder and the bit arithmetic are literal; the cursor/width
/// units and the `0x80000000` bias are inferred from the sibling helpers.
pub unsafe fn fn_80261e70(this: usize) -> u32 {
    let mask = call0_u32(IRQ_DISABLE);
    if platform::read_u32(this + 0x10) == 0 {
        platform::call1(IRQ_RESTORE, mask);
        return 0;
    }
    let child = platform::read_u32(this) as usize;
    let position = if child == 0 {
        0
    } else {
        (platform::read_u16(child + 0xA2) as u32) * 0x10000
            + platform::read_u16(child + 0xA4) as u32
    };
    let manager = fn_80260860();
    let raw = fn_80260ec0(manager);
    let mode = platform::read_u32(this + 0x14);
    let unit = if raw != 0 {
        raw.wrapping_add(0x8000_0000)
    } else {
        raw
    };
    let width = if mode == 3 {
        unit.wrapping_mul(2).wrapping_add(2)
    } else if mode == 2 {
        unit
    } else if mode == 1 {
        unit >> 1
    } else {
        0
    };
    let edge = if mode == 3 {
        width.wrapping_add(0x200)
    } else if mode == 2 {
        width.wrapping_add(0x100)
    } else if mode == 1 {
        width.wrapping_add(0x80)
    } else {
        platform::call1(IRQ_RESTORE, mask);
        return 0;
    };
    let result = if position < width || edge <= position { 0 } else { 1 };
    platform::call1(IRQ_RESTORE, mask);
    result
}

