/// medium - every branch and mask is literal; the "distance in sixteenths"
/// meaning of the `mode == 3` ladder is inferred.
pub unsafe fn fn_80262540(this: usize) -> i32 {
    let mask = call0_u32(IRQ_DISABLE);
    let child = platform::read_u32(this) as usize;
    if child == 0 || platform::read_u32(this + 0x10) == 0 {
        platform::call1(IRQ_RESTORE, mask);
        return 0;
    }
    let hit = fn_80261e70(this) != 0;
    let current = platform::read_u32(this) as usize;
    let position = if hit {
        if current == 0 {
            0
        } else {
            (platform::read_u16(current + 0x9E) as u32) * 0x10000
                + platform::read_u16(current + 0xA0) as u32
        }
    } else if current == 0 {
        0
    } else {
        (platform::read_u16(current + 0xA2) as u32) * 0x10000
            + platform::read_u16(current + 0xA4) as u32
    };
    let unit = platform::read_u32(this + 0x10);
    let unit = if unit != 0 {
        unit.wrapping_add(0x8000_0000)
    } else {
        unit
    };
    let mode = platform::read_u32(this + 0x14);
    let mut result = 0i32;
    if mode == 3 {
        let d = position.wrapping_sub(unit.wrapping_mul(2));
        result = ((d & 0xF).wrapping_add((d >> 4).wrapping_mul(0xE)) as i32).wrapping_sub(2);
    } else if mode == 2 {
        result = position.wrapping_sub(unit) as i32;
    } else if mode == 1 {
        result = position.wrapping_sub(unit >> 1) as i32;
    }
    if hit {
        result = result.wrapping_add(1);
    }
    platform::call1(IRQ_RESTORE, mask);
    result
}

/// Advances the member cursor and uploads its twelve parameter halfwords.
///
/// # Original
/// - Ghidra: `FUN_802628a0` at `0x802628A0` (336 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802628a0_FUN_802628a0.c`
