    let mask = call0_u32(IRQ_DISABLE);
    let child = platform::read_u32(this) as usize;
    if child == 0 {
        platform::call1(IRQ_RESTORE, mask);
        return;
    }
    const OR_MASKS: [u32; 24] = [
        0, 0, 0x2, 0x6, 0x1_0000, 0x5_0000, 0x2_0000, 0x6_0000, 0x20_0000, 0xA0_0000,
        0x40_0000, 0xC0_0000, 0x400_0000, 0x1400_0000, 0x800_0000, 0x1800_0000,
        0x8, 0x18, 0x8_0000, 0x18_0000, 0x100_0000, 0x300_0000, 0x2000_0000,
        0x6000_0000,
    ];
