            platform::write_u32(G_80265100_LINK + 8, (G_80265100_LINK + 4) as u32);
            platform::write_u32(G_80265100_LIST_B, 0);
            platform::write_u32(G_80265100_LIST_B + 4, (G_80265100_LIST_B + 4) as u32);
