/// Walks one descriptor level for a selector.
///
/// # Original
/// - Ghidra: `FUN_80265a30` at `0x80265A30` (284 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80265a30_FUN_80265a30.c`
/// - observed: `kind = node[1]; if (kind == 1) return node;
///   if (kind == 2) { table = FUN_80283a60(node[0], node[4], this[1] + 8);
///   if (table == 0) return 0; for (i = 0; ; i++) { if (selector <=
///   table[i+1]) return table + ((table[0] + 4) & ~3) + i*8;
///   if (!(i + 1 < table[0])) return 0; } } if (kind == 3) {
///   table = FUN_80283a60(node[0], node[4], this[1] + 8); if (table == 0)
///   return 0; if (selector < table[0] || table[1] < selector) return 0;
///   return table + (selector - table[0])*8 + 4; } return 0;`
///
/// # Arguments
/// - `this`: lookup object; `+0x04` directory table.
/// - `node`: descriptor whose `+0x01` byte selects the walk.
/// - `selector`: index within the resolved table.
///
/// # Returns
/// The selected 8-byte descriptor, or 0.
///
/// # Side effects
/// None beyond the `0x80283A60` resolution call.
///
/// # Safety
/// `node` and every table reached must be readable; `selector` bounds are
/// checked only in the kind-3 arm, exactly like the export.
///
/// # Confidence
/// medium - the two walks and every byte offset are literal; the descriptor
/// role is inferred.
pub unsafe fn fn_80265a30(this: usize, node: usize, selector: u32) -> usize {
    let kind = platform::read_u8(node + 1);
    if kind == 1 {
        return node;
    }
    if kind == 2 {
        let table = platform::call3(
            FN_80283A60,
            platform::read_u8(node) as u32,
            platform::read_u32(node + 4),
            (platform::read_u32(this + 4) + 8) as u32,
        ) as usize;
        if table == 0 {
            return 0;
        }
        let count = platform::read_u8(table) as u32;
        let mut index = 0u32;
        loop {
            if selector <= platform::read_u8(table + 1 + index as usize) as u32 {
                let base = ((count as usize).wrapping_add(4)) & !3;
                return table + base + (index as usize) * 8;
            }
            index += 1;
            if index >= count {
                return 0;
            }
        }
    }
    if kind == 3 {
        let table = platform::call3(
            FN_80283A60,
            platform::read_u8(node) as u32,
            platform::read_u32(node + 4),
            (platform::read_u32(this + 4) + 8) as u32,
        ) as usize;
        if table == 0 {
            return 0;
        }
        let first = platform::read_u8(table) as u32;
        let last = platform::read_u8(table + 1) as u32;
        if selector < first || last < selector {
            return 0;
        }
        return table + (selector - first) as usize * 8 + 4;
    }
    0
}

