///   while (link != inner[3]) { link = link[1]; if (link != 0 &&
///   link[4] != 0) (**(link[4]))(link[2], link[3], link[5]); }
///   if (inner + 8 != 0) FUN_80229030(inner + 8, 0); }
///   FUN_80229190(this + 1, inner); } FUN_801d4d60(*this, 3);
///   FUN_801d4c10(*this); *this = 0; } if (this + 1 != 0)
///   FUN_80229030(this + 1, 0); if (0 < flag) FUN_802b9280(this);`
