            payload = (node + 0x20) as u32;
            platform::write_u32(node, 0);
            platform::write_u32(node + 4, 0);
            platform::write_u32(node + 8, payload);
            platform::write_u32(node + 0x0C, size);
            platform::write_u32(node + 0x10, a);
            platform::write_u32(node + 0x14, b);
