/// Binary-searches an eight-byte-stride table and returns the matching key.
///
/// # Original
/// - Ghidra: `FUN_802b4df0` at `0x802B4DF0` (232 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802b4df0_FUN_802b4df0.c`
/// - observed: `if ((param_3 == 1) || (param_1 <= (double)*param_2)) return
///   *(undefined2 *)(param_2 + 1); if ((double)param_2[param_3 * 2 + -2] <=
///   param_1) return *(undefined2 *)(param_2 + param_3 * 2 + -1); ...
///   if ((*(r2 - 0x3f90) < (float)(param_1 - (double)param_2[iVar5 * 2]))
///   && (... < *(r2 - 0x3f8c))) return *(undefined2 *)(param_2 + iVar5 * 2
///   + 1); return *(undefined2 *)(param_2 + iVar4 * 2 + 1);`
/// - `// inferred:` each entry is a float boundary followed by a `u16` key;
///   the two `r2` floats are the tolerance window used to prefer the upper
///   boundary.
///
/// # Arguments
/// - `value`: probe value.
/// - `entries`: table base; entry `i` starts at byte `i * 8`.
/// - `count`: entry count.
///
/// # Returns
/// The `u16` key stored at `+0x04` of the selected entry.
///
/// # Side effects
/// None.
///
/// # Safety
/// `entries` must hold `count` readable entries.
///
/// # Confidence
/// medium - the search, the two tolerance tests and both return sites are
/// literal; the meaning of the keys is inferred from the stride.
pub unsafe fn fn_802b4df0(value: f64, entries: usize, count: i32) -> u16 {
    if count == 1 || value <= platform::read_f32(entries) as f64 {
        return platform::read_u16(entries + 0x04);
    }
    if platform::read_f32(entries + (count * 2 - 2) as usize * 4) as f64 <= value {
        return platform::read_u16(entries + (count * 2 - 1) as usize * 4);
    }
    let mut low = 0i32;
    let mut high = count - 1;
    let mut probe;
    loop {
        probe = high;
        if low == probe - 1 || low == probe {
            break;
        }
        let mid = (low + high) / 2;
        high = mid;
        if platform::read_f32(entries + mid as usize * 8) as f64 <= value {
            low = mid;
            high = probe;
        }
    }
    let delta = (value - platform::read_f32(entries + probe as usize * 8) as f64) as f32;
    let low_bound = platform::read_f32(SDA2_802B4DF0_LOW);
    let high_bound = platform::read_f32(SDA2_802B4DF0_HIGH);
    if low_bound < delta && delta < high_bound {
        platform::read_u16(entries + probe as usize * 8 + 0x04)
    } else {
        platform::read_u16(entries + low as usize * 8 + 0x04)
    }
}

/// Hides or shows one effect record and rebinds the manager's texture flags.
///
/// # Original
/// - Ghidra: `FUN_802baed0` at `0x802BAED0` (156 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802baed0_FUN_802baed0.c`
/// - observed: `if ((*param_1 & 1) != 0) { local_18[0] = *(param_1 + 0x14);
///   FUN_801c5ec0(local_18,*(param_1 + 0x18)); } piVar3 =
///   (**(code **)(**(int **)(r13 + -0x4838) + 8))(); iVar5 = *piVar3;
///   uVar2 = countLeadingZeros(*(byte *)(iVar5 + 0x19));
///   FUN_801c5f40(...,iVar5 + 0x1a,uVar2 >> 5 & 0xff,iVar5 + 0x32); ...
///   FUN_802bc350(uVar4,bVar1 & 1);`
/// - `// inferred:` the manager at `r13 - 0x4838` exposes the current texture
///   record through vtable `+8`; `+0x19`/`+0x1A`/`+0x32` are its packed
///   palette fields and `0x802BC350` the stream advance.
///
/// # Arguments
/// - `state`: record with the visible byte at `+0x00`, the colour at `+0x14`
///   and the texture id at `+0x18`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// May enqueue one texture colour, update the palette table, and advance the
/// manager stream.
///
/// # Safety
/// `state` and the manager singleton must be initialised.
///
/// # Confidence
/// medium - every call, offset and mask is literal; the texture/palette roles
/// are inferred from the byte layout.
pub unsafe fn fn_802baed0(state: usize) {
    if platform::read_u8(state) & 1 != 0 {
        let colour = [platform::read_u32(state + 0x14), 0, 0, 0, 0];
        platform::call2(
            FN_801C5EC0,
            colour.as_ptr() as u32,
            platform::read_u32(state + 0x18),
        );
    }
    let manager = platform::read_u32(SDA_802B_WRAPPER_MANAGER) as usize;
    let vtable = platform::read_u32(manager) as usize;
    let slot = platform::read_u32(vtable + 0x08) as usize;
    let current = platform::call1(slot, manager as u32) as usize;
    let record = platform::read_u32(current) as usize;
    let palette = platform::read_u8(record + 0x19) as u32;
    platform::call4(
        FN_801C5F40,
        palette,
        (record + 0x1A) as u32,
        palette.leading_zeros() >> 5,
        (record + 0x32) as u32,
    );
    let flags = platform::read_u8(state);
    let slot = platform::read_u32(vtable + 0x14) as usize;
    let stream = platform::call1(slot, manager as u32);
    fn_802bc350(stream as usize, (flags & 1) as u32);
}

