/// Reads one interpolated value out of a ramp record.
///
/// # Original
/// - Ghidra: `FUN_80260a80` at `0x80260A80` (108 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80260a80_FUN_80260a80.c`
/// - observed: `if (signed cursor < signed duration) low + (cursor as f32) *
///   (high - low) / (duration as f32); else high;`
/// - the `CONCAT44(0x43300000, x ^ 0x80000000) - 2^52` pair is the unsigned
///   `u32 -> f32` conversion.
///
/// # Arguments
/// - `this`: ramp record with `low` at `+0x1C`, `high` at `+0x20`, `duration`
///   at `+0x24` and `cursor` at `+0x28`.
///
/// # Returns
/// The interpolated value widened to `f64` (the C return type).
///
/// # Side effects
/// None.
///
/// # Safety
/// `this` must be readable for `0x2C` bytes.
///
/// # Confidence
/// high - the guard, the three loads and the two stores are literal.
pub unsafe fn fn_80260a80(this: usize) -> f64 {
    let cursor = platform::read_u32(this + 0x28);
    let duration = platform::read_u32(this + 0x24);
    let value = if (cursor as i32) < (duration as i32) {
        let low = platform::read_f32(this + 0x1C);
        let high = platform::read_f32(this + 0x20);
        low + ((cursor as f32) * (high - low)) / (duration as f32)
    } else {
        platform::read_f32(this + 0x20)
    };
    value as f64
}

/// Stores a new ramp pair and schedules the next sound-system update.
///
/// # Original
/// - Ghidra: `FUN_802610c0` at `0x802610C0` (204 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802610c0_FUN_802610c0.c`
/// - observed: lower-clamps the new value to `r2 - 0x48a8`, advances the old
///   ramp to its final point, writes `+0x28 = 0`, `+0x1C = value`,
///   `+0x20 = new`, `+0x24 = (count + 2) / 3`, and on `count == 0` calls
///   `FUN_80283530(FUN_80282ef0(), 8)`.
///
/// # Arguments
/// - `value`: new ramp target (`f64` in the export).
/// - `this`: ramp record.
/// - `count`: ramp length in updates.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes four fields and may request a sound-system update.
///
/// # Safety
/// `this` must be writable for `0x2C` bytes.
///
/// # Confidence
/// medium - the arithmetic and both call addresses are literal; the `count / 3`
/// scaling is inferred to be the per-frame step count.
pub unsafe fn fn_802610c0(mut value: f64, this: usize, count: i32) {
    let lower = platform::read_f32(SDA2_SOUND_LOW_48A8) as f64;
    if value < lower {
        value = lower;
    }
    let cursor = platform::read_u32(this + 0x28);
    let duration = platform::read_u32(this + 0x24);
    let current = if (cursor as i32) < (duration as i32) {
        let low = platform::read_f32(this + 0x1C);
        let high = platform::read_f32(this + 0x20);
        low + ((cursor as f32) * (high - low)) / (duration as f32)
    } else {
        platform::read_f32(this + 0x20)
    };
    platform::write_u32(this + 0x28, 0);
    platform::write_f32(this + 0x1C, current);
    platform::write_f32(this + 0x20, value as f32);
    platform::write_u32(this + 0x24, (count.wrapping_add(2) / 3) as u32);
    if count == 0 {
        let sound = call0_u32(FN_80282EF0);
        platform::call2(FN_80283530, sound, 8);
    }
}

/// Lazily constructs the sound manager and dispatches every list callback.
///
/// # Original
/// - Ghidra: `FUN_80261190` at `0x80261190` (344 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80261190_FUN_80261190.c`
/// - observed: repeated `if (*(r13 - 0x4994) == 0) { FUN_802605d0(&DAT_803fc810);
///   FUN_802dc780(...); *(r13 - 0x4994) = 1; }` guards around a walk of the
///   inline list at `0x803FC81C`; each node's `+0x08` word is called; finally
///   the `0x803FC824` callback is called when set.
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Constructs the manager on first use, runs every registered callback and the
/// trailing frame callback.
///
/// # Safety
/// Must run on the sound thread; every list node and callback must be valid.
///
/// # Confidence
/// medium - the guards, the list walk and both callback loads are literal; the
/// node payload role is inferred from the `+0x08` call.
pub unsafe fn fn_80261190() {
    ensure_sound_manager_ready_80260000();
    let head = SOUND_MANAGER_HEAD_80260000;
    let mut node = platform::read_u32(head) as usize;
    while node != head {
        ensure_sound_manager_ready_80260000();
        let next = platform::read_u32(node) as usize;
        let callback = platform::read_u32(node + 0x08) as usize;
        platform::call0(callback);
        node = next;
    }
    ensure_sound_manager_ready_80260000();
    let tick = platform::read_u32(SOUND_MANAGER_TICK_80260000) as usize;
    if tick != 0 {
        ensure_sound_manager_ready_80260000();
        platform::call0(tick);
    }
}

