/// Recomputes the note cursor of a sound record and publishes it to the mixer.
///
/// # Original
/// - Ghidra: `FUN_80264220` at `0x80264220` (428 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80264220_FUN_80264220.c`
/// - observed: writes `+0x92 = (u16)param_1[2]`, selects the nearest of
///   `-1`/`+1`/rounded direction in units of `0x60`, clamps the direction so
///   `base + direction * 0x60` stays inside `0..0xFFFF`, then publishes
///   `+0x08`/`+0x0A` and the `0x100` flag.
/// - the `quotient / 0x60 + (quotient >> 31)` pair is the export's floor
///   division; it is reproduced literally.
///
/// # Arguments
/// - `this`: sound record; `+0x00` is the mixer handle, `+0x08`/`+0x0A` are
///   the published cursor and direction, `+0x0E` the target.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the handle cursor words and the record flags under interrupt mask.
///
/// # Safety
/// `this` and its mixer handle must be valid; the handle must be writable at
/// `+0x92`/`+0x94`/`+0x1C`.
///
/// # Confidence
/// medium - the arithmetic, masks and stores are literal; the nearest-step
/// selection is inferred from the `0x60` unit.
pub unsafe fn fn_80264220(this: usize) {
    let mask = call0_u32(IRQ_DISABLE);
    if platform::read_u32(this) == 0 {
        platform::call1(IRQ_RESTORE, mask);
        return;
    }
    let handle = platform::read_u32(this) as usize;
    platform::write_u16(handle + 0x92, platform::read_u16(this + 0x08));
    let target = platform::read_u16(this + 0x0E) as i32;
    let base = platform::read_u16(this + 0x08) as i32;
    let difference = target.wrapping_sub(base);
    let steps = difference / 0x60 + (difference >> 31);
    let rounded = (steps as i16).wrapping_sub((steps >> 31) as i16);
    let magnitude = rounded as u32;
    let is_zero = (!magnitude & magnitude.wrapping_neg()) >> 31;
    let mut direction: i32 = -1;
    if magnitude != is_zero {
        direction = 1;
    }
    let direct_distance = {
        let value = target.wrapping_sub(base + direction * 0x60);
        if value < 0 {
            value.wrapping_neg()
        } else {
            value
        }
    };
    let rounded_distance = {
        let value = target.wrapping_sub(base + (rounded as i32) * 0x60);
        if value < 0 {
            value.wrapping_neg()
        } else {
            value
        }
    };
    if rounded_distance < direct_distance {
        platform::write_u16(handle + 0x94, rounded as u16);
    } else {
        platform::write_u16(handle + 0x94, direction as u16);
    }
    let next = base.wrapping_add(platform::read_u16(handle + 0x94) as i16 as i32 * 0x60);
    if next < 0 {
        let negated = base.wrapping_neg();
        let quotient = negated / 0x60 + (negated >> 31);
        let clamped = (quotient as i16).wrapping_sub((quotient >> 31) as i16);
        platform::write_u16(handle + 0x94, clamped as u16);
    } else if next > 0xFFFF {
        let above = 0xFFFFi32.wrapping_sub(base);
        let quotient = above / 0x60 + (above >> 31);
        let clamped = (quotient as i16).wrapping_sub((quotient >> 31) as i16);
        platform::write_u16(handle + 0x94, clamped as u16);
    }
    if platform::read_u16(handle + 0x94) == 0 && platform::read_u16(this + 0x0A) == 0 {
        platform::write_u16(handle + 0x92, platform::read_u16(this + 0x0E));
    }
    let flags = (platform::read_u32(this + 0x04) & 0xFFFF_FDFF) | 0x100;
    platform::write_u32(this + 0x04, flags);
    platform::write_u16(this + 0x08, platform::read_u16(handle + 0x92));
    platform::write_u16(this + 0x0A, platform::read_u16(handle + 0x94));
    platform::write_u32(handle + 0x1C, platform::read_u32(handle + 0x1C) | flags);
    platform::write_u32(this + 0x04, 0);
    platform::call1(IRQ_RESTORE, mask);
}

/// Resolves a wave descriptor and decodes its `0x80`-byte record.
///
/// # Original
/// - Ghidra: `FUN_80265b50` at `0x80265B50` (604 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80265b50_FUN_80265b50.c`
/// - observed: descriptor kind `0` looks the entry up through
///   `0x80283a90`/`0x80283b10`/`0x80283a60` and decodes it with
///   `0x80283bd0`; kind `1` copies the inline record at `desc[1]`; kind `2`
///   asks that record's virtual `+0x08` for its source and copies that.
///
/// # Arguments
/// - `reader`: bank reader; `+0x00` is the open flag, `+0x08` the entry table.
/// - `out`: destination record (`0x80` bytes).
/// - `descriptor`: `{ kind, payload }` pair; `+0x04` is the payload word.
/// - `mode`: extra mode forwarded to the bank lookup and decoder.
/// - `out_handle`: optional word receiving the source record pointer.
///
/// # Returns
/// `1` when a record was produced, `0` otherwise.
///
/// # Side effects
/// Writes `out`, optionally writes `out_handle`, and decodes through the
/// `0x80283xxx` bank helpers.
///
/// # Safety
/// `reader`, `descriptor` and `out` must be valid; the record pointer in kind
/// `1`/`2` must be readable for `0x80` bytes.
///
/// # Confidence
/// medium - the three arms, the copy shape and every callee address are
/// literal; the bank-object roles are inferred from the call chain.
pub unsafe fn fn_80265b50(
    reader: usize,
    out: usize,
    descriptor: usize,
    mode: u32,
    out_handle: usize,
) -> u32 {
    if out_handle != 0 {
        platform::write_u32(out_handle, 0);
    }
    if platform::read_u32(reader) == 0 {
        return 0;
    }
    let kind = platform::read_u32(descriptor);
    if kind == 0 {
        let table = platform::read_u32(reader + 0x08) as usize;
        let index = platform::read_u32(descriptor + 0x04);
        if table == 0 {
            let mut query = [0u32; 5];
            platform::call2(FN_80283A90, query.as_mut_ptr() as u32, mode);
            let sound = platform::call2(FN_80283B10, query.as_mut_ptr() as u32, index);
            if sound == 0 {
                return 0;
            }
            let mut handle = [0u32; 1];
            platform::call2(FN_80283BA0, handle.as_mut_ptr() as u32, sound);
            return platform::call3(FN_80283BD0, handle.as_mut_ptr() as u32, out as u32, 0);
        }
        if index < platform::read_u32(table + 0x08) {
            let entry = table + index as usize * 8;
            let sound = platform::call3(
                FN_80283A60,
                platform::read_u8(entry + 0x0C) as u32,
                platform::read_u32(entry + 0x10),
                (table + 0x08) as u32,
            );
            if sound == 0 {
                return 0;
            }
            let mut handle = [0u32; 1];
            platform::call2(FN_80283BC0, handle.as_mut_ptr() as u32, sound);
            return platform::call3(FN_80283BD0, handle.as_mut_ptr() as u32, out as u32, mode);
        }
        return 0;
    }
    if kind == 1 {
        let source = platform::read_u32(descriptor + 0x04);
        if source == 0 {
            return 0;
        }
        if out_handle != 0 {
            platform::write_u32(out_handle, source);
        }
        copy_wave_record_80265b50(out, source as usize);
        return 1;
    }
    if kind == 2 {
        let source = platform::read_u32(descriptor + 0x04);
        if source == 0 {
            return 0;
        }
        let vtable = platform::read_u32(source as usize) as usize;
        let slot = platform::read_u32(vtable + 0x08) as usize;
        let record = platform::call1(slot, source);
        if record == 0 {
            return 0;
        }
        if out_handle != 0 {
            platform::write_u32(out_handle, record);
        }
        copy_wave_record_80265b50(out, record as usize);
        return 1;
    }
    0
}

/// Advances or aborts one note record's ramp.
///
/// # Original
/// - Ghidra: `FUN_80266250` at `0x80266250` (488 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80266250_FUN_80266250.c`
/// - observed: asks the child's `+0x18`/`+0x1C`/`+0x20` slots whether the note
///   may run; when it may not, calls the record's own `+0x10` slot. Otherwise
///   interpolates `+0x64..+0x70`, writes the new pair, clears `+0x98`,
///   notifies `param_1[4]` through `0x8027a900`, runs the `+0x2C` slot and
///   sets the state bytes at `+0x86`/`+0x87`.
///
/// # Arguments
/// - `this`: note record; its first word is the vtable.
/// - `duration`: ramp length in updates.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Runs four virtual slots, may call `0x8027A900`, and writes the ramp fields
/// and state bytes.
///
/// # Safety
/// `this` and its child object must expose valid vtables.
///
/// # Confidence
/// medium - the slots, constants and arithmetic are literal; the child/owner
/// roles are inferred from the preconditions.
pub unsafe fn fn_80266250(this: usize, duration: u32) {
    let child = virtual_call1_80260000(this, 0x24) as usize;
    let mut stop = duration == 0;
    if !stop {
        stop = virtual_call1_80260000(child, 0x18) == 0;
    }
    if !stop {
        stop = virtual_call1_80260000(child, 0x1C) == 0;
    }
    if !stop {
        stop = virtual_call1_80260000(child, 0x20) != 0;
    }
    if stop {
        virtual_call1_80260000(this, 0x10);
        return;
    }
    let cursor = platform::read_u32(this + 0x70);
    let length = platform::read_u32(this + 0x6C);
    let first = ramp_80260000(
        platform::read_f32(this + 0x64),
        platform::read_f32(this + 0x68),
        cursor,
        length,
    );
    let second = ramp_80260000(
        platform::read_f32(this + 0x64),
        platform::read_f32(this + 0x68),
        cursor,
        length,
    );
    platform::write_f32(this + 0x64, second);
    platform::write_u32(this + 0x68, platform::read_u32(SDA2_SOUND_FLOAT_4834));
    platform::write_u32(this + 0x6C, ((duration as f32) * first) as i32 as u32);
    platform::write_u32(this + 0x70, 0);
    platform::write_u8(this + 0x98, 0);
    let owner = platform::read_u32(this + 0x10);
    if owner != 0 {
        platform::call2(FN_8027A900, owner, this as u32);
    }
    virtual_call1_80260000(this, 0x2C);
    platform::write_u8(this + 0x86, 0);
    platform::write_u32(this + 0x88, 0);
    platform::write_u8(this + 0x8C, 0);
    platform::write_u8(this + 0x87, 1);
}

/// Restarts one envelope record in fade-in or fade-out mode.
///
/// # Original
/// - Ghidra: `FUN_80266440` at `0x80266440` (596 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80266440_FUN_80266440.c`
/// - observed: for `mode == 0`, when `(+0x88 - 1) < 3`, recomputes
///   `+0x74..+0x80`, stores `ticks = max(1, duration * (ceiling - value))`,
///   then `+0x88 = 3`, byte `+0x8C = 1`; for the other modes, when `+0x88` is
///   `0`/`1`/`3`, stores `ticks = max(1, duration * value)`, `+0x88 = 1` and
///   byte `+0x8C = 0`.
///
/// # Arguments
/// - `this`: envelope record.
/// - `mode`: `0` selects the fade-in arm, anything else the fade-out arm.
/// - `duration`: ramp length in updates.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the ramp fields `+0x74..+0x80`, the state word `+0x88` and the byte
/// `+0x8C`.
///
/// # Safety
/// `this` must be writable for `0x90` bytes.
///
/// # Confidence
/// medium - both arms, the clamps and the two SDA words are literal; the
/// fade-in/fade-out split is inferred from the two ceiling choices.
pub unsafe fn fn_80266440(this: usize, mode: i32, duration: u32) {
    if mode == 0 {
        if platform::read_u32(this + 0x88).wrapping_sub(1) < 3 {
            let value = ramp_80260000(
                platform::read_f32(this + 0x74),
                platform::read_f32(this + 0x78),
                platform::read_u32(this + 0x80),
                platform::read_u32(this + 0x7C),
            );
            let ceiling = platform::read_f32(SDA2_SOUND_FLOAT_4838);
            let mut ticks = ((duration as f32) * (ceiling - value)) as i32;
            if ticks < 1 {
                ticks = 1;
            }
            let final_value = ramp_80260000(
                platform::read_f32(this + 0x74),
                platform::read_f32(this + 0x78),
                platform::read_u32(this + 0x80),
                platform::read_u32(this + 0x7C),
            );
            platform::write_f32(this + 0x74, final_value);
            platform::write_u32(this + 0x78, platform::read_u32(SDA2_SOUND_FLOAT_4838));
            platform::write_u32(this + 0x7C, ticks as u32);
            platform::write_u32(this + 0x80, 0);
            platform::write_u32(this + 0x88, 3);
            platform::write_u8(this + 0x8C, 1);
        }
    } else if platform::read_u32(this + 0x88) < 2 || platform::read_u32(this + 0x88) == 3 {
        let value = ramp_80260000(
            platform::read_f32(this + 0x74),
            platform::read_f32(this + 0x78),
            platform::read_u32(this + 0x80),
            platform::read_u32(this + 0x7C),
        );
        let mut ticks = ((duration as f32) * value) as i32;
        if ticks < 1 {
            ticks = 1;
        }
        let final_value = ramp_80260000(
            platform::read_f32(this + 0x74),
            platform::read_f32(this + 0x78),
            platform::read_u32(this + 0x80),
            platform::read_u32(this + 0x7C),
        );
        platform::write_f32(this + 0x74, final_value);
        platform::write_u32(this + 0x78, platform::read_u32(SDA2_SOUND_FLOAT_4834));
        platform::write_u32(this + 0x7C, ticks as u32);
        platform::write_u32(this + 0x80, 0);
        platform::write_u32(this + 0x88, 1);
        platform::write_u8(this + 0x8C, 0);
    }
}

