/// Clamps a new value and stores it as the tail of a ramp record.
///
/// # Original
/// - Ghidra: `FUN_80267420` at `0x80267420` (144 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80267420_FUN_80267420.c`
/// - observed: lower-clamps the value to `*(r2 - 0x4834)`, collapses the ramp
///   `+0xA0..+0xAC`, writes `+0xA0 = final`, `+0xA4 = value`, `+0xA8 =
///   duration`, `+0xAC = 0`.
///
/// # Arguments
/// - `value`: new target (`f64` in the export).
/// - `this`: ramp record.
/// - `duration`: new duration word.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes four words.
///
/// # Safety
/// `this` must be writable for `0xB0` bytes.
///
/// # Confidence
/// high - the clamp, the interpolation and the four stores are literal.
pub unsafe fn fn_80267420(mut value: f64, this: usize, duration: u32) {
    let lower = platform::read_f32(SDA2_SOUND_FLOAT_4834) as f64;
    if value < lower {
        value = lower;
    }
    let cursor = platform::read_u32(this + 0xAC);
    let length = platform::read_u32(this + 0xA8);
    let current = if (cursor as i32) < (length as i32) {
        let low = platform::read_f32(this + 0xA0);
        let high = platform::read_f32(this + 0xA4);
        low + ((cursor as f32) * (high - low)) / (length as f32)
    } else {
        platform::read_f32(this + 0xA4)
    };
    platform::write_f32(this + 0xA0, current);
    platform::write_f32(this + 0xA4, value as f32);
    platform::write_u32(this + 0xA8, duration);
    platform::write_u32(this + 0xAC, 0);
}

