    let along_y = (cosine * platform::read_f32(src + 0x0C) as f64) as f32;
    let side_x = (-cosine * platform::read_f32(src + 0x10) as f64) as f32;
    let side_y = (sine * platform::read_f32(src + 0x10) as f64) as f32;
