    platform::write_f32(dst + 0x0C, side_x * -wrap + origin_x + wrap + along_x * -wrap);
    platform::write_f32(dst + 0x10, along_y);
    platform::write_f32(dst + 0x14, side_y);
    platform::write_f32(dst + 0x18, flat);
    platform::write_f32(dst + 0x1C, side_y * -wrap + origin_y + wrap + along_y * -wrap);
    platform::write_f32(dst + 0x20, flat);
    platform::write_f32(dst + 0x24, flat);
    platform::write_f32(dst + 0x28, limit);
    platform::write_f32(dst + 0x2C, flat);
