/// Evaluates a cubic Hermite spline at one coordinate.
///
/// # Original
/// - Ghidra: `FUN_802b4ee0` at `0x802B4EE0` (444 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802b4ee0_FUN_802b4ee0.c`
/// - observed: `if ((param_3 == 1) || (param_1 <= *param_2)) return
///   param_2[1]; ... if (param_1 < param_2[param_3 * 3 + -3]) { ... binary
///   search ... } else return param_2[param_3 * 3 + -2];`
/// - the flat-segment test compares `param_1 - x0` against the two `r2` slots
///   `-0x3F90`/`-0x3F8C`; the curve uses `-0x3F88`, `-0x3F84`, `-0x3F80` and
///   `-0x3F7C`.
///
/// # Arguments
/// - `x`: coordinate to evaluate.
/// - `points`: `count` control points of three floats `{x, y, tangent}`.
/// - `count`: number of control points, at least one.
///
/// # Returns
/// The interpolated `y`, clamped to the end points.
///
/// # Side effects
/// None.
///
/// # Safety
/// `points` must hold `count * 3` readable floats.
///
/// # Confidence
/// medium - the search, the clamps and the coefficient layout are literal;
/// the `r2` coefficient values are not recovered.
pub unsafe fn fn_802b4ee0(x: f64, points: usize, count: i32) -> f64 {
    if count == 1 || x <= platform::read_f32(points) as f64 {
        return platform::read_f32(points + 0x04) as f64;
    }
    let last = ((count * 3 - 3) * 4) as usize;
    if x < platform::read_f32(points + last) as f64 {
        let mut low: u32 = 0;
        let mut upper: u32 = (count - 1) as u32;
        while low != upper.wrapping_sub(1) && low != upper {
            let mid = low.wrapping_add(upper) / 2;
            if (platform::read_f32(points + (mid as usize) * 12) as f64) < x {
                low = mid;
            } else {
                upper = mid;
            }
        }
        let high_point = points + (upper as usize) * 12;
        let low_point = points + (low as usize) * 12;
        let delta = (x - platform::read_f32(high_point) as f64) as f32;
        let near = platform::read_f32(SDA2_802B4DF0_LOW) < delta
            && delta < platform::read_f32(SDA2_802B4DF0_HIGH);
        if near {
            let next = high_point + 12;
            if upper < (count - 1) as u32 && platform::read_f32(high_point) == platform::read_f32(next) {
                return platform::read_f32(next + 0x04) as f64;
            }
            return platform::read_f32(high_point + 0x04) as f64;
        }
        let t = (x - platform::read_f32(low_point) as f64) as f32;
        let inv = platform::read_f32(SDA2_802B4EE0_INV)
            / (platform::read_f32(high_point) - platform::read_f32(low_point));
        let t2 = inv * t * t;
        let t3 = t * t2 * inv;
        let three = platform::read_f32(SDA2_802B4EE0_THREE) * t2 * inv;
        let two = platform::read_f32(SDA2_802B4EE0_TWO);
        let neg_two = platform::read_f32(SDA2_802B4EE0_NEG_TWO);
        (platform::read_f32(high_point + 0x08) * (t3 - t2)
            + platform::read_f32(low_point + 0x08) * (t + (t3 - two * t2))
            + platform::read_f32(low_point + 0x04)
                * (platform::read_f32(SDA2_802B4EE0_INV) + (two * t3 * inv - three))
            + platform::read_f32(high_point + 0x04) * (neg_two * t3 * inv + three)) as f64
    } else {
        platform::read_f32(points + ((count * 3 - 2) * 4) as usize) as f64
    }
}

