/// Clamps `value` into `[min, max]` exactly as the export's `<=`/`<` ladder.
unsafe fn clamp_102(value: f64, min: f64, max: f64) -> f64 {
    if value <= max {
        if value < min {
            min
        } else {
            value
        }
    } else {
        max
    }
}

/// Returns `start + index * (end - start) / total`, or `end` at the limit.
unsafe fn ramp_102(start: usize, end: usize, total: usize, index: usize) -> f64 {
    let span = platform::read_i32(total);
    if platform::read_i32(index) < span {
        let begin = platform::read_f32(start) as f64;
        let finish = platform::read_f32(end) as f64;
        begin + (platform::read_i32(index) as f64 * (finish - begin)) / span as f64
    } else {
        platform::read_f32(end) as f64
    }
}

/// Reproduces the three-way `mode` ladder that scales one channel value.
unsafe fn channel_scale_102(value: u32, mode: i32) -> u32 {
    if mode == 3 {
        value.wrapping_mul(2).wrapping_add(2)
    } else if mode == 2 {
        value
    } else if mode == 1 {
        value >> 1
    } else {
        0
    }
}

/// Reproduces the `mode` ladder that maps a tick index onto a note slot.
unsafe fn note_slot_102(base: u32, index: u32, mode: i32) -> u32 {
    if mode == 3 {
        (index % 0xE) + base.wrapping_mul(2) + (index / 0xE) * 0x10 + 2
    } else if mode == 2 {
        base.wrapping_add(index)
    } else if mode == 1 {
        (base >> 1).wrapping_add(index)
    } else {
        0
    }
}

/// Calls one no-argument callee that returns an `f64`.
unsafe fn call_double0(addr: usize) -> f64 {
    let target: extern "C" fn() -> f64 = core::mem::transmute(addr);
    target()
}

/// Calls one callee that takes an `f64` and returns a word.
unsafe fn call_u32_double(addr: usize, value: f64) -> u32 {
    let target: extern "C" fn(f64) -> u32 = core::mem::transmute(addr);
    target(value)
}

/// Calls `(f64, u32)`, the shape of most `0x80281xxx` stream setters.
unsafe fn call_void_f64_u32(addr: usize, value: f64, a: u32) {
    let target: extern "C" fn(f64, u32) = core::mem::transmute(addr);
    target(value, a);
}

/// Calls `(f64, f64, u32)`, used by one stream-record setter pair.
unsafe fn call_void_f64_f64_u32(addr: usize, x: f64, y: f64, a: u32) {
    let target: extern "C" fn(f64, f64, u32) = core::mem::transmute(addr);
    target(x, y, a);
}

/// Calls `(f64, u32, u32, u32)`, the `0x802839D0` window reader shape.
unsafe fn call_f64_3(addr: usize, x: f64, a: u32, b: u32, c: u32) {
    let target: extern "C" fn(f64, u32, u32, u32) = core::mem::transmute(addr);
    target(x, a, b, c);
}

/// Calls `(f64, f64, i32) -> f64`, the [`FN_802835B0`] ratio shape.
unsafe fn call_double3(addr: usize, x: f64, y: f64, z: i32) -> f64 {
    let target: extern "C" fn(f64, f64, i32) -> f64 = core::mem::transmute(addr);
    target(x, y, z)
}

/// Calls `(f64, 6 x u32)`, the per-channel listener slot of [`fn_80261740`].
unsafe fn call_listener_102(
    addr: usize,
    value: f64,
    a: u32,
    b: u32,
    c: u32,
    d: u32,
    e: u32,
    f: u32,
) {
    let target: extern "C" fn(f64, u32, u32, u32, u32, u32, u32) = core::mem::transmute(addr);
    target(value, a, b, c, d, e, f);
}

/// Stores one word as two halfwords on a voice handle under interrupt masking.
unsafe fn store_voice_word_102(this: usize, offset: usize, value: u32, flag: u32) {
    let mask = call0_u32(IRQ_DISABLE);
    let handle = platform::read_u32(this) as usize;
    if handle == 0 {
        platform::call1(IRQ_RESTORE, mask);
        return;
    }
    platform::write_u16(handle + offset, (value >> 16) as u16);
    platform::write_u16(handle + offset + 2, value as u16);
    let flags = platform::read_u32(handle + 0x1C);
    if (flags & 0x400) == 0 {
        platform::write_u32(handle + 0x1C, flags | flag);
    }
    platform::call1(IRQ_RESTORE, mask);
}

/// Returns the address of one virtual slot of `object`.
unsafe fn vtable_102(object: usize, offset: usize) -> usize {
    platform::read_u32(platform::read_u32(object) as usize + offset) as usize
}

/// Advances the three channel ramps and the master ramp of the sound manager.
///
/// # Original
/// - Ghidra: `FUN_80260af0` at `0x80260AF0` (972 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80260af0_FUN_80260af0.c`
/// - observed: three `0x10`-byte channel blocks: `+0x90/+0x8C` and
///   `+0x60/+0x5C` counters each advance, the `+0x84..+0x88` and
///   `+0x54..+0x58` ramps interpolate and are clamped by the `r2 - 0x48A4`/
///   `-0x48A8` pair, then `0x801A1910/1920/1930` receives the level; afterwards
///   the `+0x28/+0x24`, `+0x48/+0x44` and `+0x38/+0x34` counters advance and
///   `0x801A18F0` receives the product of the `+0x2C..+0x30` and
///   `+0x3C..+0x40` ramps.
/// - the `unaff_GQR0` / `ldexpf` pairs are the compiler's paired-single
///   prologue and epilogue; their results are never stored, so they are not
///   reproduced (same policy as [`fn_802bfda0`]).
///
/// # Arguments
/// - `this`: sound-manager tick record.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Advances six counters, rewrites the two per-channel levels and the master
/// level, and may release one channel list through [`fn_80261640`].
///
/// # Safety
/// `this` must be writable through `+0xB0` and the audio helpers must be live.
///
/// # Confidence
/// medium - every counter, ramp and clamp is literal; the GQR quantisation is
/// dead in the export and the field roles are inferred.
pub unsafe fn fn_80260af0(this: usize) {
    let max = platform::read_f32(SDA2_SOUND_ALT_48A4) as f64;
    let min = platform::read_f32(SDA2_SOUND_LOW_48A8) as f64;
    let scale = platform::read_f32(SDA2_102_F32_4898) as f64;
    let mut channel = 0usize;
    while channel < 3 {
        let base = this + channel * 0x10;
        let mut active = false;
        if platform::read_i32(base + 0x90) < platform::read_i32(base + 0x8C) {
            platform::write_i32(base + 0x90, platform::read_i32(base + 0x90) + 1);
            active = true;
        }
        if platform::read_i32(base + 0x60) < platform::read_i32(base + 0x5C) {
            let next = platform::read_i32(base + 0x60) + 1;
            platform::write_i32(base + 0x60, next);
            if platform::read_i32(base + 0x5C) <= next {
                fn_80261640(this, channel as u32);
            }
            active = true;
        }
        if active {
            let first = clamp_102(
                ramp_102(base + 0x84, base + 0x88, base + 0x8C, base + 0x90),
                min,
                max,
            );
            let second = clamp_102(
                ramp_102(base + 0x54, base + 0x58, base + 0x5C, base + 0x60),
                min,
                max,
            );
            let weighted = ((max * first) as f32) as f64 * second;
            let level = (scale * (weighted as f32) as f64) as u32;
            let _ = match channel {
                0 => platform::call1(FN_801A1910, level & 0xFFFF),
                1 => platform::call1(FN_801A1920, level & 0xFFFF),
                _ => platform::call1(FN_801A1930, level & 0xFFFF),
            };
        }
        channel += 1;
    }
    if platform::read_i32(this + 0x28) < platform::read_i32(this + 0x24) {
        platform::write_i32(this + 0x28, platform::read_i32(this + 0x28) + 1);
        let sound = call0_u32(FN_80282EF0);
        platform::call2(FN_80283530, sound, 8);
    }
    if platform::read_i32(this + 0x48) < platform::read_i32(this + 0x44) {
        platform::write_i32(this + 0x48, platform::read_i32(this + 0x48) + 1);
    }
    if platform::read_i32(this + 0x38) < platform::read_i32(this + 0x34) {
        platform::write_i32(this + 0x38, platform::read_i32(this + 0x38) + 1);
    }
    let level = ramp_102(this + 0x2C, this + 0x30, this + 0x34, this + 0x38);
    let depth = ramp_102(this + 0x3C, this + 0x40, this + 0x44, this + 0x48);
    let master = clamp_102((level * depth) as f32 as f64, min, max);
    platform::call1(FN_801A18F0, (scale * master) as i32 as u32 & 0xFFFF);
}

/// Notifies every channel member of a sound-manager mode change.
///
/// # Original
/// - Ghidra: `FUN_80260fa0` at `0x80260FA0` (260 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80260fa0_FUN_80260fa0.c`
/// - observed: `if (*this != mode) { mask; *this = mode; 0x801A18A0(mode);`
///   `0x80283530(0x80282EF0(),0x10); for three 0xC-byte slots walk the
///   `+0xB8` ring and call each node's `+0x18` slot; if (mode == 2) +0xFC = 0;
///   restore; }`
///
/// # Arguments
/// - `this`: sound-manager record whose `+0x00` word is the current mode.
/// - `mode`: new mode, `0`..`3`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Stores the mode, forwards it to `0x801A18A0`, requests a sound-system
/// update, calls three `+0x18` virtual slots per member node and clears
/// `+0xFC` in mode `2`.
///
/// # Safety
/// `this` must be a live manager record and every list node must carry a valid
/// vtable at `node - 4`.
///
/// # Confidence
/// medium - the guard, the mode ladder and the ring walk are literal; the
/// `+0x18` slot role is inferred.
pub unsafe fn fn_80260fa0(this: usize, mode: u32) {
    if platform::read_u32(this) == mode {
        return;
    }
    let mask = call0_u32(IRQ_DISABLE);
    platform::write_u32(this, mode);
    let _ = match mode {
        0 => platform::call1(FN_801A18A0, 0),
        1 => platform::call1(FN_801A18A0, 1),
        2 => platform::call1(FN_801A18A0, 2),
        3 => platform::call1(FN_801A18A0, 0),
        _ => 0,
    };
    let sound = call0_u32(FN_80282EF0);
    platform::call2(FN_80283530, sound, 0x10);
    let mut slot = this + 0xB4;
    let mut index = 0usize;
    while index < 3 {
        let head = slot + 4;
        let mut node = platform::read_u32(head) as usize;
        while node != head {
            let next = platform::read_u32(node) as usize;
            let object = node - 4;
            let notify = vtable_102(object, 0x18);
            platform::call1(notify, object as u32);
            node = next;
        }
        slot += 0xC;
        index += 1;
    }
    if mode == 2 {
        platform::write_u32(this + 0xFC, 0);
    }
    platform::call1(IRQ_RESTORE, mask);
}

/// Resets one channel ramp and hands the channel to a new sound entry.
///
/// # Original
/// - Ghidra: `FUN_802612f0` at `0x802612F0` (496 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802612f0_FUN_802612f0.c`
/// - observed: `base = this + index*0x10; if (base[0x60] < base[0x5c])
///   FUN_80261640(); base[0x54] = lerp; base[0x58] = r2[-0x48a4];
///   base[0x5c] = base[0x60] = 0; 0x801A1910/1920/1930(0x8000);
///   if ((**(entry + 0xc))(entry) != 0) { mask; if (slot[0xb4] == 0)
///   { 0x801A0CA0/D10/D80(FUN_80261740, index); this[index+0xf0] = 2; }
///   insert(&slot[0xb4], &slot[0xb8], entry + 1); restore; return 1; }`
/// - `// inferred:` the dropped argument of `FUN_80261640` is `(this, index)`,
///   the pair the shim still held at the call.
///
/// # Arguments
/// - `this`: sound-manager record.
/// - `index`: channel index `0`..`2`.
/// - `entry`: sound entry whose `+0x0C` slot is queried and whose `+0x04`
///   word is linked.
///
/// # Returns
/// `1` when the entry was linked, `0` otherwise.
///
/// # Side effects
/// Resets the channel ramp, programs the channel level, maybe registers
/// [`fn_80261740`] as the channel callback and inserts the entry into the
/// channel list.
///
/// # Safety
/// `this` and `entry` must be live; `index` must be `0`..`2`.
///
/// # Confidence
/// medium - the ramp, the callback registration and the insert are literal;
/// the dropped restore argument is reconstructed from the surrounding mask.
pub unsafe fn fn_802612f0(this: usize, index: u32, entry: usize) -> u32 {
    let base = this + index as usize * 0x10;
    if platform::read_i32(base + 0x60) < platform::read_i32(base + 0x5C) {
        fn_80261640(this, index);
    }
    if platform::read_i32(base + 0x60) < platform::read_i32(base + 0x5C) {
        platform::write_f32(base + 0x54, ramp_102(base + 0x54, base + 0x58, base + 0x5C, base + 0x60) as f32);
    } else {
        platform::write_f32(base + 0x54, platform::read_f32(base + 0x58));
    }
    platform::write_u32(base + 0x58, platform::read_u32(SDA2_SOUND_ALT_48A4));
    platform::write_u32(base + 0x5C, 0);
    platform::write_u32(base + 0x60, 0);
    let _ = match index {
        0 => platform::call1(FN_801A1910, 0x8000),
        1 => platform::call1(FN_801A1920, 0x8000),
        _ => platform::call1(FN_801A1930, 0x8000),
    };
    let accept = vtable_102(entry, 0x0C);
    if platform::call1(accept, entry as u32) == 0 {
        return 0;
    }
    let mask = call0_u32(IRQ_DISABLE);
    let slot = this + index as usize * 0xC;
    let head = slot + 0xB4;
    if platform::read_u32(head) == 0 {
        match index {
            0 => {
                platform::call2(FN_801A0CA0, FN_80261740 as u32, 0);
            }
            1 => {
                platform::call2(FN_801A0D10, FN_80261740 as u32, 1);
            }
            _ => {
                platform::call2(FN_801A0D80, FN_80261740 as u32, 2);
            }
        }
        platform::write_u8(this + index as usize + 0xF0, 2);
    }
    let link = [(slot + 0xB8) as u32];
    platform::call3(
        FN_80229160,
        head as u32,
        link.as_ptr() as u32,
        (entry + 4) as u32,
    );
    platform::call1(IRQ_RESTORE, mask);
    1
}

/// Stops one channel ramp, optionally restarting it at a fixed step.
///
/// # Original
/// - Ghidra: `FUN_802614e0` at `0x802614E0` (348 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802614e0_FUN_802614e0.c`
/// - observed: `if (mode == 0) { FUN_80261640(); base = this + index*0x10;
///   if ((int)base[0x60] < (int)base[0x5c]) { base[0x54] = lerp;
///   base[0x58] = r2[-0x48a8]; base[0x5c] = 0; base[0x60] = 0; } } else {
///   base = this + index*0x10; ... base[0x54] = lerp-or-end;
///   base[0x58] = r2[-0x48a8]; base[0x5c] = (mode + 2) / 3; base[0x60] = 0; }`
///
/// # Arguments
/// - `this`: sound-manager record.
/// - `index`: channel index `0`..`2`.
/// - `mode`: `0` releases the channel, otherwise it sets the new ramp length.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Rewrites the channel `+0x54..+0x60` block and, in mode `0`, releases the
/// channel list through [`fn_80261640`].
///
/// # Safety
/// `this + index * 0x10` must be writable through `+0x60`.
///
/// # Confidence
/// high - every store and the `(mode + 2) / 3` step are literal.
pub unsafe fn fn_802614e0(this: usize, index: u32, mode: i32) {
    let base = this + index as usize * 0x10;
    if mode == 0 {
        fn_80261640(this, index);
        if platform::read_i32(base + 0x60) < platform::read_i32(base + 0x5C) {
            let value = ramp_102(base + 0x54, base + 0x58, base + 0x5C, base + 0x60);
            platform::write_f32(base + 0x54, value as f32);
            platform::write_u32(base + 0x58, platform::read_u32(SDA2_SOUND_LOW_48A8));
            platform::write_u32(base + 0x5C, 0);
            platform::write_u32(base + 0x60, 0);
        }
    } else {
        let value = if platform::read_i32(base + 0x60) < platform::read_i32(base + 0x5C) {
            ramp_102(base + 0x54, base + 0x58, base + 0x5C, base + 0x60) as f32
        } else {
            platform::read_f32(base + 0x58)
        };
        platform::write_f32(base + 0x54, value);
        platform::write_u32(base + 0x58, platform::read_u32(SDA2_SOUND_LOW_48A8));
        platform::write_u32(base + 0x5C, ((mode + 2) / 3) as u32);
        platform::write_u32(base + 0x60, 0);
    }
}

/// Per-channel sound callback: keeps the channel window and tick count current.
///
/// # Original
/// - Ghidra: `FUN_80261740` at `0x80261740` (988 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80261740_FUN_80261740.c`
/// - observed: `start = 0x801B5FA0(); lazy manager init; copy 3 words
///   (or 4 when the manager state is 2) from the payload; if
///   `active[channel] == 0` the three/`0x180`-byte buffers are cleared through
///   `0x800046B4` and `ticks[channel] = now - start`; otherwise the per-channel
///   `0xB8` ring is walked and each node's `+0x14` slot receives
///   `(r2[-0x4894], object, count, words, 0x180, 0, manager_state)`.
///
/// # Arguments
/// - `payload`: 3- or 4-word parameter block passed by the audio system.
/// - `channel`: channel index `0`..`2` recovered from the save-pair.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Memsets up to four DSP buffers, decrements or initialises the channel
/// counter and publishes the elapsed ticks.
///
/// # Safety
/// `payload` must be readable for 16 bytes and every ring node live.
///
/// # Confidence
/// low - the counter handling, the memsets and the two tick stores are
/// literal, but the listener arguments and the save-pair order are inferred
/// and the repeated lazy init is folded into [`fn_80260860`].
pub unsafe fn fn_80261740(payload: usize, channel: u32) {
    let started = call0_u32(FN_801B5FA0);
    fn_80260860();
    let count = if platform::read_u32(G_SOUND_MANAGER) == 2 {
        4u32
    } else {
        3u32
    };
    let mut args = [0u32; 4];
    let mut word = 0usize;
    while word < count as usize {
        args[word] = platform::read_u32(payload + word * 4);
        word += 1;
    }
    let active = G_80261740_ACTIVE + channel as usize;
    if platform::read_u8(active) == 0 {
        fn_80260860();
        if platform::read_u32(G_80261740_STATE + channel as usize * 0xC) == 0 {
            let mut index = 0usize;
            while index < count as usize {
                platform::call3(FN_800046B4, args[index], 0, 0x180);
                index += 1;
            }
            fn_80260860();
            let now = call0_u32(FN_801B5FA0);
            platform::write_u32(
                G_80261740_TICKS + channel as usize * 4,
                now.wrapping_sub(started),
            );
        } else {
            fn_80260860();
            let head = G_80261740_LIST + channel as usize * 0xC;
            let mut node = platform::read_u32(head) as usize;
            loop {
                fn_80260860();
                if node == head {
                    break;
                }
                fn_80260860();
                let object = node - 4;
                let slot = vtable_102(object, 0x14);
                call_listener_102(
                    slot,
                    platform::read_f32(SDA2_102_F32_4894) as f64,
                    object as u32,
                    count,
                    args.as_ptr() as u32,
                    0x180,
                    0,
                    platform::read_u32(G_SOUND_MANAGER),
                );
                node = platform::read_u32(node) as usize;
            }
            fn_80260860();
            let now = call0_u32(FN_801B5FA0);
            platform::write_u32(
                G_80261740_TICKS + channel as usize * 4,
                now.wrapping_sub(started),
            );
        }
    } else {
        fn_80260860();
        platform::write_u8(active, platform::read_u8(active).wrapping_sub(1));
        let mut index = 0usize;
        while index < count as usize {
            platform::call3(FN_800046B4, args[index], 0, 0x180);
            index += 1;
        }
        fn_80260860();
        let now = call0_u32(FN_801B5FA0);
        platform::write_u32(
            G_80261740_TICKS + channel as usize * 4,
            now.wrapping_sub(started),
        );
    }
}

/// `r2 - 0x4894`: listener value forwarded by [`fn_80261740`].
const SDA2_102_F32_4894: usize = SDA2_BASE - 0x4894;

/// Applies the export's `if (value != 0) value += 0x80000000` normalisation.
fn signed_word_102(value: u32) -> u32 {
    if value != 0 {
        value.wrapping_add(0x8000_0000)
    } else {
        0
    }
}

/// Programs one voice's note window from a tick value.
///
/// # Original
/// - Ghidra: `FUN_80261fb0` at `0x80261FB0` (284 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80261fb0_FUN_80261fb0.c`
/// - observed: `mask; if (*this == 0) restore; else { mode = this[5];
///   if (value != 0) value += 0x80000000; slot = ladder(mode, value, count);
///   mask; store slot at handle[0x9a/0x9c]; if ((handle[0x1c] & 0x400) == 0)
///   handle[0x1c] |= 0x1000; restore; restore; }`
/// - the `0x124924925` magic is the unsigned `/ 14` sequence, so the mode-3
///   arm is `count % 14 + value * 2 + (count / 14) * 16 + 2`.
///
/// # Arguments
/// - `this`: voice-holder record whose `+0x00` word is the handle.
/// - `value`: base tick/note value normalised by the export.
/// - `count`: tick index passed through the mode ladder.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the handle's `+0x9A`/`+0x9C` window and raises bit `0x1000` of its
/// `+0x1C` flags, all under interrupt masking.
///
/// # Safety
/// The handle must be writable through `+0x9D`; `this` must be readable.
///
/// # Confidence
/// medium - the ladder, the two halfword stores and the flag are literal; the
/// inner restore argument is dropped by the export and is recovered from the
/// enclosing mask.
pub unsafe fn fn_80261fb0(this: usize, value: u32, count: u32) {
    let outer = call0_u32(IRQ_DISABLE);
    if platform::read_u32(this) == 0 {
        platform::call1(IRQ_RESTORE, outer);
        return;
    }
    let mode = platform::read_i32(this + 0x14);
    let slot = note_slot_102(signed_word_102(value), count, mode);
    store_voice_word_102(this, 0x9A, slot, 0x1000);
    platform::call1(IRQ_RESTORE, outer);
}

