/// Advances the twelve-halfword note window of a voice.
///
/// # Original
/// - Ghidra: `FUN_802631f0` at `0x802631F0` (1568 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802631f0_FUN_802631f0.c`
/// - observed: `mask; if (*this == 0) restore; else { if (+0x1C != 0 ||
///   handle[0x38] != 1) copy twelve halfwords from the source into
///   `+0x1E..+0x34` and clear `+0x1C`; dirty = FUN_80262fe0(this, source);
///   for each of the twelve fields compute delta = (new - old) / 0x60 under
///   the truncating-division idiom; build twelve `{value, delta}` pairs in the
///   order the child expects; FUN_80264400(this, &pairs, 0); then store
///   `source == 0 || delta == 0 ? source : old + delta * 0x60`; restore;
///   return dirty; }`
///
/// # Arguments
/// - `this`: voice record whose window starts at `+0x1E`.
/// - `source`: twelve halfwords in field order.
///
/// # Returns
/// `1` when the window changed, `0` when it already matched.
///
/// # Side effects
/// Copies the source window, rebuilds the twenty-four halfwords handed to
/// [`fn_80264400`] and rewrites the twelve fields.
///
/// # Safety
/// Both records must be readable/writable through `+0x34`.
///
/// # Confidence
/// medium - every delta and store is literal; the `{value, delta}` order is
/// recovered from the stack layout and the dirty flag is [`fn_80262fe0`]'s.
pub unsafe fn fn_802631f0(this: usize, source: usize) -> u32 {
    let mask = call0_u32(IRQ_DISABLE);
    let handle = platform::read_u32(this) as usize;
    if handle == 0 {
        platform::call1(IRQ_RESTORE, mask);
        return 0;
    }
    const FIELDS: [usize; 12] = [
        0x1E, 0x20, 0x22, 0x24, 0x26, 0x28, 0x2A, 0x2C, 0x2E, 0x30, 0x32, 0x34,
    ];
    const ORDER: [usize; 12] = [0, 1, 3, 4, 6, 7, 9, 10, 2, 5, 8, 11];
    if platform::read_u8(this + 0x1C) != 0 || platform::read_u16(handle + 0x38) != 1 {
        let mut index = 0usize;
        while index < 12 {
            let value = platform::read_u16(source + index * 2);
            platform::write_u16(this + FIELDS[index], value);
            index += 1;
        }
        platform::write_u8(this + 0x1C, 0);
    }
    let dirty = fn_80262fe0(this, source);
    let mut deltas = [0i16; 12];
    let mut index = 0usize;
    while index < 12 {
        let old = platform::read_u16(this + FIELDS[index]) as i32;
        let new = platform::read_u16(source + index * 2) as i32;
        deltas[index] = if new == 0 || new == old {
            0
        } else {
            ((new - old) / 0x60) as i16
        };
        index += 1;
    }
    let mut pairs = [0u16; 24];
    index = 0;
    while index < 12 {
        let field = ORDER[index];
        pairs[index * 2] = platform::read_u16(this + FIELDS[field]);
        pairs[index * 2 + 1] = deltas[field] as u16;
        index += 1;
    }
    fn_80264400(this, pairs.as_ptr() as usize, 0);
    index = 0;
    while index < 12 {
        let new = platform::read_u16(source + index * 2);
        if new == 0 || deltas[index] == 0 {
            platform::write_u16(this + FIELDS[index], new);
        } else {
            let updated = platform::read_u16(this + FIELDS[index]) as i32
                + deltas[index] as i32 * 0x60;
            platform::write_u16(this + FIELDS[index], updated as u16);
        }
        index += 1;
    }
    platform::call1(IRQ_RESTORE, mask);
    dirty
}

