/// Calls `(f64, u32, u32)`, the `0x80281610` stream-setter shape.
unsafe fn call_void_f64_u32_u32(addr: usize, value: f64, a: u32, b: u32) {
    let target: extern "C" fn(f64, u32, u32) = core::mem::transmute(addr);
    target(value, a, b);
}

/// Builds the stream-record stream from one descriptor.
///
/// # Original
/// - Ghidra: `FUN_802654f0` at `0x802654F0` (504 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802654f0_FUN_802654f0.c`
