///   else if (FUN_80265b50(this,record,&block,this[0xc],&handle) == 0) 0;
///   else { mode = min(record[8], 2); target = FUN_80268a50(mode, desc[6],
///   desc[5], desc[7], desc[8]); if (target == 0) 0; else { target[0xa8] =
///   desc[1]; target[0xac] = block[0x15]; target[0x90] = pitch^2 * amp;
///   target[0x9c] = block[0x18]; five 0x802698xx/0x802699xx stores;
///   target[0x94] = (block[0x16]-0x40)/r2[-0x4864] + desc[4]/r2[-0x4864];
///   target[0x98] = r2[-0x4860]; target[0xbc] = block[0x14];
///   target[0x3a] = (block[0x10] == 1); if (block[0] == 2) {
///   target[0xc8] = block[1]; target[0xcc] = handle; }
