    pan[2] = low + platform::read_f32(this + 0xDC) + platform::read_f32(channel + 0x60);
    pan[0] = low
        + platform::read_f32(this + 0xD4)
        + platform::read_f32(channel + 0x58)
        + platform::read_f32(this + 0x40);
    let bias = low + platform::read_f32(this + 0xD0) + platform::read_f32(channel + 0x54);
    let spread = platform::read_u32(this + 0xC8);
