    platform::write_f32(target + 0x04, volume);
    platform::write_f32(target + 0x08, width);
    platform::write_f32(target + 0x0C, height);
    platform::write_f32(target + 0x10, depth);
    platform::write_f32(target + 0x14, blend);
    fn_80265f70(target, level as f32, tag as u8);
    platform::write_u32(target + 0x20, spread);
    platform::write_f32(target + 0x24, slope);
