/// Creates the two stream lists of the sound system on first use.
unsafe fn ensure_stream_list_102() {
    if platform::read_u8(STREAM_LIST_READY_80260000) != 0 {
        return;
    }
    platform::write_u32(STREAM_LIST_HEAD_80260000, 0);
    platform::write_u32(STREAM_LIST_LINK_80260000, 0);
    platform::write_u32(STREAM_LIST_TAIL_80260000, STREAM_LIST_TAIL_80260000 as u32);
    platform::write_u32(STREAM_LIST_TAIL_80260000 + 4, STREAM_LIST_TAIL_80260000 as u32);
    platform::write_u32(STREAM_LIST_HEAD_80260000 + 8, 0);
    platform::write_u32(STREAM_LIST_HEAD_80260000 + 0x0C, 0);
    platform::call3(
        FN_802DC780,
        STREAM_LIST_HEAD_80260000 as u32,
        FN_80267CC0 as u32,
        STREAM_LIST_ANCHOR_80260000 as u32,
    );
    platform::write_u8(STREAM_LIST_READY_80260000, 1);
}

/// Releases one stream record's handle, callback and list membership.
unsafe fn release_stream_102(this: usize) {
    if platform::read_u32(this + 0xD0) == 0 {
        return;
    }
    platform::call0(FN_80281390);
    platform::call1(FN_802810A0, platform::read_u32(this + 0xD0));
    platform::write_u32(this + 0xD0, 0);
    platform::write_u8(this + 0x35, 0);
    platform::write_u8(this + 0x36, 0);
    let callback = platform::read_u32(this + 0xC0);
    if callback != 0 {
        platform::call3(callback as usize, this as u32, 0, platform::read_u32(this + 0xC4));
    }
    let owner = platform::read_u32(this + 0xC8) as usize;
    if owner != 0 {
        platform::call2(
            vtable_102(owner, 0x0C),
            owner as u32,
            platform::read_u32(this + 0xCC),
        );
    }
    if platform::read_u8(this + 0x37) == 0 {
        return;
    }
    platform::write_u8(this + 0x37, 0);
    ensure_stream_list_102();
    platform::call2(FN_80229190, STREAM_LIST_LINK_80260000 as u32, (this + 0xD8) as u32);
    fn_8026db00(STREAM_LIST_HEAD_80260000, this);
}

