    platform::write_u32(record + 0x30, platform::read_u32(SDA2_102_F32_4818));
    platform::write_u8(record + 0x35, 0);
    platform::write_u8(record + 0x36, 0);
    platform::write_u8(record + 0x37, 0);
    platform::write_u8(record + 0xA0, 0);
    platform::write_u8(record + 0xA1, 0);
    platform::write_u16(record + 0xA2, 0);
    platform::write_u16(record + 0xA4, 0);
