/// Returns `(high, low)` of one `0x802DCDxx` register-save stub.
///
/// # Safety
/// `addr` must be one of the save stubs at `0x802DCD40..0x802DCD74`.
unsafe fn save_pair_105(addr: usize) -> (u32, u32) {
    let pair = platform::call_u64(addr);
    ((pair >> 32) as u32, pair as u32)
}

/// Calls the virtual slot at `offset` of `object` with three word arguments.
///
/// # Safety
/// `object` must start with a vtable pointer and the slot must accept the call.
unsafe fn virtual3_105(object: usize, offset: usize, a: u32, b: u32, c: u32) -> u32 {
    let slot = platform::read_u32(platform::read_u32(object) as usize + offset) as usize;
    platform::call4(slot, object as u32, a, b, c)
}

/// Calls the virtual slot at `offset` of `object` with two word arguments.
///
/// # Safety
/// `object` must start with a vtable pointer and the slot must accept the call.
unsafe fn virtual2_105(object: usize, offset: usize, a: u32, b: u32) -> u32 {
    let slot = platform::read_u32(platform::read_u32(object) as usize + offset) as usize;
    platform::call3(slot, object as u32, a, b)
}

/// Tests `countLeadingZeros(x) >> 5`, the export's `x == 0` idiom.
fn clz_zero_105(x: u32) -> bool {
    x.leading_zeros() >> 5 != 0
}

/// Starts the queued child list at `+0xB48` if one is present.
///
/// # Original
/// - Ghidra: `FUN_802bc980` at `0x802BC980` (16 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802bc980_FUN_802bc980.c`
/// - observed: `if (*(int *)(param_1 + 0xb48) == 0) return; FUN_802bdf70();`
/// - `// inferred:` this is the start twin of the already-translated stop at
///   [`fn_802bc9c0`], which forwards the `+0xB48` list to `0x802BDDF0`.
/// - `// unknown:` the export prints the callee without arguments, so only `r3`
///   (`this`, untouched by the guard load) is certain at the call site.
///
/// # Arguments
/// - `this`: owner record whose child list lives at `+0xB48`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Enqueues one step on the child list behind `+0xB48`.
///
/// # Safety
/// `this + 0xB48` must be readable and a non-zero child a live list owner.
///
/// # Confidence
/// medium - the guard and the callee are literal; the forwarded `r3` is
/// inferred from the stop twin, the other three registers are not recovered.
pub unsafe fn fn_802bc980(this: usize) {
    if platform::read_u32(this + CHILD_LIST_SLOT_105) == 0 {
        return;
    }
    platform::call1(FN_802BDF70_105, this as u32);
}

/// Advances the timed child list at `+0xB48` if one is present.
