const SDA2_105_F32_3F38: usize = SDA2_BASE - 0x3F38;
/// `r2 - 0x3F40`: the `2^52` bias of the int-to-double idiom.
const SDA2_105_F64_3F40: usize = SDA2_BASE - 0x3F40;
