const SDA2_105_F32_3F48: usize = SDA2_BASE - 0x3F48;

/// Calls a function taking eight word arguments.
///
/// # Safety
/// `addr` must accept the eight `u32` arguments and return `u32`.
unsafe fn call8_105(
    addr: usize,
    a: u32,
    b: u32,
    c: u32,
    d: u32,
    e: u32,
    f: u32,
    g: u32,
    h: u32,
) -> u32 {
    let target: extern "C" fn(u32, u32, u32, u32, u32, u32, u32, u32) -> u32 =
        core::mem::transmute(addr);
    target(a, b, c, d, e, f, g, h)
}

/// Calls a function taking three doubles and five word arguments.
///
/// # Safety
/// `addr` must accept the `(f64, f64, f64, u32 x5)` shape.
unsafe fn call_3f64_5w_105(
    addr: usize,
    x: f64,
    y: f64,
    z: f64,
    a: u32,
    b: u32,
    c: u32,
    d: u32,
    e: u32,
) {
    let target: extern "C" fn(f64, f64, f64, u32, u32, u32, u32, u32) = core::mem::transmute(addr);
    target(x, y, z, a, b, c, d, e);
}

/// Calls a function taking six doubles.
///
/// # Safety
/// `addr` must accept the `(f64 x6)` shape.
unsafe fn call_6f64_105(addr: usize, a: f64, b: f64, c: f64, d: f64, e: f64, f: f64) {
    let target: extern "C" fn(f64, f64, f64, f64, f64, f64) = core::mem::transmute(addr);
    target(a, b, c, d, e, f);
}

/// Reads one big-endian `f64` from two consecutive words.
///
/// # Safety
/// `addr` must be readable for eight bytes.
unsafe fn read_f64_105(addr: usize) -> f64 {
    let bits = ((platform::read_u32(addr) as u64) << 32) | platform::read_u32(addr + 4) as u64;
    f64::from_bits(bits)
}

/// Calls a function taking six doubles and one trailing pointer.
///
/// # Safety
/// `addr` must accept the `(f64 x6, usize)` shape.
unsafe fn call_6f64_ptr_105(
    addr: usize,
    a: f64,
    b: f64,
    c: f64,
    d: f64,
    e: f64,
    f: f64,
    out: usize,
) {
    let target: extern "C" fn(f64, f64, f64, f64, f64, f64, usize) = core::mem::transmute(addr);
    target(a, b, c, d, e, f, out);
}

/// Programs the standard GX state block used by the window overlay.
///
/// # Original
/// - Ghidra: `FUN_802bba30` at `0x802BBA30` (920 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802bba30_FUN_802bba30.c`
/// - observed: a fixed sequence of `0x801C6D90`/`0x801C6FF0`/`0x801C1350`/
