    fn_802be5d0(GX_MATRICES_105, 0);
    platform::call1(FN_801C9A60_105, 0);
    platform::call0(FN_801C4070_105);
    platform::call2(FN_801C37C0_105, 9, 1);
    platform::call2(FN_801C37C0_105, 0xD, 1);
    platform::call5(FN_801C40B0_105, 0, 9, 0, 2, 0);
    platform::call5(FN_801C40B0_105, 0, 0xD, 1, 0, 0);
    platform::call1(FN_801C6AC0_105, 0);
    platform::call7(FN_801C6AF0_105, 4, 0, 0, 0, 0, 0, 2);
    platform::call7(FN_801C6AF0_105, 5, 0, 0, 0, 0, 0, 2);
    platform::call1(FN_801C4A20_105, 1);
    platform::call6(FN_801C47D0_105, 0, 1, 4, 0x3C, 0, 0x7D);
    platform::call2(FN_801C74C0_105, GX_STATE_105 as u32, 0);
    platform::call1(FN_801C88F0_105, 1);
    let word = [platform::read_u32(params)];
    platform::call2(FN_801C8430_105, 1, word.as_ptr() as u32);
    platform::call4(FN_801C8790_105, 0, 0, 0, 0xFF);
    platform::call5(FN_801C82F0_105, 0, 0xF, 0xF, 0xF, 2);
    platform::call6(FN_801C8370_105, 0, 0, 0, 0, 1, 0);
    platform::call5(FN_801C8330_105, 0, 7, 7, 7, 1);
    platform::call6(FN_801C83D0_105, 0, 0, 0, 0, 1, 0);
    platform::call5(FN_801C86C0_105, 7, 0, 1, 7, 0);
    platform::call3(FN_801C8700_105, 2, 0x16, 0);
    platform::call1(FN_801C8EB0_105, 0);
    platform::call4(FN_801C8DC0_105, 0, 0, 0, 5);
    platform::call1(FN_801C8E40_105, 1);
    platform::call2(FN_801C8FC0_105, 1, platform::read_u8(params + 3) as u32);
    platform::call3(FN_801C8E70_105, 1, 7, 1);
    platform::call1(FN_801C5860_105, 2);
    platform::call3(FN_801C5570, 0x80, 0, 4);
