const SDA2_SPRITE_TAIL_A: usize = SDA2_BASE - 0x3E7A;

/// Calls a no-argument routine that returns a word.
unsafe fn call_u32_0_a(addr: usize) -> u32 {
    let target: extern "C" fn() -> u32 = core::mem::transmute(addr);
    target()
}

/// Calls `(f32, f32, f32, ptr)`, the `0x801C0C60` position-block shape.
unsafe fn call_f32x3_ptr_a(addr: usize, x: f32, y: f32, z: f32, out: *mut u8) {
    let target: extern "C" fn(f32, f32, f32, *mut u8) = core::mem::transmute(addr);
    target(x, y, z, out);
}

/// Calls `(f32, f32, f32, f32, u32, ptr)`, the `0x801C8920` ortho/window shape.
unsafe fn call_f32x4_u32_ptr_a(
    addr: usize,
    left: f32,
    right: f32,
    bottom: f32,
    top: f32,
    mode: u32,
    out: *mut u8,
) {
    let target: extern "C" fn(f32, f32, f32, f32, u32, *mut u8) = core::mem::transmute(addr);
    target(left, right, bottom, top, mode, out);
}

/// Dispatches slot `+0x0C` of the sub-vtable at `+0x28` with two scalars.
unsafe fn vcall_f32_pair_a(this: usize, x: f32, y: f32) {
    let slot = platform::read_u32(platform::read_u32(this + 0x28) as usize + 0x0C) as usize;
    let target: extern "C" fn(u32, f32, f32) = core::mem::transmute(slot);
    target(this as u32, x, y);
}

/// Reads slot `+0x3C` of the vtable at `+0x04`: the child count of one panel.
unsafe fn vcall_count_a(this: usize) -> u32 {
    let slot = platform::read_u32(platform::read_u32(this + 0x04) as usize + 0x3C) as usize;
    let target: extern "C" fn(u32) -> u32 = core::mem::transmute(slot);
    target(this as u32)
}

/// Dispatches slot `+0x20` of a child's own vtable with `(state, enable)`.
unsafe fn vcall_state_a(this: usize, state: u32, enable: u32) {
    let slot = platform::read_u32(platform::read_u32(this) as usize + 0x20) as usize;
    let target: extern "C" fn(u32, u32, u32) = core::mem::transmute(slot);
    target(this as u32, state, enable);
}

/// Blends one four-byte colour toward another, byte by byte.
///
/// The factor is compared against the two `SDA2` bounds first: at or below the
/// lower bound the source colour is copied unchanged, at or above the upper
/// bound the target colour is copied, and only the open interval is blended.
///
/// # Original
/// - Ghidra: `FUN_802c0450` at `0x802C0450` (392 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c0450_FUN_802c0450.c`
/// - observed: `lfs f0,0xC190(r2); fcmpo cr0,f1,f0; cror 2,0,2; bc 4,2,...`
///   copies `r4[0..4]` to `r3` and returns; then the same test against
///   `0xC194(r2)` copies `r5[0..4]` and returns. `0xC190`/`0xC194` are
///   `0.0`/`1.0`, so both tests are "factor is above the bound".
/// - observed: the blend reloads `0x43300000` pairs into the stack words
///   `+0x08`/`+0x10`, stores `b[i] - a[i]` with `xoris ...,0x8000` in `+0x14`
///   and `a[i]` in `+0x0C`, then subtracts the two `SDA2` conversion biases
///   (`2^52` at `r2 - 0x3E68`, `2^52 + 2^31` at `r2 - 0x3E60`). Those pairs
///   are the compiler's `i32 -> f64` conversions and are written here as plain
///   `as f32` casts, exactly as in [`fn_802b0680`].
/// - observed: `fctiwz` truncates the blended value and `stb` keeps its low
///   byte, so the body is `a[i] + t * (b[i] - a[i])` per byte.
///
/// # Arguments
/// - `t`: blend factor (`f1`; single precision, the body only uses `fmuls`).
/// - `out`: four-byte destination (`r3`).
/// - `from`: four-byte colour used at or below the lower bound (`r4`).
/// - `to`: four-byte colour used at or above the upper bound (`r5`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the four bytes at `out`.
///
/// # Safety
/// All three pointers must be readable/writable for four bytes.
///
/// # Confidence
/// high - both guards, the four-byte copies and the blend arithmetic are
/// literal; only the two bounds are named by their values.
pub unsafe fn fn_802c0450(t: f32, out: usize, from: usize, to: usize) {
    let low = platform::read_f32(SDA2_LERP_LOW_A);
    let high = platform::read_f32(SDA2_LERP_HIGH_A);
    if t > low {
        if t < high {
            let mut index = 0;
            while index < 4 {
                let start = platform::read_u8(from + index) as i32;
                let end = platform::read_u8(to + index) as i32;
                let blended = start as f32 + t * (end - start) as f32;
                platform::write_u8(out + index, blended as i32 as u8);
                index += 1;
            }
        } else {
            let mut index = 0;
            while index < 4 {
                platform::write_u8(out + index, platform::read_u8(to + index));
                index += 1;
            }
        }
    } else {
        let mut index = 0;
        while index < 4 {
            platform::write_u8(out + index, platform::read_u8(from + index));
            index += 1;
        }
    }
}

/// Fills and binds the material block of one pane object.
///
/// `0x802C0BA0` builds a `0x24`-byte material block from the pane object and
/// `0x801C74C0` (a GX material binder) consumes it, so the whole body is a
/// stack block plus two calls.
///
/// # Original
/// - Ghidra: `FUN_802c0b60` at `0x802C0B60` (60 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c0b60_FUN_802c0b60.c`
/// - observed: `stwu r1,-0x30`; `addi r4,r1,8; bl 0x802C0BA0`;
///   `addi r3,r1,8; bl 0x801C74C0`; the block at `r1+8` is `0x24` bytes.
///
/// # Arguments
/// - `pane`: pane object passed through to `0x802C0BA0` (`r3`).
/// - `material`: material word handed to the GX binder (`r4`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the GX material state through `0x801C74C0`.
///
/// # Safety
/// `pane` must be a live pane object with a readable `+0x00..` block.
///
/// # Confidence
/// high - the block size, both call targets and the argument order are literal.
pub unsafe fn fn_802c0b60(pane: usize, material: u32) {
    let mut record = [0u8; 0x24];
    let record_ptr = record.as_mut_ptr() as usize;
    platform::call2(FN_802C0BA0_A, pane as u32, record_ptr as u32);
    platform::call2(FN_801C74C0_105, record_ptr as u32, material);
}

/// Allocates the `0x20`-byte GIF buffer of one pane and binds it.
///
/// The pane's texture object is created from the size pair at `+0x04`/`+0x06`,
/// the format byte at `+0x09` and `(0, 1)`, then a `0x20`-byte buffer is
/// allocated from the pool named by the second argument (or by the `SDA` default
/// when that argument is `0`) and bound through `0x802C0B40`.
///
/// # Original
/// - Ghidra: `FUN_802c11e0` at `0x802C11E0` (132 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c11e0_FUN_802c11e0.c`
/// - observed: `cmpi cr0,r4,0; bc 4,2,...` then `lwz r31,-0x4870(r13)`, so a
///   zero selection word is replaced by the `r13` default.
/// - observed: `lhz r3,4(r3); lhz r4,6(r30); lbz r5,9(r30); li r6,0; li r7,1;
///   bl 0x801C6BA0`, then `li r5,0x20; bl 0x802B9270`, then
///   `stw r3,0x14(r30)`, `bl 0x802C0B40` and `ori 0x4` on byte `+0x08`.
///
/// # Arguments
/// - `pane`: pane object (`r3`).
/// - `selection`: pool/selection word (`r4`); `0` selects the `SDA` default.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Allocates a `0x20`-byte buffer, stores it at `+0x14`, binds it and sets bit
/// `0x04` of the byte at `+0x08`.
///
/// # Safety
/// `pane` must be a live pane object; the selected pool must be initialised.
///
/// # Confidence
/// high - every field offset, the `0x20` size and the `0x04` flag are literal;
/// only the meaning of the selection word is inferred from its two call sites.
pub unsafe fn fn_802c11e0(pane: usize, selection: u32) {
    let selection = if selection == 0 {
        platform::read_u32(SDA_ARC_DEFAULT_SELECTION_A)
    } else {
        selection
    };
    let texture = platform::call5(
        FN_801C6BA0_A,
        platform::read_u16(pane + 0x04) as u32,
        platform::read_u16(pane + 0x06) as u32,
        platform::read_u8(pane + 0x09) as u32,
        0,
        1,
    );
    let buffer = platform::call3(FN_802B9270_A, texture, selection, 0x20);
    platform::write_u32(pane + 0x14, buffer);
    platform::call2(FN_802C0B40_A, pane as u32, buffer);
    platform::write_u8(pane + 0x08, platform::read_u8(pane + 0x08) | 0x04);
}

/// Four-byte tail thunk onto [`fn_802c11e0`].
///
/// The shipped body is the single instruction `b 0x802C11E0` (no link
/// register, no prologue), so this alias forwards both arguments unchanged.
///
/// # Original
/// - Ghidra: `thunk_FUN_802c11e0` at `0x802C1270` (4 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c1270_thunk_FUN_802c11e0.c`
/// - observed: the export is byte-for-byte the `0x802C11E0` body because
///   Ghidra follows the tail branch; the image word is `4BFFFF70`, i.e.
///   `b 0x802C11E0` with `AA = LK = 0`.
///
/// # Arguments
/// - `pane`: pane object, forwarded in `r3`.
/// - `selection`: selection word, forwarded in `r4`.
///
/// # Returns
/// Nothing.
///
/// # Safety
/// Same contract as [`fn_802c11e0`].
///
/// # Confidence
/// high - the four displaced bytes decode to one unconditional tail branch.
pub unsafe fn fn_802c1270(pane: usize, selection: u32) {
    fn_802c11e0(pane, selection);
}

/// Builds a `0x40`-byte window block from one colour word and binds it.
///
/// The colour is the first word of the source object; `0x802C7C70` expands it
/// into the window block with the fixed flags `(0, 0, 1, 1)` and
/// `0x801C74C0` binds that block.
///
/// # Original
/// - Ghidra: `FUN_802c2300` at `0x802C2300` (88 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c2300_FUN_802c2300.c`
/// - observed: `lwz r0,0(r3); stw r0,8(r1)` copies the colour to a stack word,
///   then `li r5,0; li r6,0; li r7,1; li r8,1; addi r3,r1,0x10;
///   addi r4,r1,8; bl 0x802C7C70`, then `bl 0x801C74C0` on the same block.
///
/// # Arguments
/// - `source`: object whose first word is the colour (`r3`).
/// - `material`: material word handed to the GX binder (`r4`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the GX material state through `0x801C74C0`.
///
/// # Safety
/// `source` must be readable for four bytes.
///
/// # Confidence
/// high - the copied word, the six arguments and both call targets are literal.
pub unsafe fn fn_802c2300(source: usize, material: u32) {
    let colour = platform::read_u32(source);
    let mut record = [0u8; 0x40];
    let record_ptr = record.as_mut_ptr() as usize;
    platform::call6(
        FN_802C7C70_A,
        record_ptr as u32,
        &colour as *const u32 as u32,
        0,
        0,
        1,
        1,
    );
    platform::call2(FN_801C74C0_105, record_ptr as u32, material);
}

/// Applies one colour and one texture-object pair to a GX matrix block.
///
/// The matrix block is reset through `0x801C9940`/`0x801C99C0`, the colour word
/// is handed to `0x801C69E0` as a four-byte payload, and the GX texture object
/// is selected from the eight-byte handle table indexed by the first argument.
///
/// # Original
/// - Ghidra: `FUN_802c2f70` at `0x802C2F70` (136 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c2f70_FUN_802c2f70.c`
/// - observed: `bl 0x801C9940` and `bl 0x801C99C0` both take the block in `r3`
///   and `0` in `r4`; `lwz r0,0(r31); stw r0,8(r1); li r3,4;
///   addi r4,r1,8; bl 0x801C69E0`; then `lis r3,0x8042; addi r3,r3,0x45B8;
///   rlwinm r0,r29,3,0,28; lwzx r3,r3,r0; lwz r4,4(r3+idx*8);
///   bl 0x801C95E0`.
///
/// # Arguments
/// - `index`: entry index into the `0x804245B8` handle table (`r3`).
/// - `matrix`: `0x28`-byte matrix block (`r4`).
/// - `colour`: four-byte colour word (`r5`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes one matrix block and one texture object into the GX FIFO.
///
/// # Safety
/// `matrix` must be a writable `0x28`-byte block, `colour` readable for four
/// bytes, and `index` must be inside the `0x804245B8` table.
///
/// # Confidence
/// high - the table, the eight-byte stride, the payload size and the argument
/// order are literal; the roles of the two calls are inferred from their
/// neighbours in the same band.
pub unsafe fn fn_802c2f70(index: u32, matrix: usize, colour: usize) {
    platform::call2(FN_801C9940_105, matrix as u32, 0);
    platform::call2(FN_801C99C0_A, matrix as u32, 0);
    let value = platform::read_u32(colour);
    platform::call2(FN_801C69E0, 4, &value as *const u32 as u32);
    let entry = ARC_TEXOBJ_TABLE_A + (index as usize) * 8;
    platform::call2(
        FN_801C95E0_A,
        platform::read_u32(entry),
        platform::read_u32(entry + 0x04),
    );
}

/// Walks every child slot of one panel list and resets its state pair.
///
/// The count comes from slot `+0x3C` of the vtable at `+0x04` (re-read on every
/// iteration because the list is rebuilt in between), `0x802C7EF0` creates the
/// twelve-byte child slots, and each child's own vtable slot `+0x20` is called
/// with the states `8, 2, 3, 4, 5` enabled. The tail then clears state `5` of
/// the first child, programs its four state words through
/// `0x80257720`/`0x802576A0`/`0x802576E0` and stores the panel's `+0x14`
/// address (or `0` for a null panel) at child `+0xD4`.
///
/// # Original
/// - Ghidra: `FUN_802c32b0` at `0x802C32B0` (432 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c32b0_FUN_802c32b0.c`
/// - observed: `lwz r12,4(r3); lwz r12,0x3C(r12); bcctr` then
///   `rlwinm r4,r0,0,16,31; addi r3,r31,8; bl 0x802C7EF0`, and the loop test
///   `bl`-style dispatch of the same slot followed by
///   `cmpl cr0,(r29&0xFFFF),r3` with `bc 12,0` back to the body.
/// - observed: each body iteration forms `r30 = (r29 & 0xFFFF) * 12`, reads
///   `*(int **)(*(int *)(r31 + 8) + r30 + 4)` and calls its `+0x20` slot five
///   times with `(8,1) (2,1) (3,1) (4,1) (5,1)`.
/// - observed: the tail re-reads `*(int *)(r31 + 8)` and takes `+4` as the
///   first child, calls its `+0x20` slot once more with `(5,0)`, then
///   `0x80257720(child,4)`, `0x802576A0(child,1)`, `0x802576E0(child,2)`,
///   `0x802576E0(child,4)` and `stw r31(+0x14 or 0),0xD4(child)`.
///
/// # Arguments
/// - `panel`: panel list object (`r3`).
/// - `arg`: word forwarded to `0x802C7EF0` (`r4`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Rebuilds the child slots, toggles five child states, clears one and writes
/// four state words plus one back-pointer.
///
/// # Safety
/// `panel` must be live with a readable `+0x04` vtable, a readable `+0x08`
/// list pointer and valid child objects with readable vtables.
///
/// # Confidence
/// high - the vtable slots, the twelve-byte stride, the state values and the
/// `+0xD4` store are literal; the meaning of the five states is inferred from
/// their use here.
pub unsafe fn fn_802c32b0(panel: usize, arg: u32) {
    let count = vcall_count_a(panel) & 0xFFFF;
    platform::call3(FN_802C7EF0_A, (panel + 0x08) as u32, count, arg);
    let mut index: u32 = 0;
    loop {
        let total = vcall_count_a(panel) & 0xFFFF;
        if (index & 0xFFFF) >= total {
            break;
        }
        let slot = platform::read_u32(panel + 0x08) as usize + (index & 0xFFFF) as usize * 12;
        for state in [8u32, 2, 3, 4, 5] {
            let child = platform::read_u32(slot + 0x04) as usize;
            vcall_state_a(child, state, 1);
        }
        index += 1;
    }
    let first = platform::read_u32(platform::read_u32(panel + 0x08) as usize + 0x04) as usize;
    vcall_state_a(first, 5, 0);
    platform::call2(FN_80257720_A, first as u32, 4);
    platform::call2(FN_802576A0_A, first as u32, 1);
    platform::call2(FN_802576E0_A, first as u32, 2);
    platform::call2(FN_802576E0_A, first as u32, 4);
    let back = if panel != 0 { (panel + 0x14) as u32 } else { 0 };
    platform::write_u32(first + 0xD4, back);
}

/// Deleting destructor of the panel object: release the child block, then free.
///
/// # Original
/// - Ghidra: `FUN_802c34b0` at `0x802C34B0` (92 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c34b0_FUN_802c34b0.c`
/// - observed: `cmpi cr0,r3,0; bc 12,2,end` skips everything for a null object,
///   `addi r3,r3,8; li r4,0; bl 0x802C7E30`, then `cmpi cr0,r31,0;
///   bc 4,1,end` frees only when the flag is greater than zero, and `r3` is
///   reloaded from `r30` before the return.
///
/// # Arguments
/// - `panel`: panel object (`r3`).
/// - `flag`: destructor flag (`r4`); only a positive value frees the object.
///
/// # Returns
/// The `panel` pointer, as in every Metrowerks deleting destructor.
///
/// # Side effects
/// Releases the sub-object at `+0x08` and frees `panel` when `flag > 0`.
///
/// # Safety
/// `panel` must be a live object or null.
///
/// # Confidence
/// high - both guards, both call targets and the `r3` reload are literal.
pub unsafe fn fn_802c34b0(panel: usize, flag: i32) -> usize {
    if panel != 0 {
        platform::call2(FN_802C7E30_A, (panel + 0x08) as u32, 0);
        if flag > 0 {
            platform::call1(HEAP_DELETE, panel as u32);
        }
    }
    panel
}

/// Deleting destructor without the child-block release.
///
/// Identical to [`fn_802c34b0`] except that the `0x802C7E30` call on `+0x08`
/// is absent, which is what distinguishes the two destructors of this class
/// family in the shipped image.
///
/// # Original
/// - Ghidra: `FUN_802c35f0` at `0x802C35F0` (64 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c35f0_FUN_802c35f0.c`
/// - observed: `cmpi cr0,r3,0; bc 12,2,end`, `cmpi cr0,r4,0; bc 4,1,end`,
///   `bl 0x802B9280` (with `r3` still the object) and `mr r3,r31` before the
///   return; there is no second callee.
///
/// # Arguments
/// - `panel`: panel object (`r3`).
/// - `flag`: destructor flag (`r4`); only a positive value frees the object.
///
/// # Returns
/// The `panel` pointer.
///
/// # Side effects
/// Frees `panel` when `flag > 0`.
///
/// # Safety
/// `panel` must be a live object or null.
///
/// # Confidence
/// high - the export and the disassembly agree on both guards and on the single
/// heap call.
pub unsafe fn fn_802c35f0(panel: usize, flag: i32) -> usize {
    if panel != 0 && flag > 0 {
        platform::call1(HEAP_DELETE, panel as u32);
    }
    panel
}

/// Builds or tears down the two-mode panel set of one HUD screen.
///
/// This is the largest body of the band. `r3` is the panel owner and `r4` is the
/// mode word; both are recovered from the disassembly because the export models
/// the `_savegpr_19` prologue as a call that "returns" `(r3, r4)` and therefore
/// declares the function argument-less.
///
/// Mode `0` builds the screen: the three GX state words are pushed to `1`, the
/// pixel extents of the HUD record and of the geometry record are halved (by
/// `2`, or by `4` when bit `0x04` of the owner's `+0x1C` is set), an animation
/// handle is created, and the panel kind at `+0x20` selects between the small
/// (`kind 0`, texture `0x13`, one pane) and the two-pane (`kind 1`, texture
/// `0x16`, plus the `0x801C0C60` projection, the fixed GX state ladder and the
/// `0x27` pane) layouts. Both then fall into the shared tail, which stores the
/// sprite at `[owner+0x84]+4`, marks `+8 = 1`, and lays out four further panes
/// (`0x28`, `0x27`, one more `0x28` pane and the `+0x80` overlay) through the
/// `0x802D3700` factory, two window blocks and the lane table at
/// `0x803504E0`.
/// Mode `2` is the teardown: it releases the pane object through `0x802CEE70`,
/// resets the pane transform state, re-binds the material of `[owner+0x88]`
/// and re-runs the `0x801C0C60`/`0x802C2F70` projection pair.
///
/// # Original
/// - Ghidra: `FUN_802c3d80` at `0x802C3D80` (2424 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c3d80_FUN_802c3d80.c`
/// - observed: the extent is exactly `0x802C3D80..0x802C46F8`; the prologue is
///   `stwu r1,-0x160`, `mfspr r0,LR`, `stw r0,0x164(r1)`, `addi r11,r1,0x130`,
///   the three `stfd`/`psq_st` pairs for `f29..f31` and `bl 0x802DCD54`
///   (`_savegpr_19`), and the epilogue at `0x802C46C8` restores the same set
///   and calls `0x802DCDA0` (`_restgpr_19`).
/// - observed: `mr r21,r3; mr r19,r4` then `cmpi cr0,r19,0`,
///   `cmpi cr0,r19,2`, i.e. the mode word is the second argument.
/// - observed: the export's `(double)CONCAT44(0x43300000,x) - *(double *)
///   (r2 + -0x3D18)` pairs are again the compiler's `i32 -> f64` conversions
///   (`0x4330000000000000` at `0x8042F368`); they are written here as `as f32`
///   casts, and the `xoris ...,0x8000` variants are the signed form of the same
///   conversion.
/// - observed: the two lane/index ladders both read `lhz r6,0x34(hud)` and test
///   `rlwinm. r0,r6,0,26,26` (bit `0x20`) and `rlwinm. r0,r6,0,28,28` (bit
///   `0x08`), falling back to `lwz r0,-0x4778(r13)`.
/// - observed: the ratio terms multiply the halved extents by the halfwords at
///   `0x803504E0 + lane*12` and `+2` and divide by the halfwords at
///   `r13 - 0x4748` / `r13 - 0x4746`, then feed the `+0x0C` slot of the
///   `+0x28` sub-vtable of `[owner+0x84]`, `[owner+0x80]` and the stack window
///   block at `r1+0x58`.
/// - observed: the three `802D2F20`/`802D2F80`/`802D2FE0` state words are saved
///   and restored around both window draws, exactly as the export's
///   `uVar17/uVar18/uVar19` save triple shows.
/// - `// inferred:` the owner is the screen/scene controller of the title and
///   file-select menus: the body only proves the offsets, the mode ladder, the
///   constants and the callees.
///
/// # Arguments
/// - `owner`: panel owner (`r3`), holding the `+0x1C` flag word, the `+0x20`
///   panel kind, the `+0x24`/`+0x28` centre and half-extent floats, and the
///   `+0x80`/`+0x84`/`+0x88` sub-objects.
/// - `mode`: `0` builds the set, `2` tears it down; every other value returns
///   immediately.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Creates or destroys up to six panes, allocates two stack window blocks,
/// reprograms the GX state ladder and issues the material and matrix commands
/// of both modes.
///
/// # Safety
/// `owner` must be a live controller; the `SDA`/`SDA2` records it dereferences
/// (HUD owner, lane spans, lane index) must be initialised, and every pane the
/// factories return must stay live until the matching `0x802D3370` call.
///
/// # Confidence
/// high - all 606 instructions were decoded and every offset, constant, branch
/// and callee is literal. The lane index is computed once here where the
/// compiler duplicated the same three-instruction ladder; nothing in between
/// touches `hud+0x34`, so the values are identical.
pub unsafe fn fn_802c3d80(owner: usize, mode: u32) {
    let hud = platform::read_u32(G_ARC_HUD_OWNER_A) as usize;
    let geometry = platform::call1(FN_802D17C0_A, hud as u32) as usize;
    let geometry_x = platform::read_f32(geometry) as i32;
    let geometry_y = platform::read_f32(geometry + 0x04) as i32;

    if mode == 0 {
        platform::call1(FN_802D2F20_A, 1);
        platform::call1(FN_802D2F80_A, 1);
        platform::call1(FN_802D2FE0_A, 1);

        let mut divisor: u32 = 2;
        if platform::read_u16(owner + 0x1C) & 0x04 != 0 {
            divisor = 4;
        }

        // Halved HUD pixel extents (`r23`/`r22`).
        let hud_x = (platform::read_f32(hud + 0x08) as i32 & 0xFFFF) as u32 / divisor;
        let hud_y = (platform::read_f32(hud + 0x0C) as i32 & 0xFFFF) as u32 / divisor;
        // Halved geometry extents (`r25`/`r24`).
        let cell_x = (platform::read_f32(geometry + 0x08) / divisor as f32) as i32;
        let cell_y = (platform::read_f32(geometry + 0x0C) / divisor as f32) as i32;

        let animation = platform::call3(FN_802D1E20_A, 3, 1, owner as u32);
        platform::call1(FN_802CEE70_A, hud as u32);

        let mut sprite: usize = 0;
        let kind = platform::read_u32(owner + 0x20);
        if kind == 0 {
            let panel = platform::read_u32(owner + 0x84) as usize;
            platform::write_u32(panel + 0x60, 0);
            let created = platform::call3(
                FN_802D3700_A,
                (platform::read_f32(geometry + 0x08) as i32 & 0xFFFF) as u32,
                (platform::read_f32(geometry + 0x0C) as i32 & 0xFFFF) as u32,
                3,
            ) as usize;
            platform::write_u8(created + 0x0C, 0);
            platform::write_u8(created + 0x0D, 0);
            sprite = created;
            platform::call5(
                FN_802C02C0_A,
                created as u32,
                (geometry_x & 0xFFFF) as u32,
                (geometry_y & 0xFFFF) as u32,
                0,
                0x13,
            );
        } else if kind == 1 {
            let panel = platform::read_u32(owner + 0x84) as usize;
            platform::write_u32(panel + 0x60, 2);
            let created = platform::call3(
                FN_802D3700_A,
                (platform::read_f32(geometry + 0x08) as i32 & 0xFFFF) as u32,
                (platform::read_f32(geometry + 0x0C) as i32 & 0xFFFF) as u32,
                6,
            ) as usize;
            platform::write_u8(created + 0x0C, 0);
            platform::write_u8(created + 0x0D, 0);
            platform::call5(
                FN_802C02C0_A,
                created as u32,
                (geometry_x & 0xFFFF) as u32,
                (geometry_y & 0xFFFF) as u32,
                0,
                0x16,
            );
            fn_802c0b60(created, 0);

            // Projection block of the kind-1 pane set (`r1+0x98`).
            let mut matrix = [0u8; 0x28];
            let matrix_ptr = matrix.as_mut_ptr() as usize;
            call_f32x3_ptr_a(
                FN_801C0C60_A,
                hud_x as f32,
                hud_y as f32,
                platform::read_f32(SDA2_ONE_A),
                matrix.as_mut_ptr(),
            );
            platform::call2(FN_802D2E90_A, 0, 0);

            // Orthographic window over the owner's centre and half-extent.
            let mut depth = [0u8; 4];
            let depth_ptr = depth.as_mut_ptr() as usize;
            platform::write_u32(depth_ptr, platform::read_u32(SDA2_DESC_3FFF_A));
            let extent = platform::read_f32(owner + 0x28) * platform::read_f32(SDA2_HALF_A);
            let centre = platform::read_f32(owner + 0x24);
            call_f32x4_u32_ptr_a(
                FN_801C8920_A,
                centre - extent,
                centre + extent,
                platform::read_f32(hud + 0x18),
                platform::read_f32(hud + 0x1C),
                2,
                depth.as_mut_ptr(),
            );
            platform::call3(FN_801C8CB0_A, 0, 0, 0);
            platform::call1(FN_802C1F80_A, 1);
            platform::call1(FN_802C2060_A, 1);
            platform::call0(FN_802C20E0_A);
            platform::call1(FN_801C88F0, 1);
            platform::call5(FN_801C8640_A, 0, 0, 1, 2, 3);
            platform::call1(FN_801C8130, 0);
            platform::call3(FN_801C8600_A, 0, 0, 0);
            platform::call4(FN_801C8790_105, 0, 0, 0, 0xFF);
            platform::call5(FN_801C82F0_105, 0, 0x0F, 0x0F, 0x0F, 0x0F);
            platform::call6(FN_801C8370_105, 0, 0, 0, 0, 1, 0);
            platform::call5(FN_801C8330_105, 0, 7, 7, 7, 7);
            platform::call6(FN_801C83D0_105, 0, 0, 0, 0, 1, 0);
            platform::call3(FN_801C8700_105, 2, 0x16, 0);
            platform::call3(FN_801C8E70, 0, 7, 0);
            platform::call1(FN_801C8EB0, 0);
            platform::call5(FN_801C86C0, 7, 0, 1, 7, 0);
            platform::call4(FN_801C8DC0, 2, 1, 1, 7);
            platform::call1(FN_802C2360_A, 0x0B);

            let mut tint = 0u32;
            fn_802c2f70(0x10, matrix_ptr, &mut tint as *mut u32 as usize);

            let mut scissor = [0u8; 4];
            let scissor_ptr = scissor.as_mut_ptr() as usize;
            platform::write_u32(scissor_ptr, platform::read_u32(SDA2_DESC_FF_A));
            call_f32x4_u32_ptr_a(
                FN_801C8920_A,
                platform::read_f32(SDA2_ZERO_A),
                platform::read_f32(SDA2_ONE_A),
                platform::read_f32(SDA2_ZERO_A),
                platform::read_f32(SDA2_ONE_A),
                0,
                scissor.as_mut_ptr(),
            );
            platform::call3(FN_801C8700_105, 0, 0x16, 0);
            platform::call2(
                FN_802D2E90_A,
                platform::read_u32(G_ARC_VIEWPORT_A_A),
                platform::read_u32(G_ARC_VIEWPORT_B_A),
            );
            platform::call1(FN_802D3370_A, created as u32);

            // Kind-1 second pane (texture 0x27).
            let second = platform::call3(
                FN_802D3700_A,
                (cell_x & 0xFFFF) as u32,
                (cell_y & 0xFFFF) as u32,
                1,
            ) as usize;
            platform::write_u8(second + 0x18, platform::read_u8(second + 0x18) | 0x08);
            platform::write_u32(second + 0x24, platform::read_u32(SDA2_SPRITE_COLOUR_A));
            platform::write_u16(second + 0x28, platform::read_u16(SDA2_SPRITE_SIZE_A));
            platform::write_u8(second + 0x2A, platform::read_u8(SDA2_SPRITE_TAIL_A));
            platform::call5(
                FN_802C02C0_A,
                second as u32,
                (geometry_x & 0xFFFF) as u32,
                (geometry_y & 0xFFFF) as u32,
                0,
                0x27,
            );
            sprite = second;
        }

        // Shared tail: publish the sprite and lay out the four-cell set.
        platform::call0(FN_801C76C0_A);
        let panel = platform::read_u32(owner + 0x84) as usize;
        platform::write_u32(panel + 0x08, 1);
        let panel = platform::read_u32(owner + 0x84) as usize;
        platform::write_u32(panel + 0x04, sprite as u32);

        let layout = call_u32_0_a(FN_802D2550_A) as usize;
        let layout_x = platform::read_f32(layout) as i32;
        let layout_y = platform::read_f32(layout + 0x04) as i32;

        let flags = platform::read_u16(hud + 0x34);
        let half = platform::read_f32(SDA2_HALF_A);
        let lane = if flags & 0x20 == 0 {
            0usize
        } else if flags & 0x08 != 0 {
            2
        } else {
            platform::read_u32(G_ARC_LANE_INDEX_A) as usize
        };
        let lane_entry = ARC_LANE_TABLE_A + lane * 12;
        let scale_a = (cell_y & 0xFFFF) as f32 * platform::read_u16(lane_entry) as f32
            / platform::read_u16(G_ARC_LANE_SPAN_X_A) as f32;
        let scale_b = (cell_x & 0xFFFF) as f32 * platform::read_u16(lane_entry + 0x02) as f32
            / platform::read_u16(G_ARC_LANE_SPAN_Y_A) as f32;

        let panel = platform::read_u32(owner + 0x84) as usize;
        platform::write_f32(panel + 0x24, half);
        vcall_f32_pair_a(panel, scale_a, scale_b);
        platform::call1(FN_802D3370_A, sprite as u32);

        // Cell pane 2 (texture 0x28).
        let cell = platform::call3(
            FN_802D3700_A,
            (cell_y & 0xFFFF) as u32,
            (cell_x & 0xFFFF) as u32,
            1,
        ) as usize;
        let colour = platform::read_u32(SDA2_SPRITE_COLOUR_A);
        let size = platform::read_u16(SDA2_SPRITE_SIZE_A);
        let tail_byte = platform::read_u8(SDA2_SPRITE_TAIL_A);
        platform::write_u8(cell + 0x18, platform::read_u8(cell + 0x18) | 0x08);
        platform::write_u32(cell + 0x24, colour);
        platform::write_u16(cell + 0x28, size);
        platform::write_u8(cell + 0x2A, tail_byte);
        platform::call5(
            FN_802C02C0_A,
            cell as u32,
            (layout_x & 0xFFFF) as u32,
            (layout_y & 0xFFFF) as u32,
            0,
            0x28,
        );

        // First window block: the opaque lane strip.
        let mut block = [0u8; 0x40];
        let block_ptr = block.as_mut_ptr() as usize;
        platform::call1(FN_802D0830_A, block_ptr as u32);
        platform::write_u32(block_ptr + 0x08, 0);
        let keep_colour = platform::call1(FN_802D2F20_A, 1);
        let keep_blend = platform::call1(FN_802D2F80_A, 0);
        let keep_depth = platform::call1(FN_802D2FE0_A, 0);
        platform::write_u32(block_ptr + 0x2C, platform::read_u32(SDA2_OPAQUE_A));
        platform::write_u32(block_ptr + 0x00, 0);
        platform::write_u32(block_ptr + 0x04, animation);
        platform::write_f32(block_ptr + 0x24, half);
        vcall_f32_pair_a(block_ptr, scale_a, scale_b);
        platform::call1(FN_802D2FE0_A, keep_depth);
        platform::call1(FN_802D2F80_A, keep_blend);
        platform::call1(FN_802D2F20_A, keep_colour);

        // Cell pane 3 (texture `0xFFFFFFFF`).
        let overlay_cell = platform::call3(
            FN_802D3700_A,
            (cell_y & 0xFFFF) as u32,
            (cell_x & 0xFFFF) as u32,
            6,
        ) as usize;
        platform::write_u8(
            overlay_cell + 0x18,
            platform::read_u8(overlay_cell + 0x18) | 0x08,
        );
        platform::write_u32(overlay_cell + 0x24, colour);
        platform::write_u16(overlay_cell + 0x28, size);
        platform::write_u8(overlay_cell + 0x2A, tail_byte);
        platform::call5(
            FN_802C02C0_A,
            overlay_cell as u32,
            (layout_x & 0xFFFF) as u32,
            (layout_y & 0xFFFF) as u32,
            0,
            0xFFFF_FFFF,
        );

        // The `+0x80` overlay reuses the halved HUD extents.
        let keep_overlay = platform::call1(
            FN_802D2F80_A,
            (platform::read_u16(owner + 0x1C) & 0x01) as u32,
        );
        let overlay = platform::read_u32(owner + 0x80) as usize;
        platform::write_u32(overlay + 0x04, overlay_cell as u32);
        platform::write_u32(overlay + 0x08, 0);
        platform::write_f32(overlay + 0x24, -half);
        vcall_f32_pair_a(overlay, hud_x as f32, hud_y as f32);

        let keep_colour = platform::call1(FN_802D2F20_A, 0);
        let keep_blend = platform::call1(FN_802D2F80_A, 1);
        let keep_depth = platform::call1(FN_802D2FE0_A, 0);
        let window_tint = platform::read_u32(SDA2_WINDOW_TINT_A);
        platform::write_u32(block_ptr + 0x08, 1);
        platform::write_u8(block_ptr + 0x2C, (window_tint >> 24) as u8);
        platform::write_u8(block_ptr + 0x2D, (window_tint >> 16) as u8);
        platform::write_u8(block_ptr + 0x2E, (window_tint >> 8) as u8);
        platform::write_u8(block_ptr + 0x2F, platform::read_u8(owner + 0x1F));
        platform::write_u32(block_ptr + 0x00, 2);
        platform::write_u32(block_ptr + 0x04, cell as u32);
        platform::write_f32(block_ptr + 0x24, -half);
        vcall_f32_pair_a(block_ptr, hud_x as f32, hud_y as f32);
        platform::call1(FN_802D2FE0_A, keep_depth);
        platform::call1(FN_802D2F80_A, keep_blend);
        platform::call1(FN_802D2F20_A, keep_colour);
        platform::call1(FN_802D2F80_A, keep_overlay);

        platform::call5(
            FN_802C4FB0_A,
            owner as u32,
            (layout_x & 0xFFFF) as u32,
            (layout_y & 0xFFFF) as u32,
            (cell_x & 0xFFFF) as u32,
            (cell_y & 0xFFFF) as u32,
        );
        platform::call1(FN_802D3370_A, overlay_cell as u32);
        platform::call1(FN_802D3370_A, cell as u32);
    } else if mode == 2 {
        let keep_colour = platform::call1(FN_802D2F20_A, 1);
        let keep_blend = platform::call1(FN_802D2F80_A, 0);
        let keep_depth = platform::call1(FN_802D2FE0_A, 0);
        platform::call1(FN_802CEE70_A, hud as u32);
        platform::call1(FN_802C1F80_A, 1);
        platform::call1(FN_802C2060_A, 1);
        platform::call0(FN_802C20E0_A);
        platform::call1(FN_801C88F0, 1);
        platform::call2(FN_802C20F0_A, 0, 1);
        platform::call2(FN_802C2250_A, 0, 0);
        platform::call1(FN_802C4D80_A, owner as u32);
        fn_802c0b60(platform::read_u32(owner + 0x88) as usize, 0);

        let mut matrix = [0u8; 0x28];
        let matrix_ptr = matrix.as_mut_ptr() as usize;
        call_f32x3_ptr_a(
            FN_801C0C60_A,
            (platform::read_f32(hud + 0x08) as i32 & 0xFFFF) as f32,
            (platform::read_f32(hud + 0x0C) as i32 & 0xFFFF) as f32,
            platform::read_f32(SDA2_ONE_A),
            matrix.as_mut_ptr(),
        );
        platform::call1(FN_802C2360_A, 0x0B);
        let marker = platform::read_u32(SDA2_OPAQUE_A);
        fn_802c2f70(0x10, matrix_ptr, &marker as *const u32 as usize);

        platform::call1(FN_802D2FE0_A, keep_depth);
        platform::call1(FN_802D2F80_A, keep_blend);
        platform::call1(FN_802D2F20_A, keep_colour);
    }
}

// ===========================================================================
// Wave 219, lane B - `resource::archive` bodies in the `0x802C0000` band.
//
// Ten shipped bodies of the `0x802C0100..0x802C4770` range: the GX texture
// attribute wrappers (`0x802C0110`, `0x802C0BA0`, `0x802C02C0`, `0x802C20E0`,
// `0x802C2250`, `0x802C30C0`), the scrolled-UV wrap (`0x802C38E0`), the radial
// gradient texture fill (`0x802C0C70`), the guarded deleter (`0x802C35B0`) and
// the two-pass screen quad draw (`0x802C4700`).
//
// The exports print the CodeWarrior unsigned-int-to-double idiom as
// `CONCAT44(0x43300000, x ^ 0x80000000) - 2^52` and the `psq_st`/`psq_l`
// prologue save pairs of `f27..f31` as `GQR0` quantisation; both are compiler
// artefacts. As elsewhere in this file the first is written as a plain
// `as f32`/`as i32` cast and the second is dropped.
//
// Every named address below is a new constant in this lane and therefore
// carries the `_B` suffix; existing helpers and constants are reused as-is.
