/// Translates the gated default object setter.
///
/// # Original
/// - Ghidra: `FUN_802c0110` at `0x802C0110` (52 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c0110_FUN_802c0110.c`
///
/// # Arguments
/// - `value`: word forwarded to `0x802C0090`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Resets the descriptor block, then stores `value` into it.
///
/// # Safety
/// The descriptor block must be initialised.
///
/// # Confidence
/// high - two calls, both literal; the export is complete.
pub unsafe fn fn_802c0110(value: u32) {
    platform::call0(FN_802C0040_B);
    platform::call1(FN_802C0090_B, value);
}

/// Sets the GX viewport/scissor and texture of one sprite descriptor.
///
/// # Original
/// - Ghidra: `FUN_802c02c0` at `0x802C02C0` (388 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c02c0_802c02c0.c`
/// - observed: `if (param_5 == 0xffffffff) param_5 = *(byte *)(param_1 + 9);`
///   then the two halfwords at `+4`/`+6`, shifted left by one when `param_4` is
///   non-zero, are the viewport size; `FUN_801c59d0` gets the unscaled pair,
///   `param_5` and `param_4 & 0xff`; the fourth `FUN_801c5f40` argument is
///   `param_1 + 0x24` when bit 3 of `+0x18` is set and `r2 - 0x3E78`
///   otherwise, and the third argument is that same bit as `0`/`1`; the three
///   state latches are read, one blend bit is set, the `+0x19` word and the
///   `+0x20` word are handed to `FUN_801c5ec0`, `FUN_801c6290` binds `+0x10`,
///   the `0x10`/`0x20` bits of `+0x18` drive `FUN_801c4f70`/`FUN_801c76c0`, and
///   the latches are restored.
///
/// # Arguments
/// - `desc`: sprite descriptor; `+0x04`/`+0x06` size, `+0x09` default scissor
///   depth, `+0x10` texture handle, `+0x18` flag byte, `+0x19`/`+0x20` GX
///   words, `+0x24` the alternate mode record.
/// - `x`, `y`: viewport origin.
/// - `scale`: non-zero selects the doubled viewport size.
/// - `alpha`: scissor depth, or `0xFFFFFFFF` to take `desc + 0x09`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Programs the GX viewport, scissor, blend, texture and alpha state.
///
/// # Safety
/// `desc` must be readable for `0x28` bytes and the GX state live.
///
/// # Confidence
/// high - every offset, mask and call order is literal; only the four GX
/// callees' individual roles are inferred from their argument shapes.
pub unsafe fn fn_802c02c0(desc: usize, x: u32, y: u32, scale: u32, alpha: u32) {
    let depth = if alpha == 0xFFFF_FFFF {
        platform::read_u8(desc + 0x09) as u32
    } else {
        alpha
    };
    let mut width = platform::read_u16(desc + 0x04) as u32;
    let mut height = platform::read_u16(desc + 0x06) as u32;
    if scale != 0 {
        width = width.wrapping_shl(1);
        height = height.wrapping_shl(1);
    }
    platform::call4(FN_801C5960_B, x, y, width, height);
    platform::call4(
        FN_801C59D0_B,
        platform::read_u16(desc + 0x04) as u32,
        platform::read_u16(desc + 0x06) as u32,
        depth,
        scale & 0xFF,
    );

    let mode_flags = platform::read_u8(desc + 0x18);
    let mode_record = if (mode_flags & 0x08) != 0 {
        desc + 0x24
    } else {
        SDA2_BASE - 0x3E78
    };
    platform::call4(
        FN_801C5F40,
        0,
        G_802FCF80_BLEND_B as u32,
        ((mode_flags & 0x08) != 0) as u32,
        mode_record as u32,
    );

    let flags = platform::read_u8(desc + 0x18);
    let saved_a = platform::call1(FN_802D2F20_B, (flags & 0x01) as u32);
    let saved_b = platform::call1(FN_802D2F80_B, ((flags >> 1) & 0x01) as u32);
    platform::call3(FN_801C8E70, 1, 7, ((flags >> 2) & 0x01) as u32);

    let mut colour = [platform::read_u32(desc + 0x19)];
    platform::call2(
        FN_801C5EC0,
        colour.as_mut_ptr() as u32,
        platform::read_u32(desc + 0x20),
    );
    platform::call1(FN_801C5B00_B, 3);
    platform::call2(FN_801C6290_B, platform::read_u32(desc + 0x10), 1);
    platform::call4(
        FN_801C5F40,
        0,
        G_802FCF80_BLEND_B as u32,
        0,
        (SDA2_BASE - 0x3E78) as u32,
    );

    let tail_flags = platform::read_u8(desc + 0x18);
    if (tail_flags & 0x10) != 0 {
        platform::call0(FN_801C4F70_B);
    }
    if (tail_flags & 0x20) != 0 {
        platform::call0(FN_801C76C0_B);
    }
    platform::call1(FN_802D2F80_B, saved_b);
    platform::call1(FN_802D2F20_B, saved_a);
}

/// Sets up one texture's GX attributes from a descriptor.
///
/// # Original
/// - Ghidra: `FUN_802c0ba0` at `0x802C0BA0` (128 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c0ba0_802c0ba0.c`
/// - observed: `FUN_801c6d90(param_2, desc[0x10], desc[4], desc[6], desc[9],
///   desc[0xA], desc[0xB], 0)` followed by `FUN_801c6ff0(z, z, z, param_2,
///   desc[0xC], desc[0xD], 0, 0, 0)` with `z = r2[-0x3E70]` (`0.0f`).
///
/// # Arguments
/// - `desc`: texture descriptor; `+0x04`/`+0x06` the two size halfwords,
///   `+0x09`..`+0x0D` five format bytes and `+0x10` the base word.
/// - `handle`: GX texture handle forwarded to both setup calls.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Programs the GX texture attributes and the texture-coordinate scale.
///
/// # Safety
/// `desc` must be readable for `0x14` bytes and `handle` a live GX handle.
///
/// # Confidence
/// high - both calls, all eight argument words and the zero float are literal.
pub unsafe fn fn_802c0ba0(desc: usize, handle: u32) {
    call8(
        FN_801C6D90,
        handle,
        platform::read_u32(desc + 0x10),
        platform::read_u16(desc + 0x04) as u32,
        platform::read_u16(desc + 0x06) as u32,
        platform::read_u8(desc + 0x09) as u32,
        platform::read_u8(desc + 0x0A) as u32,
        platform::read_u8(desc + 0x0B) as u32,
        0,
    );
    let zero = platform::read_f32(SDA2_F32_ZERO_B) as f64;
    call_mixed9(
        FN_801C6FF0,
        zero,
        zero,
        zero,
        handle,
        platform::read_u8(desc + 0x0C) as u32,
        platform::read_u8(desc + 0x0D) as u32,
        0,
        0,
        0,
    );
}

/// Fills one radial-gradient render-target texture.
///
/// # Original
/// - Ghidra: `FUN_802c0c70` at `0x802C0C70` (448 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c0c70_802c0c70.c`
/// - observed: the texture object is the incoming `r3` (`lhz r30,4(r3)` /
///   `mr r28,r3` right after the prologue); the two halves of
///   its `+4`/`+6` size halfwords (rounded up, `(n + (n & 1)) >> 1`) are the
///   centre and the radius is `half_width^2`. For every `(x, y)` the offsets are
///   `dx = x - half_w`, `dy = half_h - y`, `d2 = dx*dx + dy*dy`; when
///   `d2 <= r2` the value is `0`, or `sqrt(r2 - d2)` (emitted as
///   `(r2 - d2) * invsqrt(r2 - d2)`) when `r2 - d2 > 0`. The triple
///   `(dx, dy, value)` is normalised by `0x801C1470`, packed by `0x802C7D30`,
///   has its third byte moved to the first position, and is written to
///   `(x, y)` through `0x802C1280`; `0x802C0C20` then flushes the texture.
/// - Removed: the modelled `_savegpr_23` prologue call (`0x802DCD64`) and the
///   `_restgpr_23` epilogue call (`0x802DCDB0`). The prologue `bl` returns no
///   value; `texture` is the incoming `r3`.
///
/// # Arguments
/// - `texture`: live render target.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes every texel of the render target and flushes it.
///
/// # Safety
/// The render-target object in `r3` must be live.
///
/// # Confidence
/// medium - the arithmetic, the two-step square root and the byte rotation are
/// literal; the GQR0 blocks in the export are only the `f27..f31` save/restore
/// and are dropped.
pub unsafe fn fn_802c0c70(texture: usize) {
    let width = platform::read_u16(texture + 0x04) as u32;
    let height = platform::read_u16(texture + 0x06) as u32;
    let half_w_i = ((width + (width & 1)) >> 1) as i32;
    let half_h_i = ((height + (height & 1)) >> 1) as i32;
    let half_w = half_w_i as f32;
    let radius2 = half_w * half_w;

    let mut y = 0u32;
    while y < height {
        let dy = (half_h_i - y as i32) as f32;
        let mut x = 0u32;
        while x < width {
            let dx = (x as i32 - half_w_i) as f32;
            let dist2 = dx * dx + dy * dy;
            let mut value = 0.0f32;
            if dist2 <= radius2 {
                let diff = radius2 - dist2;
                if diff > 0.0 {
                    let inverse = call_double(FN_80237BA0_B, diff as f64);
                    value = diff * inverse as f32;
                }
            }

            let mut vector = [dx, dy, value];
            let vector_ptr = vector.as_mut_ptr() as u32;
            platform::call2(FN_801C1470_B, vector_ptr, vector_ptr);
            let mut colour = 0u32;
            let colour_ptr = &mut colour as *mut u32 as u32;
            platform::call2(FN_802C7D30_B, colour_ptr, vector_ptr);
            let packed = platform::read_u32(colour_ptr as usize);
            let third = platform::read_u8(colour_ptr as usize + 3) as u32;
            let mut word = (third << 24) | (packed & 0x00FF_FFFF);
            platform::call4(
                FN_802C1280_B,
                texture as u32,
                x,
                y,
                &mut word as *mut u32 as u32,
            );
            x += 1;
        }
        y += 1;
    }
    platform::call1(FN_802C0C20_B, texture as u32);
}

/// Tail-call thunk that clears the GX pixel format.
///
/// # Original
