/// `0x801C40B0` - five-argument channel state writer.
const FN_801C40B0_E: usize = 0x801C_40B0;
/// `0x801C4780` - copy a word block into one channel's descriptor.
const FN_801C4780_E: usize = 0x801C_4780;
/// `0x801C37C0` - enable/disable one channel (`(channel, state)`).
const FN_801C37C0_E: usize = 0x801C_37C0;
/// `0x801C8DC0` - four-word GX setup, tail-called by [`fn_802c3020`].
const FN_801C8DC0_E: usize = 0x801C_8DC0;

/// `0x80350160` - the fourteen-entry jump table of [`fn_802c2360`]
/// (words `0x802C23A8`, `0x802C24D0`, `0x802C2414` x4, `0x802C2460`,
/// `0x802C24F8` x2, `0x802C25B0`, `0x802C261C` x4).
const JT_802C2360_E: usize = 0x8035_0160;

/// `0x802FCFA0`-relative descriptor blocks loaded by [`fn_802c2360`]
/// (`0x802FCFC0`, `0x802FD000`, `0x802FD040`, `0x802FD060`).
const DAT_802FCFC0_E: usize = 0x802F_CFC0;
const DAT_802FD000_E: usize = 0x802F_D000;
const DAT_802FD040_E: usize = 0x802F_D040;
const DAT_802FD060_E: usize = 0x802F_D060;

/// `sdata2` blocks read by [`fn_802c2360`] through `r2`:
/// `r2 - 0x3E00`, `r2 - 0x3DE0`, `r2 - 0x3DC0`, `r2 - 0x3DA0` and
/// `r2 - 0x3D80`.
const SDA2_3E00_E: usize = crate::boot::entry::SDA2_BASE - 0x3E00;
const SDA2_3DE0_E: usize = crate::boot::entry::SDA2_BASE - 0x3DE0;
const SDA2_3DC0_E: usize = crate::boot::entry::SDA2_BASE - 0x3DC0;
const SDA2_3DA0_E: usize = crate::boot::entry::SDA2_BASE - 0x3DA0;
const SDA2_3D80_E: usize = crate::boot::entry::SDA2_BASE - 0x3D80;

/// `0x802FD0A8` - sixteen-byte record table indexed by [`fn_802c3020`].
const DAT_802FD0A8_E: usize = 0x802F_D0A8;

/// `0x802C3210` - base constructor run first by [`fn_802c3630`].
const FN_802C3210_E: usize = 0x802C_3210;
/// `0x802CFBA0` - construct the 0x64-byte member object.
const FN_802CFBA0_E: usize = 0x802C_FBA0;
/// `0x802CEF70` - construct the 0x78-byte member object.
const FN_802CEF70_E: usize = 0x802C_EF70;
/// `0x802CF6F0` - construct the 0x1C0-byte member object.
const FN_802CF6F0_E: usize = 0x802C_F6F0;

/// `0x80350230`, `0x8035023C`, `0x8035024C`, `0x80350280` - the four
/// pointer slots installed by [`fn_802c3630`].
const DAT_80350230_E: usize = 0x8035_0230;
const DAT_8035023C_E: usize = 0x8035_023C;
const DAT_8035024C_E: usize = 0x8035_024C;
const DAT_80350280_E: usize = 0x8035_0280;

/// Constructs one 0x18-byte display object.
///
/// # Original
/// - Ghidra: `FUN_802c0a80` at `0x802C0A80` (64 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c0a80_FUN_802c0a80.c`
/// - observed: `*(undefined2 *)(param_1 + 1) = param_2; *param_1 =
///   &DAT_80350110; *(undefined2 *)((int)param_1 + 6) = param_3;
///   *(undefined1 *)(param_1 + 2) = 0; ... param_1[4] = 0; param_1[5] = 0;`
/// - verified: `0x802C0A80..0x802C0ABC` then `4e800020 bclr`; the tsv size of
///   64 is exact, no padding word.
///
/// # Arguments
/// - `this`: object base, at least 0x18 bytes (`r3`).
/// - `width`: halfword stored at `+0x04` (`r4`).
/// - `height`: halfword stored at `+0x06` (`r5`).
/// - `format`: byte stored at `+0x09` (`r6`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the vtable at `+0x00`, two halfwords, four flag bytes and two zero
/// words (`+0x10`, `+0x14`).
///
/// # Safety
/// `this..this+0x18` must be writable.
///
/// # Confidence
/// high - every store, constant and offset is literal.
pub unsafe fn fn_802c0a80(this: usize, width: u16, height: u16, format: u8) {
    platform::write_u16(this + 0x04, width);
    platform::write_u32(this, DAT_80350110_E as u32);
    platform::write_u16(this + 0x06, height);
    platform::write_u8(this + 0x08, 0);
    platform::write_u8(this + 0x09, format);
    platform::write_u8(this + 0x0A, 0);
    platform::write_u8(this + 0x0B, 0);
    platform::write_u8(this + 0x0C, 1);
    platform::write_u8(this + 0x0D, 1);
    platform::write_u32(this + 0x10, 0);
    platform::write_u32(this + 0x14, 0);
}

/// Deleting destructor of the [`fn_802c0a80`] object.
///
/// # Original
/// - Ghidra: `FUN_802c0ac0` at `0x802C0AC0` (112 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c0ac0_FUN_802c0ac0.c`
/// - observed: `if (param_1 != 0) { *param_1 = &DAT_80350110; if ((*(byte *)
///   (param_1 + 2) & 4) != 0) FUN_802b9290(param_1[5]); if (0 < param_2)
///   FUN_802b9280(param_1); } return param_1;`
/// - verified: `0x802C0AC0..0x802C0B2C` then `4e800020 bclr`; tsv 112 exact.
///
/// # Arguments
/// - `this`: object base; `0` is tolerated (`r3`).
/// - `deleting`: when positive the object itself is freed (`r4`).
///
/// # Returns
/// `this`, as in the export.
///
/// # Side effects
/// Restores the vtable, optionally frees the owned block at `+0x14`, and
/// optionally frees the object.
///
/// # Safety
/// A non-null `this` must be a live object of this class.
///
/// # Confidence
/// high - the null guard, the `& 4` flag test, both frees and the return value
/// are literal.
pub unsafe fn fn_802c0ac0(this: usize, deleting: i32) -> usize {
    if this != 0 {
        platform::write_u32(this, DAT_80350110_E as u32);
        if platform::read_u8(this + 0x08) & 4 != 0 {
            fn_802b9290(platform::read_u32(this + 0x14));
        }
        if deleting > 0 {
            arc_heap_free_object(this as u32);
        }
    }
    this
}

/// Marks the object as active.
///
/// # Original
/// - Ghidra: `FUN_802c0b30` at `0x802C0B30` (12 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c0b30_FUN_802c0b30.c`
/// - observed: `*(undefined1 *)(param_1 + 8) = 1;`
/// - verified: `0x802C0B30..0x802C0B38` then `4e800020 bclr`; tsv 12 exact,
///   followed by one alignment word.
///
/// # Confidence
/// high - single byte store.
///
/// # Safety
/// `this + 8` must be writable.
pub unsafe fn fn_802c0b30(this: usize) {
    platform::write_u8(this + 0x08, 1);
}

/// Binds a freshly allocated GX texture object to the object's `+0x10` slot.
///
/// # Original
/// - Ghidra: `FUN_802c0c20` at `0x802C0C20` (76 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c0c20_FUN_802c0c20.c`
/// - observed: `uVar1 = FUN_801c6ba0(*(undefined2 *)(param_1 + 4),
///   *(undefined2 *)(param_1 + 6), *(undefined1 *)(param_1 + 9), 0, 1);
///   FUN_801ac470(*(undefined4 *)(param_1 + 0x10), uVar1);`
/// - verified: `0x802C0C20..0x802C0C68` then `4e800020 bclr`; tsv 76 exact.
///
/// # Arguments
/// - `this`: object base (`r3`); `+0x04`/`+0x06` hold the width/height
///   halfwords, `+0x09` the format byte and `+0x10` the destination slot.
///
/// # Returns
/// Nothing.
///
/// # Safety
/// `this` must be a live object; the texture allocator must accept the
/// halfword dimensions.
///
/// # Confidence
/// high - all four arguments of the allocator and both operands of the
/// flush/bind call are literal.
pub unsafe fn fn_802c0c20(this: usize) {
    let texture = platform::call5(
        FN_801C6BA0_E,
        platform::read_u16(this + 0x04) as u32,
        platform::read_u16(this + 0x06) as u32,
        platform::read_u8(this + 0x09) as u32,
        0,
        1,
    );
    platform::call2(
        FN_801AC470_E,
        platform::read_u32(this + 0x10),
        texture,
    );
}

/// Runs the one-shot display-object render setup.
///
/// # Original
/// - Ghidra: `FUN_802c1d10` at `0x802C1D10` (612 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c1d10_FUN_802c1d10.c`
/// - observed: `uVar5 = FUN_802dcd70(); uVar1 = (undefined4)((ulonglong)uVar5
///   >> 0x20); uVar3 = FUN_802d2f20((int)uVar5); uVar4 = FUN_802d2f80(param_3);
///   FUN_802c1f80(1); FUN_801c5860(0); if (param_4 == 0) { FUN_802c2060(0); }
///   else { FUN_802c2060(1); FUN_801c74c0(&DAT_80424678, *(undefined4 *)
///   (unaff_r13 + -0x47cc)); } ... local_28[0] = *param_5; FUN_801c8430(1,
///   local_28); ... FUN_802c3020(0xe);` followed by the two mode arms and
///   `FUN_802d2f80(uVar4); FUN_802d2f20(uVar3); FUN_802dcdbc();`
/// - verified: `0x802C1D10..0x802C1F70` then `4e800020 bclr`; tsv 612 exact.
/// - observed: `0x802DCD70`/`0x802DCDBC` are the compiler's save/restore
///   register thunks; they do not change `r3..r10`, so the `uVar5` pair is
///   `(param_1, param_2)` and `uVar1` is `param_1` (the value later handed to
///   `0x801C9940`). Both thunk calls are omitted from the body.
/// - observed: the Ghidra `local_28[10]` block is a 10-word stack slot whose
///   only initialised word is `local_28[0]`; the remaining nine are whatever
///   the frame held. They are modelled as zero here.
///
/// # Arguments
/// - `layer_target`: value handed to `0x801C9940` as its first argument (`r3`).
/// - `mode_a`: pushed through `0x802D2F20`, restored at the end (`r4`).
/// - `mode_b`: pushed through `0x802D2F80`, restored at the end (`r5`).
/// - `variant`: non-zero selects the alternate texture/mode arm (`r6`).
/// - `source`: pointer to a word block whose first word is copied to the
///   stack slot handed to `0x801C8430` (`r7`).
/// - `flag`: non-zero selects the `0xD`/`0xB` channel ids (`r8`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Reprograms the GX channel state, draws one layer and restores both mode
/// pushes.
///
/// # Safety
/// `source` must be readable. All called routines must be the genuine GX
/// helpers at these addresses; `layer_target` is passed through unchanged.
///
/// # Confidence
/// medium - every call, argument, table address and branch is literal; the
/// roles of the two mode setters and of `0x801C9940`'s first argument are
/// inferred from the push/restore symmetry and from the save-thunk analysis.
pub unsafe fn fn_802c1d10(
    layer_target: u32,
    mode_a: u32,
    mode_b: u32,
    variant: i32,
    source: usize,
    flag: i32,
) {
    let previous_a = platform::call1(FN_802D2F20_E, mode_a);
    let previous_b = platform::call1(FN_802D2F80_E, mode_b);

    fn_802c1f80(1);
    platform::call1(FN_801C5860_E, 0);

    if variant == 0 {
        fn_802c2060(0);
    } else {
        fn_802c2060(1);
        platform::call2(
            FN_801C74C0_E,
            DAT_80424678_E as u32,
            platform::read_u32(G_SCREEN_WORD_8042AEB4_E),
        );
    }

    platform::call0(FN_802C20E0_E);
    platform::call1(FN_801C88F0_E, 1);
    platform::call1(FN_801C8130_E, 0);

    let mut local = [0u32; 10];
    local[0] = platform::read_u32(source);
    platform::call2(FN_801C8430_E, 1, local.as_mut_ptr() as u32);

    platform::call3(FN_801C8600_E, 0, 0, 0);
    platform::call5(FN_801C8640_E, 0, 0, 1, 2, 3);

    if variant == 0 {
        platform::call4(FN_801C8790_E, 0, 0xFF, 0xFF, 0xFF);
    } else {
        platform::call4(
            FN_801C8790_E,
            0,
            0,
            platform::read_u32(G_SCREEN_WORD_8042AEB4_E),
            0xFF,
        );
    }

    platform::call5(FN_801C82F0_E, 0, 0x0F, 0x0F, 0x0F, 2);
    platform::call6(FN_801C8370_E, 0, 0, 0, 0, 1, 0);
    platform::call5(FN_801C8330_E, 0, 7, 7, 7, 1);
    platform::call6(FN_801C83D0_E, 0, 0, 0, 0, 1, 0);
    platform::call5(FN_801C86C0_E, 7, 0, 1, 7, 0);

    fn_802c3020(0x0E);

    if variant == 0 {
        platform::call1(FN_802C3000_E, 0);
        let channel = if flag != 0 { 0x0D } else { 0x0C };
        fn_802c2360(channel);
        platform::call2(FN_801C9940_E, layer_target, 0);
        platform::call2(
            FN_801C95E0_E,
            platform::read_u32(DAT_80424640_E),
            platform::read_u32(DAT_80424644_E),
        );
    } else {
        platform::call3(FN_801C8700_E, 2, 0x16, 0);
        platform::call1(FN_802C3000_E, 3);
        platform::call1(FN_801C8EB0_E, 0);
        let channel = if flag != 0 { 0x0B } else { 0x0A };
        fn_802c2360(channel);
        platform::call2(FN_801C9940_E, layer_target, 0);
        platform::call2(
            FN_801C95E0_E,
            platform::read_u32(DAT_80424638_E),
            platform::read_u32(DAT_8042463C_E),
        );
        platform::call3(FN_801C8700_E, 0, 0x16, 0);
        platform::call1(FN_801C8EB0_E, 1);
    }

    platform::call1(FN_802D2F80_E, previous_b & 0xFF);
    platform::call1(FN_802D2F20_E, previous_a & 0xFF);
}

/// Configures the two direct GX channels for `mode == 0` or `mode == 1`.
///
/// # Original
/// - Ghidra: `FUN_802c1f80` at `0x802C1F80` (216 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c1f80_FUN_802c1f80.c`
/// - observed: `if (param_1 == 0) { FUN_801c6ac0(1); FUN_801c5860(2);
///   uVar1 = FUN_802c17d0(); FUN_801c6af0(4,1,0,0,uVar1,2,1);
///   FUN_801c6af0(5,0,1,1,0,0,2); } else if (param_1 == 1) { FUN_801c6ac0(1);
///   FUN_801c5860(2); FUN_801c6af0(4,0,0,0,0,2,1); FUN_801c6af0(5,0,1,1,0,0,2); }`
/// - verified: `0x802C1F80..0x802C2048` jump to a shared epilogue whose `bclr`
///   is at `0x802C2054`; tsv 216 exact.
/// - observed: both seven-argument `0x801C6AF0` calls really use `r3..r9`;
///   the `r7` argument of the first one is the result of `0x802C17D0()`.
///
/// # Arguments
/// - `mode`: `0` selects the default channel word, `1` selects the zero word;
///   any other value does nothing.
///
/// # Returns
/// Nothing.
///
/// # Safety
/// The GX channel setters must be callable at these addresses.
///
/// # Confidence
/// high - the two arms, both seven-argument calls and every constant are
/// literal; only the meaning of `0x802C17D0`'s word is inferred.
pub unsafe fn fn_802c1f80(mode: i32) {
    if mode == 0 {
        platform::call1(FN_801C6AC0_E, 1);
        platform::call1(FN_801C5860_E, 2);
        let default_word = call0_u32(FN_802C17D0_E);
        platform::call7(FN_801C6AF0_E, 4, 1, 0, 0, default_word, 2, 1);
        platform::call7(FN_801C6AF0_E, 5, 0, 1, 1, 0, 0, 2);
    } else if mode == 1 {
        platform::call1(FN_801C6AC0_E, 1);
        platform::call1(FN_801C5860_E, 2);
        platform::call7(FN_801C6AF0_E, 4, 0, 0, 0, 0, 2, 1);
        platform::call7(FN_801C6AF0_E, 5, 0, 1, 1, 0, 0, 2);
    }
}

/// Selects one of two window/layer rectangles.
///
/// # Original
/// - Ghidra: `FUN_802c2060` at `0x802C2060` (124 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c2060_FUN_802c2060.c`
/// - observed: `if (param_1 == 0) { FUN_801c4a20(0);
///   FUN_801c47d0(0,1,4,0x3c,0,0x7d); } else if (param_1 == 1) {
///   FUN_801c4a20(1); FUN_801c47d0(0,1,4,0x3c,0,0x7d); }`
/// - verified: `0x802C2060..0x802C20D8` then `4e800020 bclr`; tsv 124 exact.
/// - observed: the six-argument rectangle writer receives the same constants
///   in both arms; only the layer selector differs.
///
/// # Confidence
/// high - both calls and all six rectangle constants are literal.
///
/// # Safety
/// The two GX setters must be callable at these addresses.
pub unsafe fn fn_802c2060(mode: i32) {
    if mode == 0 {
        platform::call1(FN_801C4A20_E, 0);
        platform::call6(FN_801C47D0_E, 0, 1, 4, 0x3C, 0, 0x7D);
    } else if mode == 1 {
        platform::call1(FN_801C4A20_E, 1);
        platform::call6(FN_801C47D0_E, 0, 1, 4, 0x3C, 0, 0x7D);
    }
}

/// Applies one of fourteen GX channel configurations.
///
/// # Original
/// - Ghidra: `FUN_802c2360` at `0x802C2360` (920 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c2360_FUN_802c2360.c`
/// - observed: `FUN_801c4070(); switch(param_1) { case 0: ... case 0xb: ...
///   case 0xc: case 0xd: bVar1 = true; if ((param_1 != 0xb) && (param_1 !=
///   0xd)) { bVar1 = false; } bVar2 = true; if ((param_1 != 10) && (param_1
///   != 0xb)) { bVar2 = false; } ... }`
/// - verified: `0x802C2360..0x802C26F4` then `4e800020 bclr`; tsv 920 exact.
/// - observed: the dispatch is a `bctr` through the fourteen-word table at
///   `0x80350160`, dumped from `work/dol/main.elf` as
///   `0x802C23A8`, `0x802C24D0`, `0x802C2414` x4, `0x802C2460`,
///   `0x802C24F8` x2, `0x802C25B0`, `0x802C261C` x4. A `mode` above `0xD`
///   (`cmpli ...,0xd`) falls straight to the epilogue.
/// - observed: the `r2`-relative blocks passed to `0x801C4780` are raw words,
///   not floats; the disassembly shows `addi r4,r2,-0x3E00` etc. with no
///   floating load, so they are modelled as addresses, exactly as the export's
///   `unaff_r2 + -0x3e00` terms say.
///
/// # Arguments
/// - `mode`: configuration id `0..=0xD`.
///
/// # Returns
/// Nothing for an out-of-range id.
///
/// # Side effects
/// Every arm rewrites one or more GX channel descriptors; ids `0..=9` also
/// upload word blocks through `0x801C4780`.
///
/// # Safety
/// The GX setters must be callable; the descriptor blocks at the listed
/// addresses must be readable with the lengths used here (`2`, `4` or `6`
/// words).
///
/// # Confidence
/// high - the jump table, every arm, all channel ids and all block lengths were
/// read from `work/dol/main.elf`; only the descriptor semantics are inferred.
pub unsafe fn fn_802c2360(mode: i32) {
    platform::call0(FN_801C4070_E);

    match mode {
        0 => {
            platform::call5(FN_801C40B0_E, 0, 9, 1, 3, 0x0E);
            platform::call5(FN_801C40B0_E, 0, 10, 0, 3, 0x0E);
            platform::call3(FN_801C4780_E, 9, DAT_802FCFC0_E as u32, 6);
            platform::call3(FN_801C4780_E, 10, DAT_802FD000_E as u32, 6);
            platform::call2(FN_801C37C0_E, 9, 2);
            platform::call2(FN_801C37C0_E, 10, 2);
        }
        1 => {
            platform::call2(FN_801C37C0_E, 9, 1);
            platform::call5(FN_801C40B0_E, 0, 9, 1, 4, 0);
        }
        2 | 3 | 4 | 5 => {
            platform::call2(FN_801C37C0_E, 9, 1);
            platform::call2(FN_801C37C0_E, 10, 1);
            platform::call5(FN_801C40B0_E, 0, 9, 1, 4, 0);
            platform::call5(FN_801C40B0_E, 0, 10, 0, 4, 0);
        }
        6 => {
            platform::call2(FN_801C37C0_E, 9, 1);
            platform::call2(FN_801C37C0_E, 10, 1);
            platform::call2(FN_801C37C0_E, 0x0B, 1);
            platform::call5(FN_801C40B0_E, 0, 9, 1, 4, 0);
            platform::call5(FN_801C40B0_E, 0, 10, 0, 4, 0);
            platform::call5(FN_801C40B0_E, 0, 0x0B, 1, 5, 0);
        }
        7 | 8 => {
            platform::call2(FN_801C37C0_E, 9, 2);
            platform::call2(FN_801C37C0_E, 10, 2);
            if mode == 7 {
                platform::call2(FN_801C37C0_E, 0x0D, 2);
            }
            platform::call5(FN_801C40B0_E, 0, 9, 0, 3, 0x0E);
            platform::call5(FN_801C40B0_E, 0, 10, 0, 3, 0x0E);
            if mode == 7 {
                platform::call5(FN_801C40B0_E, 0, 0x0D, 1, 0, 0);
            }
            platform::call3(FN_801C4780_E, 9, DAT_802FD040_E as u32, 4);
            platform::call3(FN_801C4780_E, 10, SDA2_3E00_E as u32, 6);
            if mode == 7 {
                platform::call3(FN_801C4780_E, 0x0D, SDA2_3DE0_E as u32, 2);
            }
        }
        9 => {
            platform::call2(FN_801C37C0_E, 9, 2);
            platform::call2(FN_801C37C0_E, 10, 2);
            platform::call5(FN_801C40B0_E, 0, 9, 1, 3, 0x0E);
            platform::call5(FN_801C40B0_E, 0, 10, 0, 3, 0x0E);
            platform::call3(FN_801C4780_E, 9, DAT_802FD060_E as u32, 6);
            platform::call3(FN_801C4780_E, 10, SDA2_3DC0_E as u32, 6);
        }
        10 | 11 | 12 | 13 => {
            // observed: bVar1 = mode is 0xB or 0xD; bVar2 = mode is 0xA or 0xB.
            let even_lane = mode == 0x0B || mode == 0x0D;
            let odd_lane = mode == 10 || mode == 0x0B;

            platform::call2(FN_801C37C0_E, 9, 2);
            if odd_lane {
                platform::call2(FN_801C37C0_E, 0x0D, 2);
            }
            let block = if even_lane { SDA2_3D80_E } else { SDA2_3DA0_E };
            platform::call3(FN_801C4780_E, 9, block as u32, 2);
            if odd_lane {
                platform::call3(FN_801C4780_E, 0x0D, SDA2_3D80_E as u32, 2);
            }
            platform::call5(FN_801C40B0_E, 0, 9, 0, 0, 0);
            if odd_lane {
                platform::call5(FN_801C40B0_E, 0, 0x0D, 1, 0, 0);
            }
        }
        _ => {}
    }
}

/// Forwards the four words of one sixteen-byte table record to `0x801C8DC0`.
///
/// # Original
/// - Ghidra: `FUN_802c3020` at `0x802C3020` (36 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c3020_FUN_802c3020.c`
/// - observed: `param_1 = param_1 * 0x10; FUN_801c8dc0(*(undefined4 *)
///   (&DAT_802fd0a8 + param_1), *(undefined4 *)(&DAT_802fd0ac + param_1),
///   *(undefined4 *)(&DAT_802fd0b0 + param_1), *(undefined4 *)
///   (&DAT_802fd0b4 + param_1));`
/// - verified: `0x802C3020..0x802C3040`, which is `b 0x801C8DC0` - a pure tail
///   branch with no `bclr`; tsv 36 counts the branch, then two alignment words.
/// - observed: the index is scaled with `rlwinm r3,4,0,27`, i.e. `* 0x10` with
///   the low four bits cleared.
///
/// # Arguments
/// - `index`: record index into the table at `0x802FD0A8` (`r3`).
///
/// # Returns
/// Nothing; the callee's result is not observable here.
///
/// # Safety
/// The record at `0x802FD0A8 + (index & !0xF)` must be readable for 16 bytes.
///
/// # Confidence
/// high - the scale, the table address, the four loads and the tail branch are
/// literal.
pub unsafe fn fn_802c3020(index: u32) {
    let record = DAT_802FD0A8_E + ((index << 4) & 0xFFFF_FFF0) as usize;
    platform::call4(
        FN_801C8DC0_E,
        platform::read_u32(record),
        platform::read_u32(record + 0x04),
        platform::read_u32(record + 0x08),
        platform::read_u32(record + 0x0C),
    );
}

/// Constructs the 0x160-byte display object with its three member objects.
///
/// # Original
/// - Ghidra: `FUN_802c3630` at `0x802C3630` (348 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c3630_FUN_802c3630.c`
/// - observed: `FUN_802c3210(); ... *(undefined **)(param_1 + 4) =
///   &DAT_80350230; *(undefined **)(param_1 + 0x10) = &DAT_8035023c;
///   *(undefined **)(param_1 + 0x14) = &DAT_8035024c; *(undefined **)
///   (param_1 + 0x18) = &DAT_80350280; ... iVar10 = FUN_802b9210(100); ...
///   uVar11 = FUN_802cfba0(); *(param_1 + 0x84) = uVar11; iVar12 =
///   FUN_802b9210(0x78); ... iVar10 = FUN_802cef70(); *(param_1 + 0x80) =
///   iVar10; *(undefined1 *)(iVar10 + 0x2c) = 1; iVar10 = FUN_802b9210(0x1c0);
///   ... puVar13 = FUN_802cf6f0(); ... *puVar13 = 0; ...`
/// - verified: `0x802C3630..0x802C3788` then `4e800020 bclr`; tsv 348 exact.
/// - observed: the ten `unaff_r2` words are **single-precision loads**, not
///   integers: the disassembly is `lfs f8,-0x3D60(r2)`, `lfs f6,-0x3D58(r2)`,
///   `lfs f9,-0x3D64(r2)`, `lfs f7,-0x3D5C(r2)`, `lfs f5,-0x3D54(r2)`,
///   `lfs f4,-0x3D50(r2)`, `lfs f3,-0x3D4C(r2)`, `lfs f2,-0x3D48(r2)`,
///   `lfs f1,-0x3D44(r2)`, `lfs f0,-0x3D40(r2)`, with a final
///   `lfs f0,-0x3D58(r2)` again for the member object's `+0x34`. Their values
///   were read from `work/dol/main.elf` at `0x8042F31C..0x8042F344`:
///   `30.0`, `20.0`, `1.6`, `0.0`, `0.4`, `0.2`, `-0.0075`, `10.0`, `15.0`
///   and `1.0`. The `stfs` stores below use those floats; the export's integer
///   reads are a Ghidra type error.
/// - observed: the three constructors are called with `(r3 = allocated block,
///   r4 = current context)`: `0x802CFBA0(block, 0)`,
///   `0x802CEF70(block, block)` and `0x802CF6F0(block, obj_b)`; the export
///   leaves those arguments blank.
///
/// # Arguments
/// - `this`: object base, at least 0x160 bytes (`r3`).
///
/// # Returns
/// `this`.
///
/// # Safety
/// `this` must be a writable 0x160-byte block. The three allocators must
/// succeed (the original dereferences the results unconditionally).
///
/// # Confidence
/// medium - all offsets, constants and the float set are literal; the meaning
/// of the second constructor argument and the roles of the four pointer slots
/// are inferred.
pub unsafe fn fn_802c3630(this: usize) -> usize {
    platform::call1(FN_802C3210_E, this as u32);

    platform::write_u32(this + 0x04, DAT_80350230_E as u32);
    platform::write_u32(this + 0x10, DAT_8035023C_E as u32);
    platform::write_u32(this + 0x14, DAT_8035024C_E as u32);
    platform::write_u32(this + 0x18, DAT_80350280_E as u32);
    platform::write_u16(this + 0x1C, 1);
    platform::write_u32(this + 0x20, 1);
    platform::write_f32(this + 0x24, 30.0);
    platform::write_f32(this + 0x28, 20.0);
    platform::write_f32(this + 0x2C, 20.0);
    platform::write_f32(this + 0x30, 1.6);
    platform::write_u32(this + 0x34, 0);
    platform::write_u32(this + 0x38, 2);
    platform::write_f32(this + 0x5C, 0.0);
    platform::write_f32(this + 0x60, 0.0);
    platform::write_f32(this + 0x64, 0.4);
    platform::write_f32(this + 0x68, 0.2);
    platform::write_f32(this + 0x6C, -0.0075);
    platform::write_f32(this + 0x70, -0.0075);
    platform::write_f32(this + 0x74, 10.0);
    platform::write_f32(this + 0x78, 15.0);
    platform::write_f32(this + 0x7C, 1.0);
    platform::write_u32(this + 0x80, 0);
    platform::write_u32(this + 0x84, 0);
    platform::write_u32(this + 0x88, 0);
    platform::write_u32(this + 0x8C, 0);

    let block = fn_802b9210(100);
    let member_a = if block != 0 {
        platform::call2(FN_802CFBA0_E, block, 0)
    } else {
        0
    };
    platform::write_u32(this + 0x84, member_a);

    let block = fn_802b9210(0x78);
    let member_b = if block != 0 {
        platform::call2(FN_802CEF70_E, block, block)
    } else {
        0
    };
    platform::write_u32(this + 0x80, member_b);
    platform::write_u8(member_b as usize + 0x2C, 1);

    let block = fn_802b9210(0x1C0);
    let member_c = if block != 0 {
        platform::call2(FN_802CF6F0_E, block, member_b)
    } else {
        0
    };
    platform::write_u32(this + 0x8C, member_c);

    platform::write_u32(member_c as usize, 0);
    platform::write_f32(member_c as usize + 0x34, 0.0);
    platform::write_u32(member_c as usize + 0x2C, 0);
    platform::write_u8(this + 0x1E, 0xFF);
    platform::write_u8(this + 0x1F, 0xFF);

    this
}

// ===========================================================================
// Wave 219, lane F - `resource::archive` bodies at `0x802C0040..0x802C3790`
// ===========================================================================
//
// Ten bodies from the `0x802C0000` band. They are the immediate-mode GX side of
// the same overlay that owns the `0x802Bxxxx` effect helpers already in this
// file: two thin wrappers over the quad-projection pair, one small option
// record, one bit-clear store, one ribbon-strip generator, one quad-state
// setup, one coloured-bar drawer, three table/GX switches and one deleting
// destructor.
//
// | address | size | role |
// |---|---|---|
// | `0x802C0040` | 68 B | project the record's four corners through `0x801C9C10` |
// | `0x802C0090` | 116 B | quantise the same four floats and forward them to `0x801C9C60` |
// | `0x802C0A30` | 68 B | construct the small option record (`vtable 0x80350110`) |
// | `0x802C0B40` | 28 B | guarded word store plus one cleared flag bit |
// | `0x802C13F0` | 800 B | emit one ribbon strip of `n + 2` vertices |
// | `0x802C17E0` | 220 B | one-state quad setup, indexed by the leading zeros of a scale |
// | `0x802C1A30` | 728 B | draw one bar with a per-mode blend/alpha ladder |
// | `0x802C3000` | 32 B | indexed three-argument GX switch |
// | `0x802C3120` | 116 B | two assignments plus one four-argument GX switch |
// | `0x802C3790` | 260 B | deleting destructor of the `0x80350230` object |
//
// ## Sizes
//
// Every size below was re-checked against the prologue and the closing `blr`
// in `work/dol/main.elf`; all ten agree with `functions.tsv`:
//
// * `0x802C0040` `blr` at `0x802C0080` -> `0x40 + 4 = 68`;
// * `0x802C0090` `blr` at `0x802C0100` -> `0x70 + 4 = 116`;
// * `0x802C0A30` `blr` at `0x802C0A70` -> `0x40 + 4 = 68`;
// * `0x802C0B40` `blr` at `0x802C0B58` -> `0x18 + 4 = 28`;
// * `0x802C13F0` `blr` at `0x802C170C` -> `0x31C + 4 = 800`;
// * `0x802C17E0` `blr` at `0x802C18B8` -> `0xD8 + 4 = 220`;
// * `0x802C1A30` `blr` at `0x802C1D04` -> `0x2D4 + 4 = 728`;
// * `0x802C3000` tail-branches to `0x801C8E70`, so the next entry starts at
//   `0x802C3020` and the `32`-byte size is the whole body;
// * `0x802C3120` `blr` at `0x802C3190` -> `0x70 + 4 = 116`;
// * `0x802C3790` `blr` at `0x802C3890` -> `0x100 + 4 = 260`.
//
// ## Floating-point ABI notes
//
// Single-precision values travel in the low half of an FPR and are rounded to
// single by any `f*s` instruction, so `fsubs a, b` computes the correctly
// rounded *single* result of the full double subtraction. Two bodies below use
// the compiler's integer-to-float idiom (`0x4330_0000<<32 | value`, then
// `fsubs` of `0x4330_0000_8000_0000`) which therefore yields the plain integer
// as a `f32`; [`to_f32_signed_f`] reproduces exactly that.
//
// ## Disassembler caveat
//
// `work/ghidra/main-gb/export/802c13f0_FUN_802c13f0.c` opens with fifteen
// "removing unreachable block" warnings and a fabricated `unaff_GQR0`, because
// the function's big-endian float moves use `psq_l`/`psq_st`/`ps_merge00`
// (`ps_merge00` = primary opcode `4`, XO `20`). The export's `ldexpf` ladders
// are that misreading; the raw words at `0x802C1650..0x802C1694` were decoded
// by hand here. The two `0x802DCD6C`/`0x802DCDB8` calls in the export are the
// `__savegprlr_25`/`__restgprlr_25` helpers, not ordinary calls, so they are
// not reproduced as calls.
// ===========================================================================

// ---------------------------------------------------------------------------
// Callees of this lane that are not yet translated.
// ---------------------------------------------------------------------------

/// `0x801C9C10(a, b, c, d, e, f)` - six-double quad projection.
///
/// `// unknown:` the export prints only the six `f64` arguments; the routine is
/// the one [`fn_802bba30`] already calls by address.
const FN_801C9C10_F: usize = 0x801C_9C10;

/// `0x801C9D20(0, 0)` - closes the quad opened by `FN_801C9C10_F`.
const FN_801C9D20_F: usize = 0x801C_9D20;

/// `0x801C8600(a, b, c)` - three-word GX state setter.
const FN_801C8600_F: usize = 0x801C_8600;

/// `0x801C8640(0, 0, 1, 2, 3)` - five-word GX texture-state setter.
const FN_801C8640_F: usize = 0x801C_8640;

/// `0x801C85B0(0, 0)` - two-word GX state setter used by one alpha branch.
const FN_801C85B0_F: usize = 0x801C_85B0;

/// `0x801C1160(handle, src, dst)` - transform one four-float vector in place.
