const FN_801C1530_F: usize = 0x801C_1530;

/// `0x801C1470(v, v)` - normalise one three-float vector in place.
const FN_801C1470_F: usize = 0x801C_1470;

/// `0x802C1F80(mode)` - first state setter of the `0x802C17E0` cluster.
const FN_802C1F80_F: usize = 0x802C_1F80;

/// `0x802C2060(flag)` - second state setter of the same cluster.
const FN_802C2060_F: usize = 0x802C_2060;

/// `0x802C20E0()` - no-argument state setter of the same cluster.
const FN_802C20E0_F: usize = 0x802C_20E0;

/// `0x802C20F0(a, b)` - two-argument state setter of the same cluster.
const FN_802C20F0_F: usize = 0x802C_20F0;

/// `0x802C2250(a, b)` - two-argument state setter of the same cluster.
const FN_802C2250_F: usize = 0x802C_2250;

/// `0x802C2360(token)` - publishes the state token and flushes.
const FN_802C2360_F: usize = 0x802C_2360;

/// `0x802C3020(index)` - four-word GX switch indexed by a 16-byte stride.
const FN_802C3020_F: usize = 0x802C_3020;

/// `0x802C7E30(this + 8, 0)` - release the object's child block.
const FN_802C7E30_F: usize = 0x802C_7E30;

// ---------------------------------------------------------------------------
// Data and tables.
// ---------------------------------------------------------------------------

/// GX FIFO write port.
const GX_FIFO_F: usize = 0xCC00_8000;

/// `0x80350110` - vtable installed by [`fn_802c0a30`].
const VTABLE_80350110_F: usize = 0x8035_0110;

/// `0x80350230` - vtable installed by [`fn_802c3790`].
///
/// The same body also stores `vtable + 0x0C` at `+0x10`, `vtable + 0x1C` at
