const SDA2_F_3E20_F: usize = SDA2_BASE - 0x3E20;
/// `r2 - 0x3E1C` -> `0x8042F264`: `0.5`, the ribbon radius.
const SDA2_F_3E1C_F: usize = SDA2_BASE - 0x3E1C;
/// `r2 - 0x3E18` -> `0x8042F268`: `2^52` as a `f64`, the int-to-f32 magic.
const SDA2_F64_3E18_F: usize = SDA2_BASE - 0x3E18;
/// `r2 - 0x3E10` -> `0x8042F270`: `2^52 + 2^31` as a `f64`, the signed form of
