// ---------------------------------------------------------------------------
// Host-side helpers for this lane.
// ---------------------------------------------------------------------------

/// Reproduces the compiler's unsigned integer-to-`f32` conversion.
///
/// `0x4330_0000_0000_0000 | value` is loaded as an `f64` and the `2^52` magic
/// at `magic_addr` is subtracted with an `fsubs`, which rounds the exact
/// difference to a single. For every value used here the result is the plain
/// integer as an `f32`.
///
/// # Safety
/// `magic_addr` must be readable for eight bytes and hold `2^52`.
unsafe fn to_f32_unsigned_a(value: u32, magic_addr: usize) -> f32 {
    let magic = read_f64_f(magic_addr);
    (f64::from_bits(0x4330_0000_0000_0000u64 | value as u64) - magic) as f32
}

/// Invokes one two-argument virtual slot of the object at `object`.
///
/// This is the `lwz r12,0(r3); lwz r12,<slot>(r12); bcctr` shape
/// `0x802C9840` uses twice, with the object in `r3` and, for the second call,
/// the descriptor in `r4`.
///
/// # Safety
/// `object` must be a live object whose table at `+0x00` holds `slot`.
unsafe fn invoke_slot_two_a(object: usize, slot: usize, arg: u32) -> u32 {
    let table = platform::read_u32(object) as usize;
    let entry = platform::read_u32(table + slot) as usize;
    platform::call2(entry, object as u32, arg)
}

/// Emits one GX immediate quad through the write-gather FIFO.
///
/// Every four vertices are preceded by their `u8` index and carry two `f32`
/// coordinates: `(base, base)`, `(base, base - half)`, `(base + half, base -
/// half)` and `(base + half, base)`. `0x802CC050` emits this exact sequence
/// twice.
///
/// # Safety
/// Must run on the target, where `0xCC008000` is the FIFO port.
unsafe fn emit_gx_quad_a(base: f32, half: f32) {
    let low = base - half;
    let high = half + base;
    for (index, x, y) in [
        (0u8, base, base),
        (1u8, base, low),
        (2u8, high, low),
        (3u8, high, base),
    ] {
        platform::write_u8(GX_FIFO_A, index);
        platform::write_f32(GX_FIFO_A, x);
        platform::write_f32(GX_FIFO_A, y);
    }
}

// ---------------------------------------------------------------------------
// Bodies.
// ---------------------------------------------------------------------------

/// Builds the 80-byte draw descriptor handed to `this`'s vtable slot `+0x0C`.
///
/// # Original
/// - Ghidra: `FUN_802c9840` at `0x802C9840` (420 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c9840_FUN_802c9840.c`
/// - observed: `stw r6,0x0(r4)` .. `stw r6,0xc(r4)` clear `+0x00..+0x0F`,
///   `bl 0x802C9A20` -> `stb r3,0x8(r30)`, `lwz r12,0x0(r28)` /
///   `lwz r12,0x10(r12)` / `bcctr` -> `stw r3,0x4(r30)`, then a four-iteration
///   `bl 0x802C9A10` / `lbzx` / `stb` loop into `+0x00..+0x03`, a clear of
///   `+0x10..+0x4F`, and `lwz r12,0xc(r12)` / `bcctr` with `r3 = this`,
///   `r4 = out`.
/// - `blr` at `0x802C99E0`, so `420` bytes is the whole body.
///
/// # Arguments
/// - `this`: object whose vtable supplies the two calls; `param_1`.
/// - `out`: 80-byte descriptor (`0x802C9A00` returns `0x50` for its size).
///
/// # Returns
/// Nothing; the descriptor is filled through `out`.
///
/// # Side effects
/// - clears all 80 bytes, then writes `+0x08 = 2`, `+0x04 = vtable[0x10]()`,
///   `+0x00..+0x03` from the `"LOBJ"` name slot, and finally calls
///   `vtable[0x0C](this, out)`; the remaining fields stay zero.
///
/// # Confidence
/// high - every store offset and both call slots are explicit in the shipped
/// words; only the meaning of the two vtable slots is `// inferred:`.
pub unsafe fn fn_802c9840(this: usize, out: usize) {
    for offset in (0..0x50).step_by(4) {
        platform::write_u32(out + offset, 0);
    }

    // observed: `bl 0x802C9A20` returns 2.
    platform::write_u8(out + 0x08, call0_u32(FN_802C9A20_A) as u8);

    // observed: virtual slot +0x10, called with the object only; the module's
    // existing `invoke_slot_f` has exactly that shape.
    let value = invoke_slot_f(this as u32, 0x10);
    platform::write_u32(out + 0x04, value);

    // observed: `+0x00..+0x03` receive the four bytes at r13 - 0x5B20, the
    // object name slot `"LOBJ"`.
    let name = call0_u32(FN_802C9A10_A) as usize;
    for index in 0..4 {
        let byte = platform::read_u8(name + index);
        platform::write_u8(out + index, byte);
    }

    // observed: virtual slot +0x0C, called with the object in r3 and the
    // descriptor in r4.
    let _ = invoke_slot_two_a(this, 0x0C, out as u32);
}

/// Copies the pose triple and the four tint bytes from `+0x20` to `+0x6C`.
///
/// # Original
/// - Ghidra: `FUN_802c9c00` at `0x802C9C00` (60 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c9c00_FUN_802c9c00.c`
/// - observed: `lfs f2,0x20(r3)` / `lfs f1,0x24` / `lfs f0,0x28` /
///   `lbz r6,0x2c` .. `lbz r0,0x2f`, then the mirrored `stfs` at `+0x6C`,
///   `+0x70`, `+0x74` and `stb` at `+0x78..+0x7B`; `blr` at `0x802C9C38`, so
///   `60` bytes is the whole body.
///
/// # Arguments
/// - `this`: record; `param_1`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Snapshots `+0x20..+0x2F` into `+0x6C..+0x7B`. `// inferred:` the pose stored
/// at `+0x20` is the live one and `+0x6C` its per-frame copy, because
/// [`fn_802c9e30`] reads the tint bytes from `+0x78` after this copy runs.
///
/// # Confidence
/// high - a pure ten-field copy, byte for byte.
pub unsafe fn fn_802c9c00(this: usize) {
    platform::write_f32(this + 0x6C, platform::read_f32(this + 0x20));
    platform::write_f32(this + 0x70, platform::read_f32(this + 0x24));
    platform::write_f32(this + 0x74, platform::read_f32(this + 0x28));
    platform::write_u8(this + 0x78, platform::read_u8(this + 0x2C));
    platform::write_u8(this + 0x79, platform::read_u8(this + 0x2D));
    platform::write_u8(this + 0x7A, platform::read_u8(this + 0x2E));
    platform::write_u8(this + 0x7B, platform::read_u8(this + 0x2F));
}

/// Fills a three-float position triple and scales a four-byte tint from
/// `+0x78..+0x7B` by a table value.
///
/// # Original
/// - Ghidra: `FUN_802c9e30` at `0x802C9E30` (260 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802c9e30_FUN_802c9e30.c`
/// - observed: `lfs f2,0x94(r3)` / `0x98` / `0x9c` -> `stfs` at `r5+0x0`,
///   `+0x4`, `+0x8`; `lhz r0,0x4(r3)`; `rlwinm r0,r0,2,0,29`;
///   `lwz r3,0x44(r4)`; `lfsx f5,r3,r0`; `lbz r9..r5` from `+0x78..+0x7B` ->
///   `stb` at `r6+0..+3`; `lfs f0,-0x3C48(r2)` (1.0) / `fc050040` (fcmpo) /
///   `bc 4,0` to the plain-copy arm, otherwise the `fctiwz` scaling arm.
/// - `blr` at `0x802C9F30`, so `260` bytes is the whole body.
///
/// # Arguments
/// - `this`: record; `param_1`.
/// - `param_2`: record whose `+0x44` word is a `f32` array base.
/// - `position`: 12-byte out slot that receives the `+0x94/+0x98/+0x9C` triple.
/// - `tint`: four-byte out slot that receives the tint.
///
/// # Returns
/// Nothing; both outputs are written through pointers.
///
/// # Side effects
/// Writes `position[0..3]` and `tint[0..4]`. When the table value is below
/// `1.0` every tint byte is replaced by `trunc(byte * value)` (so it can only
/// darken); otherwise the four bytes are copied unchanged. The comparison is
/// `bc 4,0`, a branch on "false", so the *plain copy* arm is taken whenever the
/// table value is greater than or equal to `1.0`.
///
/// # Confidence
/// high for the offsets and the arithmetic; medium for the meaning of
/// `param_2 + 0x44`, which the export exposes only as a `f32` array indexed by
/// the `u16` at `this + 0x04`.
pub unsafe fn fn_802c9e30(this: usize, param_2: usize, position: usize, tint: usize) {
    platform::write_f32(position + 0x08, platform::read_f32(this + 0x9C));
    platform::write_f32(position, platform::read_f32(this + 0x94));
    platform::write_f32(position + 0x04, platform::read_f32(this + 0x98));

    let index = platform::read_u16(this + 0x04) as usize;
    let table = platform::read_u32(param_2 + 0x44) as usize;
    let scale = platform::read_f32(table + index * 4);

    let source = [
        platform::read_u8(this + 0x78),
        platform::read_u8(this + 0x79),
        platform::read_u8(this + 0x7A),
        platform::read_u8(this + 0x7B),
    ];
    for (offset, byte) in source.iter().enumerate() {
        platform::write_u8(tint + offset, *byte);
    }

    if scale >= platform::read_f32(SDA2_F32_3C48_A) {
        return;
    }
    for (offset, byte) in source.iter().enumerate() {
        let widened = to_f32_unsigned_a(*byte as u32, SDA2_F64_3C38_A);
        platform::write_u8(tint + offset, (widened * scale) as i32 as u8);
    }
}

/// Stores two three-float vectors into the `+0x08` and `+0x14` triples and
/// tail-branches to `0x802CA780`.
///
/// # Original
/// - Ghidra: `FUN_802ca8a0` at `0x802CA8A0` (52 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802ca8a0_FUN_802ca8a0.c`
/// - observed: `lfs f5,0x0(r4)` / `f4,0x4(r4)` / `f3,0x8(r4)`,
///   `lfs f2,0x0(r5)` / `f1,0x4(r5)` / `f0,0x8(r5)`, then `stfs` of `f5`/`f4`/
///   `f3` at `+0x14`/`+0x18`/`+0x1C` and of `f2`/`f1`/`f0` at
///   `+0x08`/`+0x0C`/`+0x10`, then `b 0x802CA780`.
/// - the tail branch at `0x802CA8D0` is the last instruction, so `52` bytes is
///   the whole body.
///
/// # Arguments
/// - `this`: record; `param_1`.
/// - `first`: 12-byte source stored at `+0x14`.
/// - `second`: 12-byte source stored at `+0x08`.
///
/// # Returns
/// Whatever `0x802CA780` returns.
///
/// # Side effects
/// Overwrites the two triples and then runs `0x802CA780` with `this` still in
/// `r3`, so any recomputation of the record's derived fields happens there.
///
/// # Confidence
/// high - six explicit `lfs`/`stfs` pairs plus a tail branch.
pub unsafe fn fn_802ca8a0(this: usize, first: usize, second: usize) {
    let a = platform::read_f32(second);
    let b = platform::read_f32(second + 0x04);
    let c = platform::read_f32(second + 0x08);

    platform::write_f32(this + 0x14, platform::read_f32(first));
    platform::write_f32(this + 0x18, platform::read_f32(first + 0x04));
    platform::write_f32(this + 0x1C, platform::read_f32(first + 0x08));
    platform::write_f32(this + 0x08, a);
    platform::write_f32(this + 0x0C, b);
    platform::write_f32(this + 0x10, c);

    // observed: the tail branch leaves `this` in r3.
    let _ = platform::call1(FN_802CA780_A, this as u32);
}

