/// `0x80308FA8` - type descriptor of the first interface probed by
/// [`fn_802cdd00`]; pushed on the stack word the object's `+0x08` slot reads.
const G_80308FA8_D: usize = 0x8030_8FA8;
/// `0x80308FF0` - type descriptor of the second interface probed by
/// [`fn_802cdd00`] (selected by the probe = kind 1).
const G_80308FF0_D: usize = 0x8030_8FF0;
/// `0x80308FD8` - type descriptor of the third probe (kind 0).
const G_80308FD8_D: usize = 0x8030_8FD8;
/// `0x80309000` - type descriptor of the fourth probe (kind 2).
const G_80309000_D: usize = 0x8030_9000;

/// `0x801C8500(channel, &colour)` - latch one TEV colour word.
const FN_801C8500_D: usize = 0x801C_8500;
/// `0x801C8560(channel, value)` - latch one TEV colour/coord argument.
const FN_801C8560_D: usize = 0x801C_8560;
/// `0x801C8640(channel, a, b, c, d)` - TEV colour-input selection.
const FN_801C8640_D: usize = 0x801C_8640;
