const SDA2_AXIS_SCALE_221E: usize = SDA2_BASE - 0x3C30;
/// `r2 - 0x3E3C` -> `0x8042F244`: the word `0xFFFFFFFF`.
const SDA2_WORD_NEG1_221E: usize = SDA2_BASE - 0x3E3C;
/// `r2 - 0x3E40` -> `0x8042F240`: the word `0x000000FF`.
const SDA2_WORD_FF_221E: usize = SDA2_BASE - 0x3E40;

/// `0x802FD1D0` - the three-float default block copied into `+0x08..+0x10`.
/// `// observed:` all three words are zero in the shipped image; the block is
/// the shared default the sibling instance constructors also copy.
const ARC_DEFAULT_BLOCK_221E: usize = 0x802F_D1D0;

/// `0x8035_03A0` - the instance vtable installed at `+0x00` by
/// [`fn_802c9a30`]. `// inferred:` slots `+0x00`/`+0x04` are cleared in the
/// shipped image and `+0x08` holds `0x802CA8E0`; the object is one of the
/// `0x802CAxxx` instance family.
const ARC_INSTANCE_VTABLE_221E: usize = 0x8035_03A0;

/// `0x8023_8420` - `(out, transform, vector)`: transforms a three-float vector.
const FN_80238420_221E: usize = 0x8023_8420;
/// `0x801C_1160` - `(transform, vector, out)`: the same transform in the
