const FN_801C1160_221E: usize = 0x801C_1160;
/// `0x801C_1470` - `(dst, src)`: normalises a three-float vector in place.
const FN_801C1470_221E: usize = 0x801C_1470;
/// `0x801C_1570` - `(a, b, out)`: unit normal built from two three-float
