const FN_802C30C0_221E: usize = 0x802C_30C0;
/// `0x802C_3120` / `0x802C_31A0` - the second preset pair of [`fn_802ce2a0`].
const FN_802C3120_221E: usize = 0x802C_3120;
const FN_802C31A0_221E: usize = 0x802C_31A0;
/// `0x802C_E010` - `(this, 6, 1, 1, 0)`: the draw/flush step repeated after
/// every preset store.
const FN_802CE010_221E: usize = 0x802C_E010;

/// `0x802C_DED0` - `() -> u16`: the entry count of the placement manager.
const FN_802CDED0_221E: usize = 0x802C_DED0;
/// `0x802C_E620` - `(manager, index) -> u32`: the per-entry record selector.
const FN_802CE620_221E: usize = 0x802C_E620;
/// `0x802C_7560` - the eight-argument name resolver documented earlier in this
/// file (`context`, `object`, `name`, `matrix`, `plain`, `out`, `capacity`,
/// `mode`).
const FN_802C7560_221E: usize = 0x802C_7560;
/// `0x8025_C660` - `(out, table, index)`: fill the 0x6C-byte object block.
const FN_8025C660_221E: usize = 0x8025_C660;
/// `0x8023_B800` - `(word *, index) -> u32`: pick the record table pointer.
const FN_8023B800_221E: usize = 0x8023_B800;

/// Calls `(r3, f1, f2, f3)` - the `0x8025F470`/`0x8025F4B0`/`0x8025F5F0`
/// shape, whose `stfs` stores show the three trailing arguments are `f32`.
unsafe fn call_cell_f32x3_221e(addr: usize, cell: u32, x: f32, y: f32, z: f32) {
    let target: extern "C" fn(u32, f32, f32, f32) = core::mem::transmute(addr);
    target(cell, x, y, z);
}

/// Calls `(ptr) -> f32`, the `0x801C14C0` vector-length shape.
unsafe fn call_ptr_f32_221e(addr: usize, ptr: u32) -> f32 {
    let target: extern "C" fn(u32) -> f32 = core::mem::transmute(addr);
    target(ptr)
}

