const SDA2_F_3D1C_E237: usize = SDA2_BASE - 0x3D1C;
/// `r2 - 0x3D30` -> `0x8042F350`: four mode bytes `04 02 01 00`, indexed by
/// the object's `+0x34` kind.
const SDA2_BYTES_3D30_E237: usize = SDA2_BASE - 0x3D30;
/// `r13 - 0x47B0` -> `0x8042AED0`: pointer to the mode record whose `+0x00`
/// is the mode and whose `+0x18`/`+0x1C` are the low/high extents.
const SDA_47B0_E237: usize = SDA_BASE - 0x47B0;
/// `0x802FD1A4` - five-word relative-offset table indexed by the clamped
/// `+0x38` state and copied to the child's `+0x5C`.
const TABLE_802FD1A4_E237: usize = 0x802F_D1A4;

/// PowerPC branch-shaped `min`: returns `value` unless it compares greater than
/// `limit`, in which case `limit` is returned. NaN therefore keeps `value`,
/// matching the `fcmpo`/`cror`/`bc 4,2` sequence in [`fn_802c3980`].
fn min_e237(value: f32, limit: f32) -> f32 {
    if value > limit {
        limit
    } else {
        value
    }
}

/// Branch-shaped clamp to `[0, 1]`. NaN passes through as NaN, exactly as the
/// unordered `fcmpo` pair at `0x802C39FC`/`0x802C3A0C` does.
fn clamp01_e237(value: f32) -> f32 {
    let mut out = 0.0f32;
    if !(value < 0.0) {
        out = 1.0f32;
        if !(value > 1.0) {
            out = value;
        }
    }
    out
}

/// One bound of [`fn_802c3980`]: the mode-1 affine arm or the plain `(a - lo)`
/// ratio, with the sign of `value` restored.
fn bound_e237(value: f32, mode: u32, lo: f32, hi: f32, span: f32) -> f32 {
    let raw = if mode == 1 {
        1.0f32 + (((value * -lo) / span) - ((hi * lo) / span)) / -value
    } else {
        ((-value) - lo) / span
    };
    clamp01_e237(raw)
}

/// `fctiwz` low byte: truncate toward zero, then keep the low eight bits.
///
/// `+inf` maps to `0x7FFFFFFF` and NaN to `0x80000000`, so the byte matches the
/// shipped `stfd`/`lwz` pair even on the division-by-zero arm.
fn fctiwz_byte_e237(value: f32) -> u8 {
    let word = if value.is_nan() {
        0x8000_0000u32
    } else if value >= i32::MAX as f32 {
        i32::MAX as u32
    } else if value <= i32::MIN as f32 {
        0x8000_0000u32
    } else {
        value as i32 as u32
    };
    word as u8
}

