///   and floored with `-1.0e-6`; the resulting ratios are clamped to `[0,1]`.
///   The middle/upper pair then runs the `1.0e-6` overlap correction at
///   `0x802C3B5C..0x802C3B80`.
/// - observed: the child at `+0x84` receives `+0x48 = middle`, `+0x44 = low`,
///   `+0x4C = high`; the child at `+0x80` receives the mode byte from
///   `0x8042F350`, the `+0x30` height (or `0` when `+0x34 == 2`), and four
///   bytes derived from `+0x1E` and the just-written mode byte.
/// - observed: the `+0x38` state is clamped to `2` when it is `>= 3`, then
///   indexes the five-word table at `0x802FD1A4` for the child's `+0x5C`.
/// - the integer-to-float paths are the `2^52` (`0x4330000000000000`) bias
///   idiom at `0x802C3BFC..0x802C3C50`; [`fctiwz_byte_e237`] reproduces the
///   `fctiwz` truncation and low-byte stores at `0x802C3C54..0x802C3C98`.
///
/// # Arguments
/// - `this`: live object of the `0x80350230` family.
/// - `_x`, `_y`: the two selectors passed by [`fn_802c3460`]; the shipped body
///   overwrites `f1`/`f2` before reading them, so they are unused.
///
/// # Side effects
/// Writes three floats at `child(+0x84)+0x44..0x4C`, one word at `+0x5C`, and
/// five bytes/one float on `child(+0x80)` at `+0x38..0x44`.
///
/// # Safety
/// `this` must be live, `*(this+0x84)` and `*(this+0x80)` must point to the
/// two child panes, and `*(r13-0x47B0)` must point to the mode record.
///
/// # Confidence
/// high - all arithmetic and every store are literal; the only inferred point
/// is that `+0x30`/`+0x34` are the height and kind fields.
pub unsafe fn fn_802c3980(this: usize, _x: f32, _y: f32) {
    let neg_eps = platform::read_f32(SDA2_F_3D2C_E237);
    let record = platform::read_u32(SDA_47B0_E237) as usize;
    let mode = platform::read_u32(record);
    let lo = platform::read_f32(record + 0x18);
    let hi = platform::read_f32(record + 0x1C);
    let span = hi - lo;

    let offset = platform::read_f32(this + 0x24);
    let scale = platform::read_f32(this + 0x28);

    let low = bound_e237(
        min_e237(-offset, neg_eps),
        mode,
        lo,
        hi,
        span,
    );
    let half = scale * platform::read_f32(SDA2_F_3D28_E237);
    let middle = bound_e237(
        min_e237(-(offset - half), neg_eps),
        mode,
        lo,
        hi,
        span,
    );
    let high = bound_e237(
        min_e237(-(offset + half), neg_eps),
        mode,
        lo,
        hi,
        span,
    );

    let eps = -neg_eps;
    let mut middle_out = middle;
    let mut high_out = high;
    let overlap = eps + middle;
    if high < overlap {
        high_out = platform::read_f32(SDA2_F_3D40_E237);
        if middle > platform::read_f32(SDA2_F_3D40_E237) {
            high_out = overlap;
        } else {
            middle_out = middle - eps;
        }
    }

    let mut child = platform::read_u32(this + 0x84) as usize;
    platform::write_f32(child + 0x48, middle_out);
    child = platform::read_u32(this + 0x84) as usize;
    platform::write_f32(child + 0x44, low);
    child = platform::read_u32(this + 0x84) as usize;
    platform::write_f32(child + 0x4C, high_out);

    let mut state = platform::read_u32(this + 0x38);
    if state >= 3 {
        platform::write_u32(this + 0x38, 2);
    }
    state = platform::read_u32(this + 0x38);
    child = platform::read_u32(this + 0x84) as usize;
    let slot_word = platform::read_u32(TABLE_802FD1A4_E237 + ((state << 2) as usize));
    platform::write_u32(child + 0x5C, slot_word);

    let kind = platform::read_u32(this + 0x34);
    child = platform::read_u32(this + 0x80) as usize;
    let mode_byte = platform::read_u8(SDA2_BYTES_3D30_E237 + kind as usize);
    platform::write_u8(child + 0x38, mode_byte);

    let kind_again = platform::read_u32(this + 0x34);
    let height = if kind_again == 2 {
        platform::read_f32(SDA2_F_3D58_E237)
    } else {
        platform::read_f32(this + 0x30)
    };
    child = platform::read_u32(this + 0x80) as usize;
    platform::write_f32(child + 0x44, height);

    child = platform::read_u32(this + 0x80) as usize;
    let source_byte = platform::read_u8(this + 0x1E) as u32;
    let divisor = platform::read_u8(child + 0x38) as u32;
    let divisor_f = divisor as f32;

    // `fctiwz(0.5 + 255.0 / divisor)` then the low byte.
    let rounded = platform::read_f32(SDA2_F_3D28_E237)
        + platform::read_f32(SDA2_F_3D20_E237) / divisor_f;
    let rounded_byte = fctiwz_byte_e237(rounded);

    // `fctiwz(1.75 * source / divisor)`, capped at 255.
    let alpha = platform::read_f32(SDA2_F_3D1C_E237) * source_byte as f32 / divisor_f;
    let alpha_capped = if alpha > platform::read_f32(SDA2_F_3D20_E237) {
        platform::read_f32(SDA2_F_3D20_E237)
    } else {
        alpha
    };
    let alpha_byte = fctiwz_byte_e237(alpha_capped);

    platform::write_u8(child + 0x39, rounded_byte);
    platform::write_u8(child + 0x3A, rounded_byte);
    platform::write_u8(child + 0x3B, rounded_byte);
    platform::write_u8(child + 0x3C, alpha_byte);
}

