/// `+0x1C` bit and of the `0x80429B80` gate is inferred.
pub unsafe fn fn_802c3cb0(this: usize, mode: u32) {
    if mode == 0 {
        let gate = platform::read_u32(G_PANE_GATE_5B00_E238);
        if gate & 0x02 == 0 {
            let flag_bit = ((platform::read_u16(this + 0x1C) as u32) >> 1) & 1;
            platform::call2(FN_802D2270_E238, flag_bit, this as u32);
        }
        platform::call0(FN_802D2F10_220A);
    }

    if platform::read_u32(this + 0x20) == 2 {
        platform::call2(FN_802C4700_E238, this as u32, mode);
    } else {
        fn_802c3d80(this, mode);
    }

    match mode {
        1 => {
            crate::runtime::cpp::fn_802d2310(0, this as u32);
            crate::runtime::cpp::fn_802d21f0(3, this as i32);
        }
        2 => {
            let pane = platform::read_u32(this + 0x88) as usize;
            if pane != 0 {
                crate::runtime::cpp::fn_802d3370(pane);
                platform::write_u32(this + 0x88, 0);
            }
        }
        _ => {}
    }
}

