/// `fctiwz` followed by the `rlwinm 0,16,31` mask: truncate to a signed word
/// and keep the low sixteen bits, as the shipped `stfd`/`lwz` pair does.
fn fctiwz_low16_f240(value: f32) -> f32 {
    ((value as i32 as u32) & 0xFFFF) as f32
}

/// Branch-shaped `a * (1 - t) + b * t`, with `t < 0` keeping `a` and `t > 1`
/// taking `b`.
///
/// The unordered (NaN) case follows the `fcmpo`/`bc 4,0` sequence: it is not
/// less than zero and not greater than one, so it falls into the arithmetic
/// arm exactly as the original does.
fn lerp_f32_f240(t: f32, a: f32, b: f32) -> f32 {
    if t < 0.0 {
        a
    } else if t > 1.0 {
        b
    } else {
        a * (1.0 - t) + b * t
    }
}

