    platform::write_f32(record + 0x18, platform::read_f32(this + 0x24));
    platform::write_f32(record + 0x1C, platform::read_f32(this + 0x28));
    platform::write_f32(record + 0x20, platform::read_f32(this + 0x2C));
    platform::write_f32(record + 0x24, platform::read_f32(this + 0x30));
    platform::write_f32(record + 0x30, platform::read_f32(this + 0x64));
    platform::write_f32(record + 0x34, platform::read_f32(this + 0x68));
    platform::write_f32(record + 0x28, platform::read_f32(this + 0x6C));
    platform::write_f32(record + 0x2C, platform::read_f32(this + 0x70));
