    let geometry = platform::call1(FN_802D17C0_A, owner as u32) as usize;
    let viewport_one = platform::read_u32(G_ARC_VIEWPORT_A_A) == 1;
    let state_word = platform::read_u32(G_802C7A90_STATE_D);

