                    let colour = platform::read_u32(this + 0x24);
                    fn_802c2f70(17, rect_ptr, &colour as *const u32 as usize);
                    platform::call2(FN_801C8FC0, 0, 0);
                    platform::call1(FN_802D2F80_A, saved & 0xFF);
