pub unsafe fn fn_802c6170(this: usize, record: usize) {
    if platform::read_u8(record + 0x08) != 0 {
        return;
    }
    platform::write_f32(this + 0x08, platform::read_f32(record + 0x10));
    platform::write_f32(this + 0x0C, platform::read_f32(record + 0x14));
    platform::write_f32(this + 0x10, platform::read_f32(record + 0x18));
    platform::write_f32(this + 0x14, platform::read_f32(record + 0x1C));
    platform::write_u8(this + 0x04, platform::read_u8(record + 0x20));
    platform::write_u8(this + 0x05, platform::read_u8(record + 0x21));
    platform::write_u8(this + 0x06, platform::read_u8(record + 0x22));
    platform::write_u8(this + 0x07, platform::read_u8(record + 0x23));
    platform::write_u32(this + 0x18, platform::read_u8(record + 0x24) as u32);
    platform::write_u8(this + 0x1C, platform::read_u8(record + 0x25));
}

