            platform::write_u8(this + 0x3C, platform::read_u8(record + 0x12));
            platform::write_u8(this + 0x3E, platform::read_u8(record + 0x10));
            platform::write_u8(this + 0x3F, platform::read_u8(record + 0x11));
            platform::write_u16(this + 0x68, platform::read_u16(record + 0x16));
            platform::write_u16(this + 0x06, platform::read_u16(record + 0x4C));
