    platform::write_u8(this + 0x38, platform::read_u8(record + 0x38));
    platform::write_u8(this + 0x39, platform::read_u8(record + 0x39));
    platform::write_u8(this + 0x3A, platform::read_u8(record + 0x3A));
    platform::write_u8(this + 0x3B, platform::read_u8(record + 0x3B));
    platform::write_f32(this + 0x40, platform::read_f32(record + 0x3C));
    platform::write_f32(this + 0x44, platform::read_f32(record + 0x40));
    platform::write_f32(this + 0x48, platform::read_f32(record + 0x44));

    fn_802c9c00(this);
