    platform::write_u8(record + 0x3A, platform::read_u8(this + 0x3A));
    platform::write_u8(record + 0x3B, platform::read_u8(this + 0x3B));

    platform::write_f32(record + 0x3C, platform::read_f32(this + 0x40));
