///
/// # Original (untabled)
/// - Ghidra: no export and no `functions.tsv` row for `0x802CCCB0`.
/// - Evidence: `work/dol/main.elf`, disassembly `0x802CCCB0..0x802CCD9B`;
///   `bclr 20,0` at `0x802CCD98`.
/// - extent: 236 bytes (`0xEC`); `0x802CCD9C..0x802CCD9F` is zero padding
///   before [`fn_802ccda0`].
/// - vtable evidence: the word at `0x803503F0` (file offset `0x34C950`), slot 6
///   of [`VTABLE_803503D0_F`].
/// - observed: `+0x34 = this+0x37`, `u16 +0x10 = this+0x34`, then
///   `0x802E19F8(record + 0x14, this + 0x54, 0x20)` copies the 32-byte header
///   block.
/// - observed: `this+0x34` eight-byte entries start at `record + 0x48`; each
///   receives `*(f32 *)(*(this + 0x44) + i * 4)` at `+0`, the byte
///   `*(u8 *)(*(this + 0x4C) + i)` at `+4`, and bit 0 of
///   `*(u8 *)(*(this + 0x48) + i)` at `+5`.
/// - observed: the tail writes `record+0x12 = this+0x36 & 1`,
///   `record+0x13 = this+0x35` and `f32 record+0x3C = this+0x50`.
///
/// # Arguments
/// - `this`: pane record read by the serialiser.
/// - `record`: destination transfer block; every written field is listed above.
///
/// # Safety
/// The three `this` arrays must cover `*(u8 *)(this + 0x34)` entries and
/// `record` must be writable through `+0x48 + count * 8`.
///
/// # Confidence
/// high - the header copy, the entry loop, the three index loads and the tail
/// are literal.
pub unsafe fn fn_802cccb0(this: usize, record: usize) {
    platform::write_u8(record + 0x34, platform::read_u8(this + 0x37));
    platform::write_u16(record + 0x10, platform::read_u8(this + 0x34) as u16);
    platform::call3(
        FN_802E19F8_F243,
        (record + 0x14) as u32,
        (this + 0x54) as u32,
        0x20,
    );

    let count = platform::read_u8(this + 0x34) as u32;
    let mut index = 0u32;
    while index < count {
        let entry = record + 0x48 + index as usize * 8;

        let flags = platform::read_u32(this + 0x48) as usize;
        platform::write_u8(entry + 0x05, platform::read_u8(flags + index as usize) & 1);

        let values = platform::read_u32(this + 0x44) as usize;
        platform::write_f32(entry, platform::read_f32(values + index as usize * 4));

        let bytes = platform::read_u32(this + 0x4C) as usize;
        platform::write_u8(entry + 0x04, platform::read_u8(bytes + index as usize));

        index += 1;
    }

    platform::write_u8(
        record + 0x12,
        if platform::read_u8(this + 0x36) & 1 != 0 {
            1
        } else {
            0
        },
    );
    platform::write_u8(record + 0x13, platform::read_u8(this + 0x35));
    platform::write_f32(record + 0x3C, platform::read_f32(this + 0x50));
}

