/// Clears the `field` word of every 8-byte record in the counted container at
/// `base` whose value falls in `low..=high`.
///
/// The container holds its record count at `+0x00`; record `i` starts at
/// `base + 0x04 + 8 * i` and owns two words (`+0x00` and `+0x04`). The
/// comparisons are the unsigned `cmpl` pair of the original, so both bounds are
/// inclusive. A null container never reaches here (each caller tests it first).
unsafe fn clear_range_field(base: usize, low: u32, high: u32, field: usize) {
    let mut index = 0u32;
    while index < platform::read_u32(base) {
        let entry = base + 0x04 + index as usize * 0x08;
        let value = platform::read_u32(entry + field);
        if value >= low && value <= high {
            platform::write_u32(entry + field, 0);
        }
        index += 1;
    }
}

