    crate::runtime::dvd::fn_801c0540(
        local.as_ptr() as usize,
        scale.as_ptr() as usize,
        local.as_mut_ptr() as usize,
    );

    crate::render::gx_band::fn_80296640(
        local.as_mut_ptr() as usize as u32,
        local.as_mut_ptr() as usize as u32,
        this + 0xa8,
    );
    crate::render::gx_band::fn_802965b0(
        local.as_mut_ptr() as usize,
        this + 0x9c,
        local.as_ptr() as usize,
    );
    crate::render::gx_band::fn_80295a90(local.as_ptr() as usize, this + 0xa8);
    crate::render::gx_band::fn_802891c0(this);
