/// `0x524C494D`: `'RLIM'`, the indirect-matrix animation target.
const D281_TAG_RLIM: u32 = 0x524C_494D;

/// `r2 - 0x3F74` -> `0x8042F10C`: `0.5f`, the half-frame bias added by the
/// renderer-bound targets.
const D281_F_HALF: usize = SDA2_BASE - 0x3F74;

/// Samples one floating-point keyframe track: `(data, count, frame) -> f32`.
///
/// # Safety
/// `data` must be a keyframe block accepted by `0x802B4EE0`.
unsafe fn d281_sample_f32(data: usize, count: u32, frame: f32) -> f32 {
    let target: extern "C" fn(u32, u32, f32) -> f32 = core::mem::transmute(D281_FN_802B4EE0);
    target(data as u32, count, frame)
}

/// Samples one integer keyframe track: `(data, count, frame) -> u16`.
///
/// The original returns the halfword in `r3`; the upper half is not part of
/// the contract.
///
/// # Safety
/// `data` must be a keyframe block accepted by `0x802B4DF0`.
unsafe fn d281_sample_u16(data: usize, count: u32, frame: f32) -> u32 {
    let target: extern "C" fn(u32, u32, f32) -> u32 = core::mem::transmute(D281_FN_802B4DF0);
    target(data as u32, count, frame)
}

/// Deleting destructor: re-installs the vtable, frees the two arrays and
/// optionally releases the object through [`HEAP_DELETE`].
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row and no export file for `0x802B5110`.
/// - Extent: `0x802B5110..0x802B5194` (132 bytes, 33 instructions), ending at
///   the `blr` at `0x802B5190`; three zero words follow at
///   `0x802B5194..0x802B51A0`.
/// - Table: slot 0 of `0x8034FB78` (word `0x8034FB80`).
/// - Observed: `cmplwi r3,0`; `beq 0x802B5178`; `lwz r4,0x18(r3)`;
///   `lis r5,0x8035`; `addi r5,r5,-1160` (`0x8034FB78`); `stw r5,0(r3)`;
///   `cmpwi r4,0` + `beq`; `lwz r3,-0x48B8(r13)`; `bl 0x801D5550`;
///   `lwz r4,0x14(r3)`; `cmpwi r4,0` + `beq`; `lwz r3,-0x48B8(r13)`;
///   `bl 0x801D5550`; `cmpwi r31,0` + `ble 0x802B5178`; `mr r3,r30`;
///   `bl 0x802B9280`; epilogue; `blr`.
///
/// # Arguments
/// - `this`: object to destroy, or 0.
/// - `deleting`: C++ deleting-destructor flag; only positive values release.
///
/// # Returns
/// `this`.
///
/// # Side effects
/// Writes the vtable, frees `+0x18` and `+0x14` through the EGG root heap and
/// may call [`HEAP_DELETE`].
///
/// # Safety
/// `this` must be null or a live 32-byte block of this class.
///
/// # Confidence
/// high - the null/flag guards, both frees, the vtable store and the release
/// call are literal.
pub unsafe fn fn_802b5110(this: usize, deleting: i32) -> usize {
    if this != 0 {
        let first = platform::read_u32(this + 0x18) as usize;
        platform::write_u32(this, VTABLE_8034FB78 as u32);
        if first != 0 {
            platform::call2(FN_801D5550, platform::read_u32(EGG_ROOT_HEAP), first as u32);
        }
        let second = platform::read_u32(this + 0x14) as usize;
        if second != 0 {
            platform::call2(FN_801D5550, platform::read_u32(EGG_ROOT_HEAP), second as u32);
        }
        if deleting > 0 {
            platform::call1(HEAP_DELETE, this as u32);
        }
    }
    this
}

/// Tail-dispatches the method at vtable offset `+0x10`, adding the `u16` at
/// `record + 0x0E` as the fourth argument.
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row and no export file for `0x802B51A0`.
/// - Extent: `0x802B51A0..0x802B51B4` (20 bytes, 5 instructions), ending at
///   the `bcctr 20,0` at `0x802B51B0`; three zero words follow at
///   `0x802B51B4..0x802B51C0`.
/// - Table: slot 1 of `0x8034FB78` (word `0x8034FB84`).
/// - Observed: `lwz r12,0(r3)`; `lhz r6,0xE(r4)`; `lwz r12,0x10(r12)`;
///   `mtctr r12`; `bcctr 20,0`.
///
/// # Arguments
/// - `this`: animation-target object.
/// - `record`: descriptor forwarded unchanged in `r4`.
/// - `third`: `r5` forwarded unchanged.
///
/// # Returns
/// The callee's `r3`, dropped as in the sibling tail dispatchers.
///
/// # Side effects
/// One virtual call on `this`.
///
/// # Safety
/// `this` must start with a live vtable and `record + 0x0E` must be readable.
///
/// # Confidence
/// high - all five instructions are literal; the `r6` argument is the only
/// non-obvious part and the halfword load proves it.
pub unsafe fn fn_802b51a0(this: usize, record: usize, third: u32) {
    let vtable = platform::read_u32(this) as usize;
    let count = platform::read_u16(record + 0x0E) as u32;
    platform::call4(
        platform::read_u32(vtable + 0x10) as usize,
        this as u32,
        record as u32,
        third,
        count,
    );
}

/// Constructs the animation-target object: caches the descriptor, resolves the
/// `'timg'` handles and allocates the 16-byte slot array.
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row and no export file for `0x802B51C0`.
/// - Extent: `0x802B51C0..0x802B532C` (364 bytes, 91 instructions), ending at
///   the `blr` at `0x802B5328`; one zero word follows at `0x802B532C`.
/// - Table: slot 2 of `0x8034FB78` (word `0x8034FB88`).
/// - Observed: `lhz r27,0xC(r4)`; `li r30,0`; `stw r4,0xC(r3)`;
///   `stw r30,0x14(r3)`; `lwz r3,-0x48B8(r13)`; `rlwinm r4,r27,2,14,29`;
///   `bl 0x801D5540`; zero loop `stw r30,0(r4)`/`addi r4,r4,4`/`bdnz`;
///   `stw r3,0x14(r31)`; `lis r30,0x7469`/`addi r4,r30,0x6D67` (`'timg'`);
///   `lwz r12,0(r24)`; `lwz r12,0xC(r12)`; `add r5,r29,r0`;
///   `stwx r3,r4,r27`; `lwz r3,-0x48B8(r13)`; `rlwinm r4,r25,4,12,27`;
///   `bl 0x801D5540`; 16-byte zero loop; `stw r3,0x18(r31)`;
///   `sth r25,0x1C(r31)`; epilogue; `blr`.
///
/// # Arguments
/// - `this`: object to initialise.
/// - `descriptor`: animation descriptor cached at `+0x0C`.
/// - `owner`: collector whose vtable slot `+0x0C` resolves one `'timg'` name.
/// - `count2`: number of 16-byte slot records to allocate.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Two EGG-root-heap allocations, `desc + 0x0C` virtual calls and the
/// descriptor cache.
///
/// # Safety
/// `this` must be writable through `+0x1D`, the descriptor readable and the
/// collector's `+0x0C` slot must accept `(tag, address, 0)`.
///
/// # Confidence
/// high - both allocations, both zero loops, the `'timg'` immediate and every
/// store are literal.
pub unsafe fn fn_802b51c0(this: usize, descriptor: usize, owner: usize, count2: u32) {
    let count = platform::read_u16(descriptor + 0x0C) as u32;
    platform::write_u32(this + 0x0C, descriptor as u32);
    platform::write_u32(this + 0x14, 0);
    if count != 0 {
        let heap = platform::read_u32(EGG_ROOT_HEAP);
        let block = platform::call2(FN_801D5540, heap, count.wrapping_mul(4)) as usize;
        if block != 0 {
            for index in 0..count as usize {
                platform::write_u32(block + index * 4, 0);
            }
            for index in 0..count as usize {
                let offset = platform::read_u32(descriptor + 0x14 + index * 4) as usize;
                let value = virtual3_105(
                    owner,
                    0x0C,
                    D281_4CC_TIMG,
                    (descriptor + 0x14 + offset) as u32,
                    0,
                );
                platform::write_u32(block + index * 4, value);
            }
        }
        platform::write_u32(this + 0x14, block as u32);
    }

    let heap = platform::read_u32(EGG_ROOT_HEAP);
    let slots = platform::call2(FN_801D5540, heap, count2.wrapping_mul(0x10)) as usize;
    platform::write_u32(this + 0x18, slots as u32);
    if slots != 0 {
        for index in 0..count2 as usize {
            let slot = slots + index * 0x10;
            platform::write_u32(slot, 0);
            platform::write_u32(slot + 0x04, 0);
            platform::write_u32(slot + 0x08, 0);
            platform::write_u16(slot + 0x0C, 0);
            platform::write_u8(slot + 0x0E, 0);
        }
        platform::write_u16(this + 0x1C, count2 as u16);
    }
}

/// Binds every descriptor node with `+0x15 == 0` through the owner's `+0x3C`
/// slot, and every node with `+0x15 != 0` through `+0x40`.
///
/// Each successful call fills one free 16-byte record with
/// `{+0x08 this, +0x0C index, +0x0E mode}` and hands it to either
/// [`FN_802AC080_105`] (flag clear) or [`D281_FN_802B49E0`] (flag set).
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row and no export file for `0x802B5330`.
/// - Extent: `0x802B5330..0x802B54FC` (460 bytes, 115 instructions), ending at
///   the `blr` at `0x802B54F8`; one zero word follows at `0x802B54FC`.
/// - Table: slot 3 of `0x8034FB78` (word `0x8034FB8C`).
/// - Observed: `lwz r7,0xC(r3)`; `lwz r0,0x10(r7)`; `add r31,r7,r0`;
///   `lwz r0,0x18(r25)`; `lhz r0,0x1C(r25)`; `rlwinm r0,r0,4,0,27`;
///   `subf r0,r30,r4`; `rlwinm r0,r0,28,4,31` (the free-slot count);
///   `lwz r0,8(r30)`/`addi r30,r30,0x10`/`bdnz` (free-slot scan);
///   `lwz r0,(r31)`; `add r4,r4,r0`; `lbz r0,0x15(r4)`;
///   `lwz r12,0(r26)`; `lwz r12,0x3C(r12)`/`0x40(r12)`; `bcctr 20,0l`;
///   `stw r25,8(r30)`; `sth r29,0xC(r30)`; `stb r28,0xE(r30)`;
///   `bl 0x802AC080` / `bl 0x802B49E0`; `addi r29,r29,1`;
///   `lhz r0,0xE(r4)`/`cmpl`/`blt` (node loop).
///
/// # Arguments
/// - `this`: animation-target object whose `+0x0C` is the descriptor.
/// - `source`: collector providing the `+0x3C`/`+0x40` node factories.
/// - `third`: argument forwarded to those factories.
/// - `mode`: byte stored at slot `+0x0E`.
///
/// # Returns
/// Nothing; returns early when the slot array is full.
///
/// # Side effects
/// Up to `u16[desc + 0x0E]` virtual calls and slot records.
///
/// # Safety
/// The descriptor, the collector and the slot array must be live and
/// writable through the last occupied record.
///
/// # Confidence
/// high - the two flag paths, the offset arithmetic, the slot-record layout
/// and the two binding helpers are literal; [`scan_slot_105`] is the same
/// inline scan the export uses in [`fn_802b60b0`].
pub unsafe fn fn_802b5330(this: usize, source: usize, third: u32, mode: u8) {
    let descriptor = platform::read_u32(this + 0x0C) as usize;
    let base = descriptor + platform::read_u32(descriptor + 0x10) as usize;
    let count = platform::read_u16(descriptor + 0x0E) as u32;
    let mut index = 0u32;
    while index < count {
        let offset = platform::read_u32(base + index as usize * 4) as usize;
        let node = descriptor + offset;
        let (target, clear) = if platform::read_u8(node + 0x15) == 0 {
            (virtual2_105(source, 0x3C, node as u32, third), true)
        } else {
            (virtual2_105(source, 0x40, node as u32, third), false)
        };
        if target != 0 {
            let slot = scan_slot_105(this, 0);
            if slot == 0 {
                return;
            }
            platform::write_u32(slot + 0x08, this as u32);
            platform::write_u16(slot + 0x0C, index as u16);
            platform::write_u8(slot + 0x0E, mode);
            if clear {
                platform::call2(FN_802AC080_105, target, slot as u32);
            } else {
                platform::call2(D281_FN_802B49E0, target, slot as u32);
            }
        }
        index += 1;
    }
}

/// Binds every descriptor node with `+0x15 == 1` after a `0x802B67E0` guard.
///
/// Unlike [`fn_802b5330`] the successful record is inserted into `source`'s own
/// list through [`D281_FN_802B49E0`], and the guard compares a 20-byte header
/// at `source + 0x44` with the node.
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row and no export file for `0x802B5500`.
/// - Extent: `0x802B5500..0x802B5618` (280 bytes, 70 instructions), ending at
///   the `blr` at `0x802B5614`; two zero words follow at
///   `0x802B5618..0x802B5620`.
/// - Table: slot 4 of `0x8034FB78` (word `0x8034FB90`).
/// - Observed: `lwz r6,0xC(r3)`; `lwz r0,0x10(r6)`; `add r26,r6,r0`;
///   `lwz r0,(r26)`; `add r4,r4,r0`; `lbz r0,0x15(r4)`;
///   `cmplwi r0,1`/`bne`; `addi r3,r28,0x44`; `bl 0x802B67E0`;
///   `cmplwi r3,0`/`beq`; free-slot scan `lwz r0,8(r31)`;
///   `stw r27,8(r31)`; `sth r30,0xC(r31)`; `stb r29,0xE(r31)`;
///   `mr r3,r28`/`mr r4,r31`/`bl 0x802B49E0`; `addi r30,r30,1`;
///   `lhz r0,0xE(r4)`/`cmpl`/`blt`.
///
/// # Arguments
/// - `this`: animation-target object whose `+0x0C` is the descriptor.
/// - `source`: object providing the `+0x44` header and receiving the records.
/// - `mode`: byte stored at slot `+0x0E`.
///
/// # Returns
/// Nothing; returns early when the slot array is full.
///
/// # Side effects
/// One `0x802B67E0` call per matching node and one list insertion per slot.
///
/// # Safety
/// The descriptor and `source` must be live and the slot array writable.
///
/// # Confidence
/// high - every offset, both guards and the insertion are literal. The
/// `0x802B67E0` call receives the node in `r4` from the preceding `add`, which
/// is why it is passed explicitly here.
pub unsafe fn fn_802b5500(this: usize, source: usize, mode: u8) {
    let descriptor = platform::read_u32(this + 0x0C) as usize;
    let base = descriptor + platform::read_u32(descriptor + 0x10) as usize;
    let count = platform::read_u16(descriptor + 0x0E) as u32;
    let mut index = 0u32;
    while index < count {
        let offset = platform::read_u32(base + index as usize * 4) as usize;
        let node = descriptor + offset;
        if platform::read_u8(node + 0x15) == 1 {
            if platform::call2(
                D281_FN_802B67E0,
                (source + 0x44) as u32,
                node as u32,
            ) != 0 {
                let slot = scan_slot_105(this, 0);
                if slot == 0 {
                    return;
                }
                platform::write_u32(slot + 0x08, this as u32);
                platform::write_u16(slot + 0x0C, index as u16);
                platform::write_u8(slot + 0x0E, mode);
                platform::call2(D281_FN_802B49E0, source as u32, slot as u32);
            }
        }
        index += 1;
    }
}

/// Applies the `RLPA`, `RLVI` and `RLVC` children of one descriptor node.
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row and no export file for `0x802B5620`.
/// - Extent: `0x802B5620..0x802B57FC` (476 bytes, 119 instructions), ending at
///   the `blr` at `0x802B57F8`; one zero word follows at `0x802B57FC`, then
///   slot 6 begins at `0x802B5800`.
/// - Table: slot 5 of `0x8034FB78` (word `0x8034FB94`).
/// - Observed: `lwz r6,0xC(r3)`; `rlwinm r4,r4,2,0,29`;
///   `lwz r0,0x10(r6)`; `add r0,r6,r0`; `lwzx r0,r4,r0`; `add r30,r6,r0`
///   (descriptor node); `lfs f31,0.5`; `lbz r0,0x14(r30)` (child count);
///   child loop `lwz r0,(r28)`/`add r29,r30,r0`; `addis r0,r3,0xADB4`;
///   compares `0x5041` (`RLPA`), `0x5649` (`RLVI`), `0x5643` (`RLVC`);
///   `lfs f30,0x10(r24)` (frame); key loop `lwz r0,(r27)`;
///   `lwz r0,8(r22)`; `lhz r4,4(r22)`; `bl 0x802B4EE0`;
///   `rlwinm r0,r0,2,14,29`; `stfs f1,0x2C(r3)`;
///   `lbz r0,1(r22)`/`lbz r0,0(r22)`; `bl 0x802B4DF0`;
///   `neg`/`or`/`rlwimi` visibility bit; `lwz r12,0(r25)`;
///   `lwz r12,0x30(r12)`; `bcctr 20,0l` (RLVC).
///
/// # Arguments
/// - `this`: animation-target object whose `+0x0C` is the descriptor.
/// - `index`: descriptor-node index in the `desc + 0x10` table.
/// - `target`: object receiving the profile values.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `target + 0x2C + index * 4` floats, the `+0xBB` visibility bit, or
/// dispatches `target`'s `+0x30` slot.
///
/// # Safety
/// The descriptor, the node, the keyframe blocks and `target` must be live.
///
/// # Confidence
/// high - the tag switch, every key offset and the three writes are literal;
/// the tag names are inferred from the four-character immediates.
pub unsafe fn fn_802b5620(this: usize, index: u32, target: usize) {
    let descriptor = platform::read_u32(this + 0x0C) as usize;
    let base = descriptor + platform::read_u32(descriptor + 0x10) as usize;
    let node = descriptor + platform::read_u32(base + index as usize * 4) as usize;
    let count = platform::read_u8(node + 0x14) as usize;
    let mut child_index = 0usize;
    while child_index < count {
        let offset = platform::read_u32(node + 0x18 + child_index * 4) as usize;
        let child = node + offset;
        let frame = platform::read_f32(this + 0x10);
        let keys = platform::read_u8(child + 4) as usize;
        match platform::read_u32(child) {
            D281_TAG_RLPA => {
                for key_index in 0..keys {
                    let key = child + platform::read_u32(child + 0x08 + key_index * 4) as usize;
                    let data = key + platform::read_u32(key + 0x08) as usize;
                    let value = d281_sample_f32(
                        data,
                        platform::read_u16(key + 0x04) as u32,
                        frame,
                    );
                    let at = platform::read_u8(key + 1) as usize * 4;
                    platform::write_f32(target + at + 0x2C, value);
                }
            }
            D281_TAG_RLVI => {
                for key_index in 0..keys {
                    let key = child + platform::read_u32(child + 0x08 + key_index * 4) as usize;
                    let data = key + platform::read_u32(key + 0x08) as usize;
                    let value = d281_sample_u16(
                        data,
                        platform::read_u16(key + 0x04) as u32,
                        frame,
                    ) & 0xFFFF;
                    let flags = platform::read_u8(target + 0xBB) & 0xFE;
                    platform::write_u8(
                        target + 0xBB,
                        flags | if value != 0 { 1 } else { 0 },
                    );
                }
            }
            D281_TAG_RLVC => {
                for key_index in 0..keys {
                    let key = child + platform::read_u32(child + 0x08 + key_index * 4) as usize;
                    let data = key + platform::read_u32(key + 0x08) as usize;
                    let value = d281_sample_f32(
                        data,
                        platform::read_u16(key + 0x04) as u32,
                        frame,
                    ) + platform::read_f32(D281_F_HALF);
                    // observed: `psq_st` writes the single to the scratch word,
                    // then `lbz` takes its most significant byte.
                    let byte = (value.to_bits() >> 24) as u8;
                    virtual2_105(
                        target,
                        0x30,
                        platform::read_u8(key + 1) as u32,
                        byte as u32,
                    );
                }
            }
            _ => {}
        }
        child_index += 1;
    }
}

/// Applies the `RLMC`, `RLTS`, `RLTP` and `RLIM` children of one descriptor
