const FN_801D52E0: usize = 0x801D_52E0;
/// `0x801D5310` - pop one free unit from a unit heap `(heap, size, align)`.
const FN_801D5310: usize = 0x801D_5310;
/// `0x801D53B0` - push one unit back onto the unit-heap free list `(heap, block)`.
const FN_801D53B0: usize = 0x801D_53B0;
/// `0x801D5560` - initialise a MEM allocator for an expanded heap
/// `(allocator, heap, align)`.
const FN_801D5560: usize = 0x801D_5560;
/// `0x801D55A0` - initialise a MEM allocator for a unit heap
/// `(allocator, heap, align)`.
const FN_801D55A0: usize = 0x801D_55A0;
/// `0x801AD4E0` - `OSPanic(file, line, message)`; variadic, floats are saved.
const C290_FN_OS_PANIC: usize = 0x801A_D4E0;
/// `0x8034FD40`: `"eggExpHeap.cpp"`, the assert file name used by the
/// expanded-heap allocator.
const C290_STR_EGG_EXP_HEAP_CPP: usize = 0x8034_FD40;
/// `0x8034FD50`: `"DAME DAME\n"`, the assert message used by the
/// expanded-heap allocator.
const C290_STR_DAME_DAME: usize = 0x8034_FD50;
/// `r13 - 0x4848`: optional hook invoked at the start of a heap `destroy`.
const G_ARC_DESTROY_HOOK: usize = SDA_BASE - 0x4848;

/// Heap object: unaligned backing base stored by the type-A/type-C factories.
const ARC_HEAP_BACKING: usize = 0x14;
/// Heap object: flags halfword tested by the expanded-heap alloc `OSPanic`.
const ARC_HEAP_FLAGS: usize = 0x1C;
/// MEM unit heap: unit-size word at `+0x40` of the heap head (`+0x3C` is the
/// free-list head).
const C290_UNIT_SIZE: usize = 0x40;
/// Heap vtable: the trim method calls the previous heap's resize slot.
const ARC_HEAP_RESIZE_SLOT: usize = 0x20;
/// Heap object: `0x38` bytes of object header before the MEM heap head.
const ARC_HEAP_OBJECT_HEADER: usize = 0x38;

// ---------------------------------------------------------------------------
// Type A - expanded heap (`EXPH`, kind 1), method array `0x8034FD60`
// ---------------------------------------------------------------------------

/// Deleting destructor of the expanded-heap object (type A).
///
/// Releases the client list, destroys the MEM heap head at `+0x10`, runs the
/// base destructor with a non-deleting flag and frees the object only when the
/// caller's flag is positive.
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row for `0x802B92E0`; it is slot 0 of
///   the `ARC_HEAP_VTABLE_A` method array (`0x8034FD60 + 0x08`).
/// - Extent: `0x802B92E0..0x802B9354` (116 bytes, 29 words), ending at the
///   `blr` at `0x802B9350`.
/// - Evidence: `work/dol/main.elf`; `work/wave290/c_bodies.txt`.
/// - observed: `cmpwi cr0,r3,0` guards the whole body; `stw r4,0(r3)` stores
///   the type-A vtable; `bl 0x802B9010`, `lwz r3,16(r30)` + `bl 0x801D4430`,
///   `bl 0x802B8C20` with `li r4,0`, then `cmpwi cr0,r31,0` +
///   `bl 0x802B9280` when `r31 > 0`; `mr r3,r30` before the epilogue.
///
/// # Arguments
/// - `this`: expanded-heap object, or null.
/// - `deleting`: when positive, free `this` through the thread heap.
///
/// # Returns
/// `this`, unchanged.
///
/// # Safety
/// A non-null `this` must be a live type-A heap object; its `+0x10` word must
/// be the MEM heap head returned by the factory.
///
/// # Confidence
/// high - the guard, vtable store, three release calls and free guard are
/// literal.
pub unsafe fn fn_802b92e0(this: usize, deleting: i32) -> u32 {
    if this != 0 {
        platform::write_u32(this, ARC_HEAP_VTABLE_A as u32);
        arc_heap_release_clients(this);
        platform::call1(FN_801D4430, platform::read_u32(this + ARC_HEAP_USER));
        fn_802b8c20(this, 0);
        if deleting > 0 {
            arc_heap_free_object(this as u32);
        }
    }
    this as u32
}

