/// `0x801C8330(index, a, b, c, d)` - writes one TEV alpha word.
const B292_FN_801C8330: usize = 0x801C_8330;
/// `0x801C83D0(index, a, b, c, d, e)` - writes one TEV swap-table word.
const B292_FN_801C83D0: usize = 0x801C_83D0;
/// `0x801C85B0(index, selector)` - writes one TEV constant-alpha selector.
const B292_FN_801C85B0: usize = 0x801C_85B0;
/// `0x801C7D90(p1..p10)` - the ten-argument channel descriptor writer.
const B292_FN_801C7D90: usize = 0x801C_7D90;
/// `0x801C8110(count)` - selects the indirect-stage count.
const B292_FN_801C8110: usize = 0x801C_8110;
/// `0x801C88F0(count)` - selects the punctual-light stage count.
const B292_FN_801C88F0: usize = 0x801C_88F0;
/// `0x801C8040(index, a, b)` - writes one alpha-compare pair.
const B292_FN_801C8040: usize = 0x801C_8040;
/// `0x801C7F40(index, a, b)` - writes one blend-factor pair.
const B292_FN_801C7F40: usize = 0x801C_7F40;
/// `0x801C86C0(a, b, c, d, e)` - writes one GX raster word.
const B292_FN_801C86C0: usize = 0x801C_86C0;
/// `0x801C8DC0(a, b, c, d)` - writes one copy-destination filter word.
const B292_FN_801C8DC0: usize = 0x801C_8DC0;
/// `0x80237C40(angle)` - the sine-like helper of [`fn_802b1d60`].
const B292_FN_80237C40: usize = 0x8023_7C40;
/// `0x80237BD0(angle)` - the cosine-like helper of [`fn_802b1d60`].
const B292_FN_80237BD0: usize = 0x8023_7BD0;

/// `r2 - 0x3458` -> `0x8042FC28`: the four default layout halfwords.
const B292_RLYT_DEFAULTS: usize = SDA2_BASE - 0x3458;

/// `0x8034FAF8` - per-stage TEV constant-colour selectors (`0x1F,0x1B,...`).
const B292_TEV_COLOUR_TABLE: usize = 0x8034_FAF8;
/// `0x8034FB18` - per-stage TEV constant-alpha selectors (`0x1F,0x1B,...`).
const B292_TEV_ALPHA_TABLE: usize = 0x8034_FB18;

/// Calls a ten-argument PPC function (`r3..r10` plus two stack words).
///
/// # Safety
/// `addr` must be a real entry point and every argument valid for it.
unsafe fn b292_call10(
    addr: usize,
    a0: u32,
    a1: u32,
    a2: u32,
    a3: u32,
    a4: u32,
    a5: u32,
    a6: u32,
    a7: u32,
    a8: u32,
    a9: u32,
) -> u32 {
    let f: extern "C" fn(u32, u32, u32, u32, u32, u32, u32, u32, u32, u32) -> u32 =
        core::mem::transmute(addr);
    f(a0, a1, a2, a3, a4, a5, a6, a7, a8, a9)
}

/// Binds the layout material's GX state and draws its records.
///
/// This is slot 1 of `0x8034FB38`. The body reads the packed record counts
/// from `+0x38`, the stage counts from `+0x3C` and the work-buffer base from
/// `+0x40`, then walks the same five parallel sections as the animation-object
/// twin `ui::lyt::fn_801825a0`: the per-stage 4-byte records, the
/// texture-SRT records, the texture descriptors, the material colours and
/// channels, and the long 16-byte stage records. The tail binds the indirect
/// texture stages, the 4-byte filter records, the raster word and the copy
/// filter.
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row and no export for `0x802B3B00`.
/// - Extent: `0x802B3B00..0x802B4908` (3592 bytes, 898 instructions), ending
///   at the `bclr 20,0` at `0x802B4904`; two zero words pad to `0x802B4910`.
/// - Header: `0x8034FB38`; slot 1 of the ten-slot array.
/// - Evidence: `work/wave292/b_span_layout.txt`, `b_dis.mjs`.
/// - observed: `9421FEE0 stwu r1,-0x120(r1)`, `7C0802A6 mflr r0`,
///   `48029241 bl 0x802DCD60` (the 27-register save stub), and the matching
///   `480284B9 bl 0x802DCDAC` epilogue. The body opens with
///   `li r3,1; bl 0x801C6AC0`, then tests `(packed >> 8) & 1`.
/// - observed: the unpacked fields are `packed[28..31]` state count,
///   `packed[24..27]` texture count, `packed[20..23]` 4-byte count,
///   `packed[18..19]` SRT count, `packed[15..17]` filter count,
///   `packed[14]`/`[13]`/`[8]`/`[7]`/`[6]`/`[5]` one-bit flags.
/// - observed: the final value is `r29 & r30` (`cmpwi r29,0`, `cmpwi r30,0`,
///   `li r3,1`).
///
/// # Arguments
/// - `this`: layout material; `+0x10..+0x34` colour words, `+0x38` packed
///   counts, `+0x3C` stage flags, `+0x40` record block.
/// - `flag`: second predicate ANDed into the return value.
/// - `alpha`: scale byte handed to [`fn_802b6b50`] (and the initial
///   `indirect` predicate).
///
/// # Returns
/// `1` when both the tracked-stage predicate and `flag` hold, else `0`.
///
/// # Safety
/// The packed counts must describe a live record block and the GX entry points
/// must be mapped.
///
/// # Confidence
/// medium - every offset, mask, loop bound and GX call is literal; the record
/// section roles are inferred from the identical `ui::lyt` twin.
pub unsafe fn fn_802b3b00(this: usize, flag: u32, alpha: u32) -> u32 {
    let packed = platform::read_u32(this + 0x38);
    let flags = platform::read_u32(this + 0x3C);
    let base = platform::read_u32(this + 0x40) as usize;
    let state_count = ((packed >> 28) & 0xF) as usize;
    let count_18 = ((packed >> 24) & 0xF) as usize;
    let count_14 = ((packed >> 20) & 0xF) as usize;
    let count_12 = ((packed >> 18) & 3) as usize;
    let count_0f = ((packed >> 15) & 7) as usize;
    let bit_14 = ((packed >> 14) & 1) as usize;
    let bit_8 = ((packed >> 8) & 1) as usize;
    let bit_7 = ((packed >> 7) & 1) as usize;
    let bit_6 = ((packed >> 6) & 1) as usize;
    let bit_5 = ((packed >> 5) & 1) as usize;

    let mut predicate = 1u32;
    let mut pattern = 0u32;
    let mut indirect = alpha;
    platform::call1(B292_FN_801C6AC0, 1);

    if (packed >> 8) & 1 != 0 {
        let record = base + count_18 * 0x14 + count_14 * 4 + state_count * 0x1C;
        let first = platform::read_u8(record);
        let second = platform::read_u8(record + 1);
        let _ = platform::call7(B292_FN_801C6AF0, 0, 0, 0, first as u32, 0, 0, 2);
        let _ = platform::call7(B292_FN_801C6AF0, 2, 0, 0, second as u32, 0, 0, 2);
        if first != 1 && second != 1 {
            predicate = 0;
        }
        pattern = u32::from(first == 0 && second == 0);
    } else {
        let _ = platform::call7(B292_FN_801C6AF0, 4, 0, 0, 1, 0, 0, 2);
    }

    let mut bound = u32::from(predicate != 0 && flag != 0);

    if pattern != 0 {
        let mut track = 0xFFFF_FFFFu32;
        if (packed >> 7) & 1 != 0 {
            let record = base
                + count_18 * 0x14
                + count_14 * 4
                + state_count * 0x1C
                + bit_8 * 4;
            track = platform::read_u32(record);
        }
        let mut colour = 0u32;
        fn_802b6b50(
            &mut colour as *mut u32 as usize,
            &track as *const u32 as usize,
            alpha,
        );
        platform::call2(
            B292_FN_801C69E0,
            4,
            &colour as *const u32 as u32,
        );
        bound = 1;
    }

    let mut stages = [0u8; 10];
    let mut processed = 0u32;
    let stage_count = (flags >> 20) & 0xF;
    platform::call1(B292_FN_801C4A20, stage_count);
    if stage_count != 0 {
        let textures = base
            + count_18 * 0x14
            + state_count * 0x1C
            + count_14 * 4
            + bit_8 * 4;
        let mut index = 0usize;
        while index < stage_count as usize {
            let entry = textures + index * 4;
            let first = platform::read_u8(entry);
            let second = platform::read_u8(entry + 1);
            let third = platform::read_u8(entry + 2);
            if first == 1 && third != 60 {
                let scaled = (((third.wrapping_sub(30) as u64) * 0xAAAB_AAABu64) >> 32) as u32
                    >> 1;
                if (scaled as usize) < stages.len() {
                    stages[scaled as usize] = 1;
                }
                processed = 1;
            }
            let _ = platform::call6(
                B292_FN_801C47D0,
                index as u32,
                first as u32,
                second as u32,
                third as u32,
                0,
                125,
            );
            index += 1;
        }
    }

    if processed != 0 {
        let srt = base + state_count * 0x1C;
        let mut matrix = [0u32; 0x60 / 4];
        let mut index = 0usize;
        let mut counter = 0u32;
        while index < stage_count as usize {
            if stages[index] != 0 {
                let record = srt + index * 0x14;
                fn_802b1d60(matrix.as_mut_ptr() as usize, record);
                let _ = platform::call3(
                    B292_FN_801C9A80,
                    matrix.as_mut_ptr() as u32,
                    index.wrapping_mul(3).wrapping_add(30) as u32,
                    1,
                );
            }
            counter = counter.wrapping_add(1);
            index += 1;
        }
        // observed: the stage loop shares `r28` with the later indirect gate.
        indirect = counter;
    }

    if (flags >> 28) & 0xF != 0 {
        let count = ((flags >> 28) & 0xF) as usize;
        let mut small_index = 0u32;
        let mut large_index = 16u32;
        let mut index = 0usize;
        while index < count {
            let record = base + index * 0x1C;
            let mut texobj = [0u32; 8];
            fn_802b4b50(record, texobj.as_mut_ptr() as u32);
            let kind = (platform::read_u32(record + 0x18) >> 28) & 0xF;
            if (8..=10).contains(&kind) {
                let slot = if kind == 10 {
                    let value = large_index;
                    large_index = large_index.wrapping_add(1);
                    value
                } else {
                    let value = small_index;
                    small_index = small_index.wrapping_add(1);
                    value
                };
                // observed: `r28` is the slot value and survives as the later
                // indirect-stage gate.
                indirect = slot;
                let _ = platform::call2(B292_FN_801C7120, texobj.as_mut_ptr() as u32, slot);
                let mut attr = [0u32; 4];
                fn_802b4c40(record, attr.as_mut_ptr() as u32);
                let _ = platform::call2(B292_FN_801C7550, attr.as_mut_ptr() as u32, slot);
            }
            let _ = platform::call2(
                B292_FN_801C74C0,
                texobj.as_mut_ptr() as u32,
                index as u32,
            );
            index += 1;
        }
    }

    let colour_pairs: [usize; 3] = [0x10, 0x18, 0x20];
    for (position, offset) in colour_pairs.iter().enumerate() {
        let _ = platform::call2(
            B292_FN_801C8490,
            position as u32 + 1,
            (this + offset) as u32,
        );
    }
    let colour_words: [usize; 4] = [0x28, 0x2C, 0x30, 0x34];
    for (position, offset) in colour_words.iter().enumerate() {
        let _ = platform::call2(B292_FN_801C8500, position as u32, (this + offset) as u32);
    }

    if (packed >> 14) & 1 != 0 {
        let record = base
            + count_18 * 0x14
            + state_count * 0x1C
            + count_14 * 4
            + (bit_7 + bit_8) * 4;
        let mut index = 0usize;
        while index < 4 {
            let value = platform::read_u8(record + index);
            let _ = platform::call5(
                B292_FN_801C8640,
                index as u32,
                (value & 3) as u32,
                ((value >> 1) & 3) as u32,
                ((value >> 2) & 3) as u32,
                ((value >> 3) & 3) as u32,
            );
            index += 1;
        }
    } else {
        let _ = platform::call5(B292_FN_801C8640, 0, 0, 1, 2, 3);
        let _ = platform::call5(B292_FN_801C8640, 1, 0, 0, 0, 3);
        let _ = platform::call5(B292_FN_801C8640, 2, 1, 1, 1, 3);
        let _ = platform::call5(B292_FN_801C8640, 3, 2, 2, 2, 3);
    }

    let mut stage_mark = [0u8; 3];
    let long_count = (flags >> 9) & 0x1F;
    if long_count != 0 {
        platform::call1(B292_FN_801C88F0, long_count);
        let record = base
            + (count_12 + count_18) * 0x14
            + state_count * 0x1C
            + (count_14 + bit_8 + bit_7 + bit_14 + bit_6 + bit_5 + count_0f) * 4;
        let mut index = 0usize;
        while index < long_count as usize {
            let entry = record + index * 16;
            let b0 = platform::read_u8(entry);
            let b1 = platform::read_u8(entry + 1);
            let b2 = platform::read_u8(entry + 2);
            let b3 = platform::read_u8(entry + 3);
            let _ = platform::call4(
                B292_FN_801C8790,
                index as u32,
                b0 as u32,
                (b2 as u32) | ((b3 as u32 & 1) << 8),
                b1 as u32,
            );
            let _ = platform::call3(
                B292_FN_801C8600,
                index as u32,
                ((b3 >> 1) & 3) as u32,
                ((b3 >> 3) & 3) as u32,
            );
            let b4 = platform::read_u8(entry + 4);
            let b5 = platform::read_u8(entry + 5);
            let _ = platform::call5(
                B292_FN_801C82F0,
                index as u32,
                (b4 & 0xF) as u32,
                ((b4 >> 4) & 0xF) as u32,
                (b5 & 0xF) as u32,
                ((b5 >> 4) & 0xF) as u32,
            );
            let b6 = platform::read_u8(entry + 6);
            let b7 = platform::read_u8(entry + 7);
            let _ = platform::call6(
                B292_FN_801C8370,
                index as u32,
                (b6 & 0xF) as u32,
                ((b6 >> 4) & 3) as u32,
                ((b6 >> 6) & 3) as u32,
                (b7 & 1) as u32,
                ((b7 >> 1) & 3) as u32,
            );
            let _ = platform::call2(B292_FN_801C8560, index as u32, ((b7 >> 3) & 0x1F) as u32);
            let b8 = platform::read_u8(entry + 8);
            let b9 = platform::read_u8(entry + 9);
            let _ = platform::call5(
                B292_FN_801C8330,
                index as u32,
                (b8 & 0xF) as u32,
                ((b8 >> 4) & 0xF) as u32,
                (b9 & 0xF) as u32,
                ((b9 >> 4) & 0xF) as u32,
            );
            let b10 = platform::read_u8(entry + 10);
            let b11 = platform::read_u8(entry + 11);
            let _ = platform::call6(
                B292_FN_801C83D0,
                index as u32,
                (b10 & 0xF) as u32,
                ((b10 >> 4) & 3) as u32,
                ((b10 >> 6) & 3) as u32,
                (b11 & 1) as u32,
                ((b11 >> 1) & 3) as u32,
            );
            let _ = platform::call2(B292_FN_801C85B0, index as u32, ((b11 >> 3) & 0x1F) as u32);
            let b12 = platform::read_u8(entry + 12);
            let b13 = platform::read_u8(entry + 13);
            let b14 = platform::read_u8(entry + 14);
            let b15 = platform::read_u8(entry + 15);
            let scale = ((b13 >> 3) & 0xF) as u32;
            let _ = b292_call10(
                B292_FN_801C7D90,
                index as u32,
                b12 as u32,
                (b13 & 7) as u32,
                scale,
                (b14 & 7) as u32,
                (b15 & 3) as u32,
                ((b14 >> 3) & 7) as u32,
                ((b15 >> 2) & 1) as u32,
                ((b15 >> 3) & 1) as u32,
                ((b15 >> 4) & 3) as u32,
            );
            if (1..=3).contains(&scale) {
                stage_mark[scale as usize - 1] = 1;
                indirect = 1;
            }
            index += 1;
        }
        // observed: `3BA00001 addi r29,1` at `0x802B4250`, after the loop.
        bound = 1;
    } else {
        let material_count = (flags >> 28) & 0xF;
        let mut stage = 0u32;
        let mut check_defaults = false;
        let mut clamp_bound_stage = true;
        if material_count == 0 {
            let _ = platform::call4(B292_FN_801C8790, 0, 0, 0xFF, 0xFF);
            let _ = platform::call5(B292_FN_801C82F0, 0, 0xF, 4, 10, 0xF);
            let _ = platform::call5(B292_FN_801C8330, 0, 7, 2, 5, 7);
            bound = 1;
            stage = 1;
            clamp_bound_stage = false;
        } else if material_count == 1 {
            let _ = platform::call4(B292_FN_801C8790, 0, 0, 0, 0xFF);
            let _ = platform::call5(B292_FN_801C82F0, 0, 2, 4, 8, 0xF);
            let _ = platform::call5(B292_FN_801C8330, 0, 1, 2, 4, 7);
            stage = 1;
        } else if material_count == 2 {
            let _ = platform::call4(B292_FN_801C8790, 0, 0, 0, 0xFF);
            let _ = platform::call5(B292_FN_801C82F0, 0, 0xF, 0xF, 0xF, 8);
            let _ = platform::call5(B292_FN_801C8330, 0, 7, 7, 7, 4);
            let _ = platform::call4(B292_FN_801C8790, 1, 1, 1, 0xFF);
            let _ = platform::call5(B292_FN_801C82F0, 1, 8, 0, 14, 0xF);
            let _ = platform::call5(B292_FN_801C8330, 1, 4, 0, 6, 7);
            let _ = platform::call2(
                B292_FN_801C8560,
                1,
                platform::read_u32(B292_TEV_COLOUR_TABLE),
            );
            let _ = platform::call2(
                B292_FN_801C85B0,
                1,
                platform::read_u32(B292_TEV_ALPHA_TABLE),
            );
            stage = 2;
            check_defaults = true;
        } else {
            let mut index = 0u32;
            while index < material_count {
                let stage_index = stage & 0xFF;
                let _ = platform::call4(B292_FN_801C8790, stage_index, index, index, 0xFF);
                let _ = platform::call5(B292_FN_801C82F0, stage_index, 0xF, 8, 14, 0xF);
                let _ = platform::call6(
                    B292_FN_801C8330,
                    stage_index,
                    7,
                    4,
                    6,
                    7,
                    if index == 0 { 7 } else { 0 },
                );
                let _ = platform::call2(
                    B292_FN_801C8560,
                    stage_index,
                    platform::read_u32(B292_TEV_COLOUR_TABLE + index as usize * 4),
                );
                let _ = platform::call2(
                    B292_FN_801C85B0,
                    stage_index,
                    platform::read_u32(B292_TEV_ALPHA_TABLE + index as usize * 4),
                );
                stage = stage.wrapping_add(1);
                index += 1;
            }
            check_defaults = true;
        }

        if check_defaults {
            let default_colours = (0..4).all(|i| {
                (platform::read_u16(this + 0x10 + i * 2) as i16)
                    == (platform::read_u16(B292_RLYT_DEFAULTS + i * 2) as i16)
            });
            let alpha_full =
                (0..4).all(|i| (platform::read_u16(this + 0x18 + i * 2) as i16) == 255);
            let skip = default_colours && alpha_full;
            if !skip {
                let stage_index = stage & 0xFF;
                let _ = platform::call4(B292_FN_801C8790, stage_index, 0xFF, 0xFF, 0xFF);
                let _ = platform::call5(B292_FN_801C82F0, stage_index, 2, 4, 0, 0xF);
                let _ = platform::call5(B292_FN_801C8330, stage_index, 1, 2, 0, 7);
                stage = stage.wrapping_add(1);
            }
        }
        if clamp_bound_stage && bound != 0 {
            let stage_index = stage & 0xFF;
            let _ = platform::call4(B292_FN_801C8790, stage_index, 0xFF, 0xFF, 4);
            let _ = platform::call5(B292_FN_801C82F0, stage_index, 0xF, 0, 10, 0xF);
            let _ = platform::call5(B292_FN_801C8330, stage_index, 7, 0, 5, 7);
            stage = stage.wrapping_add(1);
        }
        let final_stage = stage & 0xFF;
        let mut index = 0u32;
        while index < final_stage {
            let _ = platform::call6(B292_FN_801C8370, index, 0, 0, 0, 1, 0);
            let _ = platform::call6(B292_FN_801C83D0, index, 0, 0, 0, 1, 0);
            let _ = platform::call1(B292_FN_801C8110, index);
            let _ = platform::call3(B292_FN_801C8600, index, 0, 0);
            index += 1;
        }
        let _ = platform::call1(B292_FN_801C88F0, final_stage);
    }

    if indirect != 0 {
        let angle_scale = platform::read_f32(SDA2_802B1D60_ANGLE);
        let record = base
            + count_18 * 0x14
            + state_count * 0x1C
            + (count_14 + bit_14 + bit_6 + bit_7 + bit_8 + count_0f + bit_5) * 4;
        let mut index = 0usize;
        while index < ((flags >> 18) & 3) as usize {
            if stage_mark[index] != 0 {
                let angle = platform::read_f32(record + index * 0x14 + 8);
                let scaled = (angle_scale * angle) as f64;
                let sine = call_double(B292_FN_80237C40, scaled) as f32;
                let cosine = call_double(B292_FN_80237BD0, scaled) as f32;
                let mut matrix = [0f32; 6];
                matrix[0] = sine * platform::read_f32(record + index * 0x14 + 0x0C);
                matrix[1] = -cosine * platform::read_f32(record + index * 0x14 + 0x10);
                matrix[2] = platform::read_f32(record + index * 0x14);
                matrix[3] = cosine * platform::read_f32(record + index * 0x14 + 0x0C);
                matrix[4] = sine * platform::read_f32(record + index * 0x14 + 0x10);
                matrix[5] = platform::read_f32(record + index * 0x14 + 4);
                fn_802b1e70(index as u32 + 1, matrix.as_mut_ptr() as usize);
            }
            index += 1;
        }
    }

    let small_count = (flags >> 15) & 7;
    platform::call1(B292_FN_801C8110, small_count);
    if small_count != 0 {
        let record = base
            + count_18 * 0x14
            + state_count * 0x1C
            + (count_14 + bit_14 + bit_6 + bit_7 + bit_8 + count_0f + bit_5) * 4;
        let mut index = 0usize;
        while index < small_count as usize {
            let entry = record + index * 4;
            let _ = platform::call3(
                B292_FN_801C8040,
                index as u32,
                platform::read_u8(entry) as u32,
                platform::read_u8(entry + 1) as u32,
            );
            let _ = platform::call3(
                B292_FN_801C7F40,
                index as u32,
                platform::read_u8(entry + 2) as u32,
                platform::read_u8(entry + 3) as u32,
            );
            index += 1;
        }
    }

    if (packed >> 6) & 1 != 0 {
        let record = base
            + count_18 * 0x14
            + state_count * 0x1C
            + (count_14 + bit_14 + bit_7 + bit_8) * 4;
        let first = platform::read_u8(record);
        let _ = platform::call5(
            B292_FN_801C86C0,
            (first & 0xF) as u32,
            platform::read_u8(record + 2) as u32,
            platform::read_u8(record + 1) as u32,
            ((first >> 4) & 0xF) as u32,
            platform::read_u8(record + 3) as u32,
        );
    } else {
        let _ = platform::call5(B292_FN_801C86C0, 7, 0, 0, 7, 0);
    }

    if (packed >> 5) & 1 != 0 {
        let record = base
            + count_18 * 0x14
            + state_count * 0x1C
            + (count_14 + bit_14 + bit_6 + bit_7 + bit_8) * 4;
        let _ = platform::call4(
            B292_FN_801C8DC0,
            platform::read_u8(record) as u32,
            platform::read_u8(record + 1) as u32,
            platform::read_u8(record + 2) as u32,
            platform::read_u8(record + 3) as u32,
        );
    } else {
        let _ = platform::call4(B292_FN_801C8DC0, 1, 4, 5, 0xF);
    }

    u32::from(bound != 0 && predicate != 0)
}

/// Forwards `(other, this, 0)` to `other`'s virtual slot `+0x18`.
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row for `0x802B4910`.
/// - Extent: `0x802B4910..0x802B4930` (32 bytes, 8 words), ending at the
///   `bcctr 20,0` at `0x802B492C`; two zero words pad to `0x802B4938`.
/// - Header: `0x8034FB38`; slot 2.
/// - Evidence: `work/wave292/b_span_layout.txt`.
/// - observed: `81840000 lwz r12,0(r4)`; `7C601B78 or r0,r3,r3`;
///   `7C832378 or r3,r4,r4`; `38A00000 li r5,0`; `818C0018 lwz r12,24(r12)`;
///   `7C040378 or r4,r0,r0`; `4E800420 bcctr 20,0`.
///
/// # Arguments
