/// Finds the `+0x04` ring node whose `+0x08` word equals `key`.
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row for `0x802B4A20`.
/// - Extent: `0x802B4A20..0x802B4A28` (8 bytes, 2 words).
/// - Header: `0x8034FB38`; slot 6.
/// - Evidence: `work/wave292/b_span_layout.txt`.
/// - observed: `38630004 addi r3,r3,4`; `4800187C b 0x802B62A0`, whose body
///   walks `next = *(node)` from the sentinel and returns the node where
///   `*(node+8) == r4`, else 0.
///
/// # Arguments
/// - `this`: layout owner; the ring sentinel is `this + 4`.
/// - `key`: node key compared against `+0x08`.
///
/// # Returns
/// The matching node address, or 0.
///
/// # Safety
/// `this + 4` must be the sentinel of a live ring.
///
/// # Confidence
/// high - the thunk and the inlined 0x802B62A0 walk are literal.
pub unsafe fn fn_802b4a20(this: usize, key: u32) -> u32 {
    let sentinel = this + 0x04;
    let mut node = platform::read_u32(sentinel) as usize;
    while node != sentinel {
        if platform::read_u32(node + 0x08) == key {
            return node as u32;
        }
        node = platform::read_u32(node) as usize;
    }
    0
}

/// Finds the `+0x04` ring node whose child's `+0x0C` word equals
/// `descriptor->+0x04`.
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row for `0x802B4A30`.
/// - Extent: `0x802B4A30..0x802B4A38` (8 bytes, 2 words).
/// - Header: `0x8034FB38`; slot 7.
/// - Evidence: `work/wave292/b_span_layout.txt`.
/// - observed: `38630004 addi r3,r3,4`; `480018AC b 0x802B62E0`, whose body
///   compares `*(*(node+8)+0x0C)` with `*(descriptor+4)`.
///
/// # Arguments
/// - `this`: layout owner; the ring sentinel is `this + 4`.
/// - `descriptor`: record whose `+0x04` word is the key.
///
/// # Returns
/// The matching node address, or 0.
///
/// # Safety
/// The ring and `descriptor + 4` must be readable.
///
/// # Confidence
/// high - the thunk and the inlined 0x802B62E0 walk are literal.
pub unsafe fn fn_802b4a30(this: usize, descriptor: usize) -> u32 {
    let target = platform::read_u32(descriptor + 0x04);
    let sentinel = this + 0x04;
    let mut node = platform::read_u32(sentinel) as usize;
    while node != sentinel {
        let child = platform::read_u32(node + 0x08) as usize;
        if platform::read_u32(child + 0x0C) == target {
            return node as u32;
        }
        node = platform::read_u32(node) as usize;
    }
    0
}

